/* The Quant Curriculum — extracted verbatim from the original
   single-file build. Source blocks [15, 16, 17]. Do not reorder: these
   run in document order and several set shared globals. */
window.__GLOSS__={"alpha":{"t":"alpha","d":"Return that is not explained by simply taking known risks. If a strategy makes 12% and its market exposure alone would have made 10%, the alpha is the other 2%.","r":"5","vid":"vol5"},"autocorrelation":{"t":"autocorrelation","d":"Whether a series is related to its own past. Returns have almost none; the <em>size</em> of returns has a lot, which is why calm weeks follow calm weeks.","r":"4","vid":"vol4"},"basis-point":{"t":"basis point","d":"One hundredth of one percent. A 10 bp cost on £100,000 is £100. Trading costs are quoted this way because the numbers are otherwise all zeroes.","r":null},"bayesian":{"t":"Bayesian","d":"Working with a whole range of plausible values and how confident you are in each, rather than a single best guess. You start with a belief and the data updates it.","r":"4A","vid":"vol4a"},"beta":{"t":"beta","d":"How much something moves when the market moves. Beta 1.5 means it tends to move one and a half times as far, in the same direction.","r":"5","vid":"vol5"},"bootstrap":{"t":"bootstrap","d":"Re-sampling your own data many times over to see how much a result would wobble if history had gone slightly differently.","r":"12","vid":"vol12"},"brownian":{"t":"Brownian motion","d":"The standard mathematical model of a completely unpredictable wandering path. Its defining property: over a short interval it moves by about the square root of the time elapsed.","r":"1","vid":"vol1"},"clt":{"t":"central limit theorem","d":"Averages of many independent things end up bell-shaped, whatever the individual things looked like. It is why standard errors exist — and it says nothing about the extreme tails.","r":"0A","vid":"vol0a"},"cointegration":{"t":"cointegration","d":"Two prices that each wander unpredictably, but whose difference keeps returning to a normal level. The difference is the tradeable thing; neither price is.","r":"3","vid":"vol3"},"condition-number":{"t":"condition number","d":"How much a matrix magnifies small errors. A condition number of 10¹³ means you lose about thirteen of your sixteen digits of accuracy when you invert it.","r":"0A","vid":"vol0a"},"convexity":{"t":"convexity","d":"Curvature. A convex position gains more when things move one way than it loses when they move equally the other way — which is a real, priced advantage, not an accounting quirk.","r":"13A","vid":"vol13a"},"covariance":{"t":"covariance","d":"How two things move together, in raw units. Divide it by both volatilities and you get correlation, which is the same information on a −1 to +1 scale.","r":"0A","vid":"vol0a"},"cross-validation":{"t":"cross-validation","d":"Holding back part of your data, fitting on the rest, and scoring on what you held back. On financial data the ordinary version leaks, because observations overlap in time.","r":"6","vid":"vol6"},"eigenvalue":{"t":"eigenvalue","d":"A direction a matrix only stretches rather than rotates, and how much it stretches it. For a covariance matrix, each one is an independent source of risk and its size is how much risk.","r":"0A","vid":"vol0a"},"estimator":{"t":"estimator","d":"A recipe for guessing something you cannot observe, from data you can. It is itself random: run it on a different sample and you get a different answer.","r":"0A","vid":"vol0a"},"filtration":{"t":"filtration","d":"The formal bookkeeping for “what was knowable at each moment”. A strategy is <em>adapted</em> when every decision uses only information that already existed — which is the precise definition of no lookahead.","r":"1","vid":"vol1"},"heteroscedasticity":{"t":"heteroscedasticity","d":"Variance that changes over time. Financial returns are strongly heteroscedastic — volatility clusters — which is why the textbook standard errors are wrong.","r":"0A","vid":"vol0a"},"iid":{"t":"i.i.d.","d":"Independent and identically distributed: each observation is unrelated to the others and drawn from the same distribution. Most textbook statistics assume it; returns rarely satisfy it.","r":"0A","vid":"vol0a"},"ic":{"t":"information coefficient","d":"How well a forecast ranks what actually happened, measured as a rank correlation. An IC of 0.03 to 0.05 is a genuinely usable trading signal — the bar is much lower than intuition suggests.","r":"5","vid":"vol5"},"jensen":{"t":"Jensen's inequality","d":"The average of a curved function is not the function of the average. It is why an option is worth more than its value at the expected price, and why compounding is not the same as averaging.","r":"0A","vid":"vol0a"},"kurtosis":{"t":"kurtosis","d":"How heavy the extremes are. Daily equity returns have far heavier extremes than a bell curve, so a “five-sigma” day happens vastly more often than the bell curve says.","r":"0A","vid":"vol0a"},"likelihood":{"t":"likelihood","d":"How probable your observed data would be under a given set of parameters. Maximum likelihood picks the parameters that make what you saw least surprising.","r":"0A","vid":"vol0a"},"martingale":{"t":"martingale","d":"A process whose best forecast of tomorrow is exactly its value today. Prices are close to martingales, which is a precise way of saying returns are close to unpredictable.","r":"1","vid":"vol1"},"mean-reversion":{"t":"mean reversion","d":"A tendency to be pulled back toward a normal level after moving away from it. The key number is the half-life: how long it takes to close half the gap.","r":"1","vid":"vol1"},"monte-carlo":{"t":"Monte Carlo","d":"Answering a question by simulating it thousands of times and counting the outcomes, instead of solving it with algebra.","r":"1","vid":"vol1"},"p-value":{"t":"p-value","d":"How surprising your result would be if there were no real effect. It is <em>not</em> the probability that your result is real — that needs a prior, and the two often differ by a lot.","r":"0A","vid":"vol0a"},"pca":{"t":"principal component analysis","d":"Finding the handful of independent directions that account for most of the movement in a large set of correlated series. For equities, the first one is usually just “the market”.","r":"0A","vid":"vol0a"},"psd":{"t":"positive semi-definite","d":"The property a valid covariance matrix must have: no portfolio can be assigned a negative variance. Break it and an optimiser will find the impossible direction and put everything in it.","r":"0A","vid":"vol0a"},"posterior":{"t":"posterior","d":"Your belief after seeing the data. The <em>prior</em> is your belief before. Both are distributions, not single numbers, which is the whole point.","r":"4A","vid":"vol4a"},"quantile":{"t":"quantile","d":"The value below which a given fraction of outcomes fall. The 5% quantile of daily returns is the loss you exceed on one day in twenty.","r":"12","vid":"vol12"},"random-walk":{"t":"random walk","d":"A path whose next step is unrelated to every previous step. Prices are close to this, which is why regressing one price on another produces impressive nonsense.","r":"3","vid":"vol3"},"residual":{"t":"residual","d":"What a model failed to explain: actual minus predicted. Most diagnostics are really questions about whether the residuals still contain a pattern.","r":"0A","vid":"vol0a"},"shrinkage":{"t":"shrinkage","d":"Deliberately pulling a noisy estimate toward something simpler and steadier. It makes the estimate biased and, in high dimensions, reliably more accurate out of sample.","r":"11","vid":"vol11"},"sigma-algebra":{"t":"σ-algebra","d":"The list of questions you are allowed to assign probabilities to. In trading it becomes the bookkeeping for what is known at each moment.","r":"1","vid":"vol1"},"skewness":{"t":"skewness","d":"Lopsidedness. Negative skew means many small gains and occasional large losses — the shape of most option-selling and carry strategies.","r":"12","vid":"vol12"},"standard-error":{"t":"standard error","d":"How much your estimate would move if you ran it on a different sample. If the standard error is as large as the estimate, you have measured nothing.","r":"0A","vid":"vol0a"},"stationary":{"t":"stationary","d":"A series whose statistical behaviour does not drift over time. Prices are not stationary; returns roughly are. Most statistics only work on the second kind.","r":"3","vid":"vol3"},"t-statistic":{"t":"t-statistic","d":"Your estimate divided by its own standard error — how many “measurement widths” it sits from zero. Roughly 2 is the conventional bar and 3 is the honest one once you have tried several ideas.","r":"0A","vid":"vol0a"},"unit-root":{"t":"unit root","d":"The formal signature of a random walk — no pull back toward any level. Testing for it is the first step before regressing any two price series on each other.","r":"3","vid":"vol3"},"var-stat":{"t":"variance","d":"Volatility squared. It is the quantity that adds up nicely across independent things, which is why the mathematics is written in variance and the reporting in volatility.","r":"0A","vid":"vol0a"},"adverse-selection":{"t":"adverse selection","d":"The people who take your resting order are disproportionately the ones who know something you do not. It is why quoting a spread is not free money.","r":"2","vid":"vol2"},"arbitrage":{"t":"arbitrage","d":"A profit with no risk and no capital at stake. Genuine ones are rare and short-lived; most things called arbitrage are a risk you have decided you understand.","r":"1","vid":"vol1"},"ask":{"t":"the ask","d":"The lowest price anyone is currently willing to sell at. Buy immediately and this is what you pay.","r":"2","vid":"vol2"},"backtest":{"t":"backtest","d":"Running a strategy over historical data to see what it would have done. Almost every way of getting it wrong makes the result look better, not worse.","r":"16","vid":"vol16"},"backwardation":{"t":"backwardation","d":"When futures for later delivery cost less than the current price. Holding the future then earns you money as it rolls up toward spot.","r":"13A","vid":"vol13a"},"bid":{"t":"best bid","d":"The highest price anyone is currently willing to buy at. Sell immediately and this is what you get.","r":"2","vid":"vol2"},"borrow":{"t":"stock borrow","d":"The fee for renting shares so you can sell them short. On the names a short signal actually picks it can be several percent a year, not the flat 40 bp most backtests assume.","r":"19A","vid":"vol19a"},"capacity":{"t":"capacity","d":"The most money a strategy can run before its own market impact eats the edge. For an individual this is an advantage: strategies that cap out at $20m are not worth a large fund's time.","r":"19A","vid":"vol19a"},"carry":{"t":"carry trade","d":"What you earn if the price simply does not move — the interest differential, the dividend, the roll down a curve. Reliable for long stretches, then occasionally violent.","r":"13","vid":"vol13"},"contango":{"t":"contango","d":"When futures for later delivery cost more than the current price. Holding the future then loses money as it rolls down toward spot.","r":"13A","vid":"vol13a"},"cross-impact":{"t":"cross-impact","d":"Trading one asset moves the price of correlated assets too. Invisible in any single-name cost model, and often the majority of a portfolio's real cost.","r":"2A","vid":"vol2a"},"delta":{"t":"delta","d":"How much an option's value changes when the underlying moves by one unit. Hedging it away leaves you with a bet on volatility rather than direction.","r":"8","vid":"vol8"},"drawdown":{"t":"drawdown","d":"How far you are below your best-ever level. It is the risk measure that actually ends careers, and a good strategy spends most of its life in one.","r":"12","vid":"vol12"},"dv01":{"t":"DV01","d":"How much a bond position gains or loses if yields move one basis point, in cash. Unlike duration it adds up across instruments, which is why rates books are risked in it.","r":"13A","vid":"vol13a"},"duration":{"t":"modified duration","d":"How sensitive a bond's price is to interest rates, expressed in years. A 7-year duration means roughly a 7% price fall if yields rise 1%.","r":"13A","vid":"vol13a"},"factor":{"t":"factor model","d":"A shared driver that many assets respond to — the market itself, company size, value, momentum. Most of what looks like a new signal turns out to be exposure to one of these.","r":"5","vid":"vol5"},"fill":{"t":"fill model","d":"An executed trade, or part of one. How a backtest decides when your orders fill is usually a bigger determinant of the result than the strategy itself.","r":"16","vid":"vol16"},"gamma":{"t":"gamma","d":"How fast delta changes as the price moves. It is the actual profit and loss of a hedged option position: you earn when the market moves more than implied volatility said it would.","r":"8","vid":"vol8"},"high-water-mark":{"t":"high-water mark","d":"The highest value your account has ever reached. Drawdown is measured from it, and most fee structures and stopping rules key off it.","r":"12","vid":"vol12"},"implied-volatility":{"t":"implied volatility","d":"The volatility figure that makes an option's model price equal its market price. It is a quoting convention, and it runs persistently above what actually gets realised.","r":"8","vid":"vol8"},"information-ratio":{"t":"information ratio","d":"Like a Sharpe ratio but measured against a benchmark instead of cash. It answers: per unit of risk taken away from the benchmark, how much did you add?","r":"5","vid":"vol5"},"kelly":{"t":"Kelly criterion","d":"The bet size that maximises long-run growth — expected return divided by variance. Betting twice it has a growth rate of zero, so every error should be on the low side.","r":"12","vid":"vol12"},"leverage":{"t":"leverage","d":"Controlling more exposure than you have capital for, by borrowing. It multiplies returns and losses equally, and it multiplies the chance of being forced out at the worst moment.","r":"19A","vid":"vol19a"},"limit-order":{"t":"limit order","d":"An order to trade only at a stated price or better. It may never fill — and when it does, it is often because someone better informed wanted the other side.","r":"2","vid":"vol2"},"liquidity":{"t":"liquidity","d":"How much you can trade without moving the price. It is not a fixed property: it evaporates precisely when everyone wants it.","r":"2","vid":"vol2"},"lookahead":{"t":"lookahead","d":"Using information in a backtest that did not exist yet. The single most common way a strategy looks profitable and is not.","r":"15","vid":"vol15"},"margin":{"t":"portfolio margin","d":"Cash the broker holds against your positions. The trap is that requirements rise when markets get volatile — that is, exactly when your equity is falling.","r":"19A","vid":"vol19a"},"market-maker":{"t":"market maker","d":"Someone who quotes both a buy and a sell price and earns the spread between them, in exchange for taking the other side of whoever arrives.","r":"2","vid":"vol2"},"market-order":{"t":"market order","d":"An order to trade immediately at whatever the best available price is. Certain to fill, uncertain in price.","r":"2","vid":"vol2"},"metaorder":{"t":"metaorder","d":"One large trading decision, split into thousands of small child orders. Market impact is a property of the parent decision, not of the individual pieces.","r":"2A","vid":"vol2a"},"microprice":{"t":"microprice","d":"A better “current price” than the midpoint: it weights the bid and ask by how much size is resting on each side, because the thin side is where the price is going.","r":"2A","vid":"vol2a"},"mid-price":{"t":"mid-price","d":"The average of the best bid and best ask. Convenient, and not actually where the price is heading when one side of the book is much thicker.","r":"2","vid":"vol2"},"momentum":{"t":"momentum","d":"The tendency of what has been going up to keep going up, over horizons of months. One of the most persistent documented effects, and it fails abruptly at turning points.","r":"13","vid":"vol13"},"notional":{"t":"notional","d":"The face value of a position — what it controls, rather than what it cost you. A futures contract can have a small margin and a very large notional.","r":"13A","vid":"vol13a"},"order-book":{"t":"order book","d":"The live list of everyone's resting buy and sell orders at each price. Where your order sits in that queue determines whether you get filled on good terms or bad.","r":"2","vid":"vol2"},"participation-rate":{"t":"participation rate","d":"What fraction of the day's trading volume you are. It is the variable that sets your market impact — absolute size on its own says nothing.","r":"2A","vid":"vol2a"},"point-in-time":{"t":"point-in-time","d":"Data joined to the date it actually became public, not the date it describes. Company earnings as reported today are not what was known back then.","r":"15","vid":"vol15"},"prime-broker":{"t":"prime brokerage","d":"The bank that holds a fund's assets, lends it money and shares, and nets its margin across positions. The threshold at which a hedged book becomes economically viable.","r":"19A","vid":"vol19a"},"queue-position":{"t":"queue position","d":"Where your resting order sits in line at a price. At the front you fill often and on your terms; at the back, mainly when the price is about to move against you.","r":"2","vid":"vol2"},"repo":{"t":"repo","d":"Borrowing cash against a bond overnight. The repo rate is the real financing cost of a bond position, and the reason futures carry is what it is.","r":"13A","vid":"vol13a"},"roll":{"t":"roll yield","d":"Closing an expiring futures contract and opening the next one. Doing the historical version wrong produces a backtest whose entire edge sits on roll dates.","r":"13A","vid":"vol13a"},"sharpe":{"t":"Sharpe ratio","d":"Return divided by volatility, annualised. Its most useful property is hidden: multiply by the square root of the track record in years and you get a t-statistic.","r":"0A","vid":"vol0a"},"short":{"t":"short selling","d":"Selling something you do not own, having borrowed it, hoping to buy it back cheaper. You pay to borrow, and the lender can demand it back at the worst moment.","r":"19A","vid":"vol19a"},"slippage":{"t":"slippage","d":"The gap between the price you expected and the price you got. Measure it against the price at the moment you decided, not against the day's average, which your own trading contaminates.","r":"10","vid":"vol10"},"spread":{"t":"bid-ask spread","d":"The gap between the best buy and best sell price. Cross it and you have paid half of it immediately — before any other cost.","r":"2","vid":"vol2"},"survivorship":{"t":"survivorship bias","d":"Testing a strategy on the companies that still exist today. The ones that went bankrupt are missing, and they were the losses.","r":"15","vid":"vol15"},"turnover":{"t":"turnover","d":"How much you trade relative to the size of the portfolio, per year. Turnover of 4× at 10 bp a trade is 40 bp a year of cost — often a third of the whole edge.","r":"19A","vid":"vol19a"},"var":{"t":"value at risk","d":"The loss you expect to exceed a given fraction of the time. It has two serious flaws: it says nothing about how bad things get beyond it, and it can punish diversification.","r":"12","vid":"vol12"},"volatility":{"t":"volatility","d":"How much something moves around, as an annualised percentage. 20% volatility means a typical year's range is roughly plus or minus 20%.","r":"0A","vid":"vol0a"},"vol-targeting":{"t":"volatility targeting","d":"Scaling position size up when markets are calm and down when they are turbulent, to keep risk steady. It does more of the work in a trend strategy than the trend signal does.","r":"13","vid":"vol13"},"vwap":{"t":"VWAP","d":"The volume-weighted average price over a period. A common execution benchmark, and a poor one if you were a large share of that volume yourself.","r":"10","vid":"vol10"},"deflated-sharpe":{"t":"deflated Sharpe ratio","d":"A Sharpe ratio corrected for how many strategies you tried. Testing a hundred worthless ideas produces a best-of Sharpe near 3.0 from noise alone.","r":"18","vid":"vol18"},"meta-labelling":{"t":"meta-labelling","d":"Letting one model pick the direction and a second decide whether to act and how big. The second question is much easier than the first, which is why the split helps.","r":"6","vid":"vol6"},"overfitting":{"t":"overfitting","d":"Finding a pattern that describes your sample and not the world. Careful, rigorous execution of an overfitting procedure is still overfitting — and it feels like diligence throughout.","r":"18","vid":"vol18"},"purging":{"t":"purging","d":"Removing training observations whose outcome window overlaps the test set, then waiting a further gap. Without it, financial cross-validation grades the model on data it effectively saw.","r":"6","vid":"vol6"},"regime":{"t":"regime switching","d":"A persistent state of the market — calm or stressed — with its own volatility and behaviour. Useful for sizing positions; too laggy and noisy for timing them.","r":"4","vid":"vol4"},"triple-barrier":{"t":"triple-barrier","d":"Labelling a trade by whichever comes first: the profit target, the stop, or the time limit. It describes a position you could actually have held.","r":"6","vid":"vol6"},"walk-forward":{"t":"walk-forward","d":"Repeatedly fitting on the past and testing on the next period, moving forward through history. The only honest way to evaluate anything that re-fits over time.","r":"6","vid":"vol6"},"copula":{"t":"copula","d":"A way of separating “how each thing behaves on its own” from “how they behave at the same time”. It lets you model joint crashes without changing anything about the individual assets.","r":"12A","vid":"vol12a"},"expected-shortfall":{"t":"expected shortfall","d":"The average loss on the bad days, rather than just the threshold you cross. It fixes both of value-at-risk's defects and is the better default.","r":"12","vid":"vol12"},"garch":{"t":"GARCH","d":"A model in which today's volatility depends on yesterday's shock and yesterday's volatility. It captures the fact that turbulent days cluster together.","r":"4","vid":"vol4"},"kalman":{"t":"Kalman filter","d":"A recipe for tracking something you cannot see directly — a fair value, a drifting hedge ratio — by repeatedly predicting it forward and correcting with each new observation.","r":"4A","vid":"vol4a"},"propagator":{"t":"propagator","d":"A model of price impact in which every past trade leaves a push that fades over time, rather than a permanent step. It is what makes impact decay computable.","r":"2A","vid":"vol2a"},"microstructure":{"t":"market microstructure","d":"The study of how trading actually works at the level of orders and queues, as opposed to what prices do over days and months.","r":"2","vid":"vol2"},"almgren-chriss":{"t":"Almgren–Chriss","d":"The standard answer to how fast to execute a large order: trade quickly and pay impact, or slowly and risk the price running away. It gives the optimal middle.","r":"10","vid":"vol10"},"half-life":{"t":"half-life","d":"How long a mean-reverting spread takes to close half the gap back to its normal level. It sets your holding period, and therefore whether costs eat the trade.","r":"1","vid":"vol1"},"information-driven-bars":{"t":"information-driven bars","d":"Sampling data every fixed amount of volume or activity rather than every fixed amount of clock time, so each observation carries a similar amount of information.","r":"6","vid":"vol6"},"stop-loss":{"t":"stop loss","d":"A pre-set level at which a position is closed automatically. Its value is not the level itself but that the decision was made while calm.","r":"24","vid":"vol24"},"hedge":{"t":"hedge","d":"Taking an offsetting position so that a risk you do not want cancels out, leaving the one you do.","r":"8","vid":"vol8"},"mark-to-market":{"t":"mark-to-market","d":"Revaluing a position at today's market price rather than what you paid. It is why an unrealised loss is a real loss for margin purposes.","r":"17","vid":"vol17"},"sizing":{"t":"position sizing","d":"Deciding how much to hold, as opposed to what to hold. It usually matters more to the outcome than the signal does.","r":"12","vid":"vol12"},"reconciliation":{"t":"reconciliation","d":"Checking that what you think you hold matches what the broker says you hold, every day. Most catastrophic failures begin as a small unexplained difference nobody chased.","r":"17","vid":"vol17"},"annualised":{"t":"annualised","d":"A number rescaled to “per year” so different horizons can be compared. Daily volatility is multiplied by √252 because risk grows with the square root of time, not with time.","r":"0","vid":"vol0"},"back-adjusted":{"t":"back-adjusted series","d":"A single long price history stitched together from expiring futures contracts. The stitching rule changes the numbers, so a backtest on someone else's series is a backtest on their assumptions.","r":"0","vid":"vol0"},"bid-ask-spread":{"t":"bid–ask spread","d":"The gap between the best price you can sell at and the best price you can buy at. You pay roughly half of it entering and half leaving, and it never appears as a line on a statement.","r":"0","vid":"vol0"},"broker":{"t":"broker","d":"The firm that holds your money and sends your orders to a market. The entire relationship reduces to one question: will you get your money back?","r":"0","vid":"vol0"},"cash-account":{"t":"cash account","d":"An account that cannot borrow. You can only lose what you deposited. The safest starting structure, and the one most beginners skip past.","r":"0","vid":"vol0"},"cfd":{"t":"CFD","d":"A contract with a firm that mirrors an asset's price. You own nothing, and your counterparty is the firm — which often profits directly when you lose.","r":"0","vid":"vol0"},"commission":{"t":"commission","d":"The explicit fee your broker charges per trade. Usually the smallest of your real costs, and the only one beginners count.","r":"0","vid":"vol0"},"continuous-contract":{"t":"continuous contract","d":"A synthetic price series joining successive futures expiries so you can backtest across years. Requires an explicit roll rule, and different rules give different answers.","r":"0","vid":"vol0"},"counterparty":{"t":"counterparty","d":"Whoever is on the other side of your trade or holds your assets. When it is an exchange, risk is small; when it is the firm you trade with, it is not.","r":"0","vid":"vol0"},"cost-to-edge":{"t":"cost-to-edge ratio","d":"Your expected annual costs divided by your expected gross return. Above about 20%, no improvement to the signal saves the strategy — only less turnover does.","r":"0","vid":"vol0"},"diversification":{"t":"diversification","d":"Holding several things whose bad days do not coincide. The only reliable free improvement in finance, and the reason eight positions can carry less risk than one.","r":"0","vid":"vol0"},"edge":{"t":"edge","d":"Knowing or processing something better than the price reflects. Rare, small, decaying, and almost always confused with luck by the person who has it.","r":"0","vid":"vol0"},"etf":{"t":"ETF","d":"One tradeable security holding a basket of many. Cheap, diversified and hard to blow up — which makes it the natural first instrument.","r":"0","vid":"vol0"},"fractional-shares":{"t":"fractional shares","d":"Buying part of a share, so a $400 stock can be a $10 position. The mechanism that makes correct position sizing possible in a small account.","r":"0","vid":"vol0"},"funding-rate":{"t":"funding rate","d":"A payment flowing between longs and shorts in a perpetual futures market to keep its price near spot. Can cost tens of percent a year in one direction.","r":"14","vid":"vol14"},"futures-contract":{"t":"futures contract","d":"A standardised, exchange-traded agreement to exchange something later. You post a small margin and control a much larger notional — which is the whole danger.","r":"0","vid":"vol0"},"gtc":{"t":"good-till-cancelled","d":"An order that survives until it fills or you kill it. Forgotten GTC orders fill weeks later in a world you no longer wanted them in.","r":"0","vid":"vol0"},"idm":{"t":"diversification multiplier","d":"The factor by which you may scale up positions because your instruments do not all fall together. Roughly 1.5 for four instruments, 2.0 for eight, 2.5 for twenty.","r":"0","vid":"vol0"},"idempotency":{"t":"idempotency","d":"The property that retrying an order after a timeout cannot create a second position. Without it, one network hiccup doubles your exposure.","r":"17","vid":"vol17"},"implementation-shortfall":{"t":"implementation shortfall","d":"The difference between the price when you decided and the price you actually got. The only honest measure of what your trading costs you.","r":"10","vid":"vol10"},"inactivity-fee":{"t":"inactivity fee","d":"A monthly charge for not trading enough. $10 a month on a $1,000 account is 12% a year, which no strategy recovers.","r":"0","vid":"vol0"},"ioc":{"t":"immediate-or-cancel","d":"An order that takes whatever is available right now and cancels the rest. Useful when a partial fill is better than a chased price.","r":"0","vid":"vol0"},"kill-switch":{"t":"kill switch","d":"A tested mechanism that flattens every position and halts the system. An automated strategy without one is an unattended machine with access to your money.","r":"17","vid":"vol17"},"kyc":{"t":"KYC","d":"The identity checks a regulated firm must run before it holds your money. Slow, tedious, and a sign the firm is inside a real regulatory perimeter.","r":"0","vid":"vol0"},"liquidation":{"t":"liquidation","d":"Your position closed automatically because margin ran out — usually at the worst price of the move that caused it.","r":"14","vid":"vol14"},"margin-account":{"t":"margin account","d":"An account that can borrow, enabling shorting and futures. It also permits you to lose more than you deposited, which is why it should be a deliberate choice.","r":"0","vid":"vol0"},"margin-call":{"t":"margin call","d":"A demand to add money or have positions closed for you. If you are sizing by risk rather than by margin, you should never meet one.","r":"0","vid":"vol0"},"market-on-close":{"t":"market-on-close","d":"An order executing in the closing auction — typically the deepest liquidity of the day, and the natural venue for daily-frequency strategies.","r":"0","vid":"vol0"},"notional-exposure":{"t":"notional exposure","d":"The full value of what a position controls, not the cash you put up. The number that tells you how leveraged you actually are.","r":"0","vid":"vol0"},"paper-trading":{"t":"paper trading","d":"A simulated account with real screens and fake money. Excellent for mechanics and routine; useless for fills, costs and the emotional load of a real loss.","r":"0","vid":"vol0"},"partial-fill":{"t":"partial fill","d":"Some of your order executed and the rest is still working. Normal, and a common source of position-tracking bugs.","r":"0","vid":"vol0"},"perpetual":{"t":"perpetual future","d":"A crypto derivative with leverage and no expiry, held near spot by a funding payment. Not a beginner instrument at any account size.","r":"14","vid":"vol14"},"rebalance":{"t":"rebalance","d":"Adjusting positions back to what your rule says they should be. Doing it less often, with a no-trade buffer, can halve your costs for almost no loss of performance.","r":"0","vid":"vol0"},"risk-premium":{"t":"risk premium","d":"Payment for holding something uncomfortable that others would rather not hold. Reliable over decades, brutal over years, and requiring no cleverness at all.","r":"0","vid":"vol0"},"round-trip":{"t":"round trip","d":"One complete entry and exit. The unit in which costs should always be counted, because half a trade is not a trade.","r":"0","vid":"vol0"},"segregated-funds":{"t":"segregated funds","d":"Client money held apart from the firm's own. Without it, the failure of your broker becomes the failure of your account.","r":"0","vid":"vol0"},"settlement":{"t":"settlement","d":"The delay between trading and the money or asset actually being yours to use. It is why funds can be visible and unusable at the same time.","r":"0","vid":"vol0"},"stop-limit":{"t":"stop-limit order","d":"A stop that becomes a limit order rather than a market order. Protects you from a terrible price, at the risk of not filling at all during exactly the move you feared.","r":"0","vid":"vol0"},"suitability":{"t":"suitability questionnaire","d":"The experience and income questions asked at account opening. Overstating your experience unlocks products you should not have and quietly removes legal protections.","r":"0","vid":"vol0"},"tick":{"t":"tick","d":"The smallest price increment an instrument can move. Spreads and slippage are usually measured in ticks before they are measured in money.","r":"0","vid":"vol0"},"time-in-force":{"t":"time in force","d":"How long an order stays alive: DAY dies at the close, GTC survives, IOC takes what is there now, FOK is all-now-or-nothing.","r":"0","vid":"vol0"},"volatility-target":{"t":"volatility target","d":"How much you intend the whole account to swing in a year, expressed as a percentage. Setting it is the single most consequential number in a systematic system.","r":"0","vid":"vol0"},"withdrawal-test":{"t":"withdrawal test","d":"Depositing a small amount, trading once, and withdrawing everything back to source before you trust a firm. The cheapest useful information about a broker that exists.","r":"0","vid":"vol0"},"mgf":{"t":"moment generating function","d":"E[e^{tX}], a single function whose derivatives at zero give every moment of X. Its real use is that the MGF of a sum is the product of the MGFs, which turns convolution into multiplication.","r":"Vol 0C","vid":"vol0c"},"memorylessness":{"t":"memorylessness","d":"The property that having waited already tells you nothing about how much longer you will wait. It holds only for the exponential distribution, which is why constant-hazard models forget everything.","r":"Vol 0C","vid":"vol0c"},"order-statistic":{"t":"order statistic","d":"The k-th smallest value in a sample. The maximum is the one that matters in finance, because the best of N backtests is an order statistic and grows with N whether or not anything is real.","r":"Vol 0C","vid":"vol0c"},"chebyshev":{"t":"Chebyshev’s inequality","d":"At most 1/k² of any distribution lies beyond k standard deviations, whatever its shape. Weak but assumption-free, which is exactly why it survives fat tails when the normal bound does not.","r":"Vol 0C","vid":"vol0c"},"control-variate":{"t":"control variate","d":"A related quantity whose true value you know, simulated alongside the one you want. Correcting by its simulated error cuts variance sharply — usually worth more than extra compute.","r":"Vol 0D","vid":"vol0d"},"quasi-random":{"t":"quasi-random sequence","d":"A deterministic sequence engineered to fill space more evenly than random draws. It improves Monte Carlo convergence in low dimensions at no extra cost per path.","r":"Vol 0D","vid":"vol0d"},"numeraire":{"t":"numéraire","d":"The asset you measure every other price against. Choosing it well makes an awkward expectation trivial — most closed-form option results are a numéraire choice plus algebra.","r":"Vol 1A","vid":"vol1a"},"girsanov":{"t":"Girsanov’s theorem","d":"The rule for changing probability measure: it reweights how likely each path is without changing which paths exist. That is why drift is negotiable under a change of measure and volatility is not.","r":"Vol 1A","vid":"vol1a"},"stopping-time":{"t":"stopping time","d":"A rule for when to stop that uses only information available at the time. “Sell at the high” is not one; “sell when the drawdown hits 10%” is.","r":"Vol 1A","vid":"vol1a"},"radon-nikodym":{"t":"Radon–Nikodym derivative","d":"The density that converts one probability measure into another — the exchange rate between P and Q. In pricing it carries the market price of risk.","r":"Vol 1A","vid":"vol1a"},"effective-spread":{"t":"effective spread","d":"Twice the distance from the mid-price to your fill. It measures what a trade actually cost, rather than what the quoted spread advertised.","r":"Vol 2B","vid":"vol2b"},"realised-spread":{"t":"realised spread","d":"Twice the distance from your fill to the mid a short time later. What a market maker keeps; the gap between effective and realised spread is adverse selection.","r":"Vol 2B","vid":"vol2b"},"resiliency":{"t":"resiliency","d":"How fast the book refills after being hit. Depth tells you what you can trade now, resiliency what you can trade repeatedly.","r":"Vol 2B","vid":"vol2b"},"spoofing":{"t":"spoofing","d":"Entering orders you intend to cancel in order to move the price. It is illegal in most jurisdictions and identified by cancellation patterns rather than by intent.","r":"Vol 2B","vid":"vol2b"},"pfof":{"t":"payment for order flow","d":"A market maker paying a broker to route retail orders to it. Retail flow is uninformed and therefore valuable, which is what the payment is buying.","r":"Vol 2B","vid":"vol2b"},"internalisation":{"t":"internalisation","d":"A broker filling client orders against its own book rather than the exchange. It removes uninformed flow from the public book and leaves the rest more toxic.","r":"Vol 2B","vid":"vol2b"},"portfolio-sort":{"t":"portfolio sort","d":"Ranking every asset on a characteristic, cutting into groups, and comparing their returns. A non-parametric conditional mean — it can see relationships a linear fit averages away.","r":"Vol 5A","vid":"vol5a"},"breakpoint":{"t":"breakpoint","d":"The cut point between groups in a sort. Cutting on all names puts nearly all the money in one bucket, which is why large-cap breakpoints exist.","r":"Vol 5A","vid":"vol5a"},"fama-macbeth":{"t":"Fama–MacBeth regression","d":"Regress the cross-section each period, then average and test the resulting slope series. The split absorbs the correlation among same-period returns that ruins a pooled regression.","r":"Vol 5A","vid":"vol5a"},"newey-west":{"t":"Newey–West","d":"A standard error robust to heteroskedasticity and autocorrelation, built from weighted autocovariances out to a chosen lag. Choosing the lag after seeing the answer is the standard abuse.","r":"Vol 5A","vid":"vol5a"},"winsorise":{"t":"winsorise","d":"Replace values beyond a percentile with that percentile, keeping the observation. Decide before you look at the answer, and report how much the result moves.","r":"Vol 5A","vid":"vol5a"},"anomaly-zoo":{"t":"anomaly zoo","d":"The several hundred published characteristics claimed to predict returns. They cannot all be true; multiple testing and microcap concentration explain most of them.","r":"Vol 5A","vid":"vol5a"},"bias-variance":{"t":"bias–variance decomposition","d":"Expected squared error splits exactly into bias², variance and irreducible noise. Finance has an enormous noise term, which is why variance is the binding cost there.","r":"Vol 6A","vid":"vol6a"},"out-of-bag":{"t":"out-of-bag","d":"The ~37% of observations left out of each bootstrap sample. They give a free held-out error estimate for bagged models.","r":"Vol 6A","vid":"vol6a"},"permutation-importance":{"t":"permutation importance","d":"Shuffle one feature on held-out data and measure how much performance falls. Unlike impurity importance it does not favour high-cardinality features.","r":"Vol 6A","vid":"vol6a"},"elastic-net":{"t":"elastic net","d":"Ridge and lasso penalties combined. It selects variables while keeping correlated groups together, which matters when signals are routinely 0.8 correlated.","r":"Vol 6A","vid":"vol6a"},"auc":{"t":"AUC","d":"The probability that a randomly chosen positive scores above a randomly chosen negative. Threshold-free, and misleading when the positive class is rare — use precision–recall instead.","r":"Vol 6A","vid":"vol6a"},"kernel-trick":{"t":"kernel trick","d":"Replacing inner products with a kernel function fits a linear model in a much richer space without ever computing the mapping. It works for any method written in inner products.","r":"Vol 6A","vid":"vol6a"},"effective-sample":{"t":"effective sample size","d":"The number of genuinely independent observations, which overlapping windows and serial dependence make far smaller than the row count. Size model capacity against this, not against rows.","r":"Vol 6A","vid":"vol6a"},"variation-margin":{"t":"variation margin","d":"The daily cash settlement of a futures position’s gains and losses. Not collateral but a real payment, which is why a perfectly hedged book can still fail to fund it.","r":"Vol 8B","vid":"vol8b"},"novation":{"t":"novation","d":"The clearing house replacing one bilateral contract with two, so each side faces the CCP. It converts counterparty risk into mutualised exposure rather than removing it.","r":"Vol 8B","vid":"vol8b"},"default-waterfall":{"t":"default waterfall","d":"The ordered resources a clearing house draws on after a member fails: the defaulter’s margin, its fund contribution, the CCP’s own capital, then surviving members’ money.","r":"Vol 8B","vid":"vol8b"},"convenience-yield":{"t":"convenience yield","d":"The benefit of holding a physical commodity rather than a claim on it. It is a residual backed out of the forward curve, so it absorbs every error in your other carry inputs.","r":"Vol 8B","vid":"vol8b"},"ois-discounting":{"t":"OIS discounting","d":"Discounting collateralised cash flows at the overnight rate the collateral earns. Discounting must match funding, which is what split one curve into many.","r":"Vol 8B","vid":"vol8b"},"xva":{"t":"XVA","d":"The family of valuation adjustments — credit, debit, funding, margin, capital — that turn a textbook derivative price into a bank’s price. Each one prices an assumption that is false.","r":"Vol 8B","vid":"vol8b"},"cva":{"t":"CVA","d":"The expected loss from a counterparty defaulting while a trade is in your favour. Because it depends on the positive part of exposure it is an option, with Greeks, and is hedged as one.","r":"Vol 8B","vid":"vol8b"},"hjm":{"t":"HJM framework","d":"Models the whole forward-rate curve, and shows that no-arbitrage fully determines the drift once volatilities are chosen. Every short-rate model is a special case of it.","r":"Vol 8B","vid":"vol8b"},"put-call-parity":{"t":"put–call parity","d":"C − P = S − Ke^(−rT): a model-free identity linking calls, puts and the underlying. It means every option position has two other equivalent forms, so trade whichever is cheapest.","r":"Vol 8C","vid":"vol8c"},"synthetic":{"t":"synthetic position","d":"A position built from other instruments that replicates a target payoff. A covered write is a synthetic short put, which is what its risk actually is.","r":"Vol 8C","vid":"vol8c"},"vertical-spread":{"t":"vertical spread","d":"Long one option and short another of the same type and expiry at a different strike. Bounded at both ends, and a bet on the skew as well as on direction.","r":"Vol 8C","vid":"vol8c"},"straddle":{"t":"straddle","d":"A call and a put at the same strike. Delta-hedged, it earns realised variance and pays implied — so it is a bet on movement beyond what you were already charged for.","r":"Vol 8C","vid":"vol8c"},"butterfly":{"t":"butterfly","d":"Long the wings, short twice the middle strike. The cheapest bounded way to be short movement around a level; the wings cost most of what the middle brings in, and that is correct pricing.","r":"Vol 8C","vid":"vol8c"},"calendar-spread":{"t":"calendar spread","d":"Short a near expiry and long a far one at the same strike. It earns the difference in decay while being long forward volatility — and long vega with short gamma at once.","r":"Vol 8C","vid":"vol8c"},"ratio-spread":{"t":"ratio spread","d":"Buying one option and selling more than one of another strike, usually for zero premium. The far slope is not zero, so it is a naked short financed by a spread. Size it by the naked leg.","r":"Vol 8C","vid":"vol8c"},"gamma-rent":{"t":"gamma rent","d":"The net of rehedging gains against time decay on a long-gamma position — the running charge for holding convexity. Short gamma makes you the landlord.","r":"Vol 8C","vid":"vol8c"},"pin-risk":{"t":"pin risk","d":"Not knowing whether a short option at the settlement price will be assigned. It is an unhedgeable overnight gap the size of the whole position; close short strikes near spot before expiry.","r":"Vol 8C","vid":"vol8c"},"risk-reversal":{"t":"risk reversal","d":"Long one wing of the volatility surface and short the other. It isolates the relative pricing of the two tails, which is to say the skew.","r":"Vol 8C","vid":"vol8c"},"arrival-price":{"t":"arrival price","d":"The market price when an order reached the desk. Measuring cost from arrival rather than from the decision hides the delay term, which is often the largest.","r":"Vol 10B","vid":"vol10b"},"delay-cost":{"t":"delay cost","d":"The move between the decision price and the arrival price, on the full intended quantity. A plumbing cost rather than a market one — and the cheapest component to fix.","r":"Vol 10B","vid":"vol10b"},"opportunity-cost":{"t":"opportunity cost","d":"The return given up on the part of an order you never filled. Without it, an algorithm can look excellent simply by abandoning hard orders.","r":"Vol 10B","vid":"vol10b"},"cost-curve":{"t":"cost curve","d":"Expected trading cost plotted against horizon, with its dispersion. Its minimum sets the schedule, and feeding it back into position sizing is what defines capacity.","r":"Vol 10B","vid":"vol10b"},"square-root-law":{"t":"square-root law","d":"Market impact grows roughly as the square root of the fraction of daily volume traded. Robust across markets and decades, and the reason capacity is finite.","r":"Vol 10B","vid":"vol10b"},"tca":{"t":"transaction cost analysis","d":"Measuring what trading cost, decomposed and benchmarked. A modelling discipline rather than an accounting one, because impact has no observable counterfactual.","r":"Vol 10B","vid":"vol10b"},"forecast-scalar":{"t":"forecast scalar","d":"The constant that puts every trading rule’s output on one scale, so a forecast of the same size means the same conviction whichever rule produced it. Estimate it pooled, not per instrument.","r":"Vol 11B","vid":"vol11b"},"diversification-multiplier":{"t":"diversification multiplier","d":"1/√(w′ρw): the factor that restores a portfolio to its risk target after correlated positions partly offset. It saturates fast, so the twentieth instrument buys almost nothing.","r":"Vol 11B","vid":"vol11b"},"no-trade-buffer":{"t":"no-trade buffer","d":"A band around the optimal position inside which you do not trade. A 10% band typically removes two thirds of turnover for almost no loss of exposure — trade to the band’s edge, not its centre.","r":"Vol 11B","vid":"vol11b"},"hazard-rate":{"t":"hazard rate","d":"The instantaneous rate of default given survival so far. Roughly the credit spread divided by loss given default, which is why only that ratio is identified by one spread.","r":"Vol 12B","vid":"vol12b"},"cds":{"t":"credit default swap","d":"Insurance against a reference entity’s default: a periodic premium against a payout on a credit event, cash-settled at an auction price.","r":"Vol 12B","vid":"vol12b"},"recovery-rate":{"t":"recovery rate","d":"The fraction of face value a defaulted claim is worth. Fixed by convention when bootstrapping, so every hazard curve is conditional on an assumption you should state.","r":"Vol 12B","vid":"vol12b"},"tranche":{"t":"tranche","d":"A claim on a pool’s losses between an attachment and a detachment point. Tranching redistributes losses rather than removing them, and makes the senior claim a bet on correlation.","r":"Vol 12B","vid":"vol12b"},"base-correlation":{"t":"base correlation","d":"The correlation that reprices each equity tranche up to a detachment point under the Gaussian copula. A quoting device like implied volatility — not an estimate of how correlated defaults are.","r":"Vol 12B","vid":"vol12b"},"wrong-way-risk":{"t":"wrong-way risk","d":"Exposure that grows precisely as the counterparty’s ability to pay it shrinks. Standard CVA assumes independence, so wrong-way risk can multiply the true adjustment several times.","r":"Vol 12B","vid":"vol12b"},"netting":{"t":"netting","d":"A master agreement making all trades with one counterparty a single net claim on default. The largest single reduction in counterparty exposure available — where it is enforceable.","r":"Vol 12B","vid":"vol12b"},"margin-period-of-risk":{"t":"margin period of risk","d":"The gap between the last successful collateral call and close-out, during which the market keeps moving. Usually assumed at ten business days; it is why collateral cannot remove exposure.","r":"Vol 12B","vid":"vol12b"},"term-premium":{"t":"term premium","d":"The part of a long yield that is compensation for holding duration rather than an expectation of future short rates. A steep curve predicts excess bond returns, not rate rises.","r":"Vol 13B","vid":"vol13b"},"equity-risk-premium":{"t":"equity risk premium","d":"The expected return on equities above a safe rate. Estimated forward from yield plus growth, not backward from an average that contains a one-off re-rating.","r":"Vol 13B","vid":"vol13b"},"illiquidity-premium":{"t":"illiquidity premium","d":"Extra expected return for holding something hard to sell. Real, and available only to capital that can genuinely hold through the quarter when it cannot sell.","r":"Vol 13B","vid":"vol13b"},"volatility-risk-premium":{"t":"volatility risk premium","d":"The gap by which implied volatility exceeds subsequently realised volatility, on average. Insurance sold to people who are structurally long — and short a tail.","r":"Vol 13B","vid":"vol13b"},"bad-times":{"t":"bad times","d":"The states in which investors most need money. An asset earns a premium to the extent that it pays off badly in them, which is the single idea underneath every risk premium.","r":"Vol 13B","vid":"vol13b"},"stambaugh-bias":{"t":"Stambaugh bias","d":"The upward bias in a predictive regression when the predictor is highly persistent and correlated with the return innovation. It inflates t-statistics in exactly the valuation regressions people cite.","r":"Vol 13B","vid":"vol13b"},"unsmoothing":{"t":"unsmoothing","d":"Correcting an appraisal-based return series for the averaging in its marks. It typically raises measured volatility a lot, and lowers the Sharpe ratio accordingly.","r":"Vol 13B","vid":"vol13b"},"volatility-laundering":{"t":"volatility laundering","d":"Infrequent, appraisal-based marking that makes an asset look less volatile and less correlated than it is. The flattering inputs then cause an optimiser to over-allocate to it.","r":"Vol 13B","vid":"vol13b"}}
;
window.__CARDS__=[{"i":"0-1","v":"0","s":"0-1-what-trading-actually-is","q":"Name the <b>three</b> — and only three — ways a strategy makes money, and say what your expected result is if you have none of the first two.","a":"<p><b>Risk premium</b> (paid for holding what others avoid), <b>edge</b> (knowing or processing better than the price reflects), and <b>luck</b>.</p><p>With no risk premium and no edge your expectation is <b>not zero — it is minus your costs</b>. Trading is a coin flip with a fee on every toss.</p>"},{"i":"0-2","v":"0","s":"0-2-the-four-questions","q":"A trade answers four questions. Which of them decides whether you survive, and which one feels like the whole activity but matters least?","a":"<p>What · which way · <b>how much</b> · what ends it.</p><p><b>How much</b> — position sizing — decides survival. <b>Which way</b> — the signal, the clever part — feels like the whole activity and matters least. A mediocre signal sized well beats a good signal sized badly, essentially always (26.1).</p>"},{"i":"0-3","v":"0","s":"0-3-the-readiness-test","q":"Why is trading with money you <em>need</em> not merely risky but structurally different from trading money you can lose?","a":"<p>Because the pressure changes your behaviour in exactly the ways that destroy accounts: you size by fear rather than by rule — too small when the signal is good, then too large to catch up — and you cannot tolerate the ordinary drawdown the system was designed to have.</p><p>The skill you might acquire later does not offset what the pressure does to you now.</p>"},{"i":"0-4","v":"0","s":"0-4-capital-bands","q":"A $1,000 account pays $2 per round trip on a $200 position and trades twice a week. What fraction of the account goes to costs per year — and what does that imply?","a":"<p>$2 on $200 is 1% of the position, 0.2% of the account. Twice a week is ~104 trades: <b>about 21% of the account per year</b>.</p><p>A good systematic strategy earns 8–15% gross. You would need to be roughly three times better than professional managed futures funds simply to break even. The same $2 on a $10,000 position is 0.4% a year. <b>Identical skill, opposite outcome — the difference is arithmetic, not talent.</b></p>"},{"i":"0-5","v":"0","s":"0-5-choosing-what-to-trade","q":"In what order do the four filters for choosing an instrument apply — and where does &ldquo;what interests me&rdquo; sit?","a":"<p>1 · Can I afford a sensible position in it? 2 · Can I get honest data on it? 3 · What is the worst it can do to me? 4 · What does a round trip cost?</p><p><b>Interest comes last</b>, after all four. Choosing by familiarity or enthusiasm is how beginners end up in the instruments with the worst regulator-published loss statistics.</p>"},{"i":"0-5b","v":"0","s":"0-5-choosing-what-to-trade","q":"Why is a &ldquo;3× daily&rdquo; leveraged ETF not a 3× position in the index over any period longer than a day?","a":"<p>Because it <b>resets its leverage every day</b>. Compounding daily 3× returns is not the same as 3× the compounded return: in a choppy market the fund loses money while the index goes nowhere. They are day-trading tools, not holdings.</p>"},{"i":"0-6","v":"0","s":"0-6-choosing-a-broker","q":"How do you actually verify a broker's licence, and why does the method matter more than the fact?","a":"<p>Take the licence number from the firm's own footer, then go to <b>the regulator's website, typed by hand</b> — never a link supplied by the broker — and search the register. Confirm the entity name matches exactly and that the licence covers the activity you intend.</p><p>Clone firms copying a genuine licence number are common, and every link they control can be faked.</p>"},{"i":"0-6b","v":"0","s":"0-6-choosing-a-broker","q":"Name the single cheapest test of whether a broker can be trusted with real capital.","a":"<p>Deposit a trivial amount, let it settle, place one tiny trade, then <b>withdraw the entire balance back to the same source</b>. Time it and note every fee.</p><p>A firm that returns money quickly and without friction has passed the only test that ultimately matters; one that does not has cost you the price of the lesson rather than the price of the account.</p>"},{"i":"0-7","v":"0","s":"0-7-opening-and-funding","q":"Why should a beginner open a <b>cash</b> account rather than a margin account &ldquo;just in case&rdquo;?","a":"<p>A cash account cannot borrow, so you cannot lose more than you deposited. A margin account removes that hard limit.</p><p>Choosing margin pre-emptively discards a protection that is working for you, in exchange for an option you have no plan to use. Permissions can be added later in minutes; a removed constraint is much harder to reinstate.</p>"},{"i":"0-8","v":"0","s":"0-8-data-that-does-not-lie","q":"Name the one-line test for look-ahead bias, and what a collapse in performance under it means.","a":"<p><b>Shift every signal one bar later and re-run.</b></p><p>If performance collapses, your result depended on information you could not have had at decision time — you were trading on the future. This single test catches the most common and most fatal class of backtest bug.</p>"},{"i":"0-8b","v":"0","s":"0-8-data-that-does-not-lie","q":"What is survivorship bias, and what is the 10-minute check for it?","a":"<p>Your dataset contains only the companies that still exist, so every bankruptcy has been deleted from history — your backtest never buys the dip that went to zero. It inflates returns substantially and always in your favour.</p><p><b>Check:</b> search your universe for a company you know was delisted or acquired. If it is absent, every cross-sectional result from that data is overstated.</p>"},{"i":"0-9","v":"0","s":"0-9-automated-or-not","q":"Semi-automatic versus fully automated: state the one failure mode of each, and which is the correct default.","a":"<p><b>Semi-automatic</b> fails exactly one way: <b>you override the output</b>. That is entirely sufficient — the discipline is the product.</p><p><b>Fully automated</b> fails <b>silently</b>: stale prices, duplicated orders, unhandled disconnects, positions that do not match what the code believes.</p><p>Semi-automatic is the correct default: nearly all the benefit at a small fraction of the engineering cost, and a complete strategy rather than a stepping stone.</p>"},{"i":"0-9b","v":"0","s":"0-9-automated-or-not","q":"Name the four infrastructure requirements without which an automated system is &ldquo;not a trading system&rdquo;.","a":"<p><b>Kill switch</b> (flattens all positions, tested against the live account), <b>reconciliation</b> (continuous check that broker positions match the system's), <b>alerting that treats silence as an alarm</b>, and <b>idempotent order logic</b> (a retry cannot create a second position).</p><p>Without these it is an unattended machine with access to your money.</p>"},{"i":"0-10","v":"0","s":"0-10-your-first-strategy","q":"Why must a first strategy have fewer than four parameters, and what is the rule that protects a specification from you?","a":"<p>Every parameter is a dial you will turn until the backtest looks good. Four dials over a few hundred trades is already enough to fit noise convincingly (18.1).</p><p><b>The rule:</b> write the parameters down before running anything, run once, accept the result. If you then search for a version that looks good, you have destroyed your ability to know anything — and no subsequent care repairs it.</p>"},{"i":"0-11","v":"0","s":"0-11-paper-trading","q":"Name two things paper trading teaches reliably and two it cannot teach while appearing to.","a":"<p><b>Teaches:</b> the mechanics of the order ticket; whether your daily routine actually fits your life; whether your code produces the positions you expected; operational failure modes.</p><p><b>Cannot teach:</b> realistic fills and slippage (simulators fill you instantly at the touch); the emotional load of a real loss; and <b>whether the strategy works</b> — three weeks is ~15 observations and is statistically meaningless.</p>"},{"i":"0-12","v":"0","s":"0-12-position-sizing","q":"State the risk-per-trade sizing formula in words, and explain why a <em>tighter</em> stop produces a <em>larger</em> position.","a":"<p><b>Units = (Account × Risk fraction) ÷ (Distance from entry to stop, per unit).</b> In words: the money I am willing to lose, divided by the money I lose per share if I am wrong.</p><p>A tighter stop means less loss per share, so the same risk budget buys more shares. That is arithmetically correct and practically dangerous: a stop inside normal daily noise gets hit by noise, at full size. <b>Set the stop where the idea is wrong, then let the arithmetic give you the size — never the reverse.</b></p>"},{"i":"0-12b","v":"0","s":"0-12-position-sizing","q":"Give the volatility-targeting formula in words, and the rule of thumb it collapses to at a 10% target across eight instruments.","a":"<p><b>Units = (Account × Target volatility × Weight × IDM) ÷ (Instrument volatility × Value of one unit).</b> The top is the annual risk in money you want this instrument to contribute; the bottom is the annual risk one unit carries.</p><p><b>Rule of thumb:</b> the annual risk of one unit must be no more than about <b>2.5% of your account</b>. This alone correctly rules futures out of small accounts and ETFs in.</p>"},{"i":"0-12c","v":"0","s":"0-12-position-sizing","q":"Why do practitioners use a quarter to a half of Kelly rather than full Kelly?","a":"<p>Kelly requires knowing your true edge, and you have only a noisy estimate. The error is brutally asymmetric: betting <b>half</b> of optimal costs about a quarter of your growth rate; <b>overestimating your edge by 2× means betting twice Kelly, whose expected long-run growth is zero or negative</b>.</p><p>Full Kelly is also spectacularly volatile even when correct — 50%+ drawdowns as ordinary events.</p>"},{"i":"0-13","v":"0","s":"0-13-the-first-order","q":"Which order type should be your default, and what is the honest cost of that choice?","a":"<p><b>Limit</b> — it fills at your price or better, or not at all.</p><p>The cost is real: you may miss a trade when the signal was right. But that cost is <b>bounded and visible</b>, whereas the cost of a bad market-order fill is unbounded and invisible. Market orders belong only on very liquid instruments when getting done genuinely matters more than the price.</p>"},{"i":"0-13b","v":"0","s":"0-13-the-first-order","q":"What single thing must you record the moment an order fills, and why is it the most valuable dataset you will own?","a":"<p><b>The price you got and the price showing when you decided.</b> The difference is your implementation shortfall.</p><p>Over fifty trades it becomes the only honest measurement of what trading actually costs you — nobody records the decision price for you — and it feeds a cost model that makes every subsequent backtest more truthful (10.4).</p>"},{"i":"0-14","v":"0","s":"0-14-the-first-month","q":"A strategy with a true long-run Sharpe near 0.5 has what chance of losing money over a given year — and what follows from that?","a":"<p>Roughly a <b>30% chance</b>, while working exactly as designed.</p><p>It follows that a losing year is <em>not</em> evidence the strategy is broken, and a winning year is <em>not</em> evidence it works. The feedback is too noisy for either to tell you much, which is why the process discipline of Volume 00 and the statistics of Volume 18 are not decorations — they are the only way to learn anything from a signal this weak.</p>"},{"i":"0-15","v":"0","s":"0-15-what-it-actually-costs","q":"State the cost-to-edge test and the threshold at which a strategy is no longer viable for you.","a":"<p>Annual turnover × all-in cost per unit traded × 2 (both sides), compared with expected gross return.</p><p>If costs exceed <b>20% of expected gross</b>, the answer is never a better signal — it is <b>less turnover, a cheaper instrument, or a different strategy</b>. Weekly rebalancing at 1.5× turnover and 5 bp costs 0.15% a year; daily rebalancing at 8× turnover and 40 bp costs 6.4% and kills the strategy outright.</p>"},{"i":"0-16","v":"0","s":"0-16-how-you-will-lose-the-money","q":"Which single mechanism ends more accounts than all the others together, and what does it feel like at the time?","a":"<p><b>Position too large.</b> It accounts for more ruin than every other mechanism combined.</p><p>From the inside it feels entirely reasonable: you sized by what you could afford, and the number looked fine. The control is the sizing arithmetic in 0.12, applied every time without exception.</p>"},{"i":"0-17","v":"0","s":"0-17-kill-criteria","q":"Why does the drawdown ladder assign &ldquo;no change to positions&rdquo; as the response to the first alarming level?","a":"<p>Because the purpose of pre-committed kill criteria is to <b>remove the decision from the moment you are least able to make it</b>. The first alarming number is where discipline usually breaks, so it is given an explicit, written, permitted response of <em>keep going</em>.</p><p>Capital is protected by position sizing; the ladder protects the process.</p>"},{"i":"0-18","v":"0","s":"0-18-the-runway-checklist","q":"Summarise the entire volume in one sentence.","a":"<p><b>Trade small enough that being wrong is boring, slowly enough that costs do not matter, following a rule you wrote down before you had money at stake — and measure everything, especially yourself.</b></p><p>The remaining fifty-one volumes are elaboration on why each clause is there.</p>"},{"i":"0A-1","v":"0A","s":"0a-2-sets-functions-and-relations","q":"Why is quantitative work done in <b>log</b> returns rather than simple returns — and what is the one thing log returns are <em>not</em> good for?","a":"<p>Log returns are <b>additive through time</b>: the log return over a period is exactly the sum of the log returns within it. Simple returns are not (+10% then &minus;10% is not zero).</p><p>They are <b>not additive across assets</b> — a portfolio's log return is not the weighted average of its constituents' log returns. Rule: <b>compound through time in logs, aggregate across assets in simple returns.</b></p>"},{"i":"0A-2","v":"0A","s":"0a-3-sequences-limits-and-continuity","q":"A Brownian path moves by roughly how much over a small interval &Delta;t — and what does that imply?","a":"<p>By <b>&radic;&Delta;t</b>, not &Delta;t. Since &radic;&Delta;t / &Delta;t &rarr; &infin;, the difference quotient has no limit: the path is continuous everywhere and differentiable nowhere. There is no velocity.</p><p>Everything strange about Itô calculus follows from that one scaling.</p>"},{"i":"0A-3","v":"0A","s":"0a-3-sequences-limits-and-continuity","q":"A strategy makes 1% a day for 250 days, then loses 1% a day for 250 days. What is the total return?","a":"<p>About <b>&minus;2.5%</b>. (1.01 &times; 0.99)<sup>250</sup> = 0.9999<sup>250</sup> &asymp; 0.975.</p><p>Volatility drag is not a metaphor — it is &minus;&sigma;&sup2;/2 and it is arithmetic.</p>"},{"i":"0A-4","v":"0A","s":"0a-4-the-derivative-built-from-nothing","q":"Differentiate x&sup2; from the difference quotient. Which term vanishes, and why does that term <em>not</em> vanish in stochastic calculus?","a":"<p>((x+h)&sup2; &minus; x&sup2;)/h = (2xh + h&sup2;)/h = 2x + h &rarr; <b>2x</b>. The h&sup2; term survives division by h as an h, then vanishes.</p><p>In stochastic calculus (&Delta;W)&sup2; &asymp; &Delta;t rather than being of order (&Delta;t)&sup2;, so the squared term <b>does not vanish</b>. That single change is the whole of Itô's lemma.</p>"},{"i":"0A-5","v":"0A","s":"0a-5-taylor-series-the-approximation-everything-ru","q":"State the two-term Taylor expansion of ln(1+x) and the trading result it produces.","a":"<p>ln(1+x) &asymp; x &minus; x&sup2;/2.</p><p>Substituting returns and taking expectations gives <b>E[ln(1+r)] &asymp; &mu; &minus; &sigma;&sup2;/2</b> — the drag term appearing in geometric Brownian motion, the Kelly criterion and every compounding argument in the reference.</p>"},{"i":"0A-6","v":"0A","s":"0a-5-taylor-series-the-approximation-everything-ru","q":"Name four places in finance that are a truncated Taylor series, and say to what order.","a":"<ul><li><b>Duration and convexity</b> — bond price in yield, to second order</li><li><b>Delta and gamma</b> — option value in spot, to second order</li><li><b>Itô's lemma</b> — second order, with (dW)&sup2; = dt</li><li><b>Delta method / Newton's method</b> — first order</li></ul>"},{"i":"0A-7","v":"0A","s":"0a-6-integration-and-the-fundamental-theorem","q":"Why is the sum-of-products definition of the integral more useful to carry than 'area under the curve'?","a":"<p>Because a P&amp;L <em>is</em> a sum of (position) &times; (price change). As the rebalancing interval shrinks it becomes &int;&theta;<sub>t</sub> dS<sub>t</sub>.</p><p>And the sum form makes visible that the answer depends on whether &theta; is evaluated at the left or middle of each interval — the Itô/Stratonovich distinction. <b>In trading the left endpoint is the only defensible choice</b>, because you must set your position before observing the price change.</p>"},{"i":"0A-8","v":"0A","s":"0a-7-several-variables-gradients-hessians-and-jaco","q":"Give the gradient and Hessian of the mean&ndash;variance objective, and the solution.","a":"<p>f(w) = &frac12;w&#8868;&Sigma;w &minus; &lambda;&mu;&#8868;w. Gradient = &Sigma;w &minus; &lambda;&mu;. Hessian = <b>&Sigma; itself</b>. Setting the gradient to zero: <b>w* = &lambda;&Sigma;<sup>&minus;1</sup>&mu;</b>.</p><p>Because the Hessian <em>is</em> the covariance matrix, every pathology of estimated covariance (near-singularity, tiny eigenvalues) is directly a pathology of the optimisation.</p>"},{"i":"0A-9","v":"0A","s":"0a-8-vectors-and-what-a-portfolio-actually-is","q":"What is the sample correlation of two demeaned return series, geometrically?","a":"<p>The <b>cosine of the angle</b> between them as vectors in R<sup>T</sup>. Correlation 1: same direction. 0: perpendicular. &minus;1: opposite.</p><p>This is why three assets cannot be pairwise correlated at &minus;0.9 — there is not enough room in any dimension — and why a correlation matrix must be positive semi-definite.</p>"},{"i":"0A-10","v":"0A","s":"0a-9-matrices-as-linear-maps","q":"Why should you never compute A<sup>&minus;1</sup>b by forming A<sup>&minus;1</sup>?","a":"<p>Solving the system directly (<code>np.linalg.solve</code>) is faster and, far more importantly, <b>numerically stabler by orders of magnitude</b> on the ill-conditioned matrices that estimated covariances always are.</p><p>Same for OLS: use <code>lstsq</code> or a QR decomposition, never (X&#8868;X)<sup>&minus;1</sup>X&#8868;y literally.</p>"},{"i":"0A-11","v":"0A","s":"0a-10-linear-systems-rank-and-the-meaning-of-singu","q":"A matrix has condition number 10<sup>13</sup>. How many correct digits remain after inversion in double precision?","a":"<p>About <b>3</b>. Double precision gives roughly 16 significant digits and you lose log<sub>10</sub>&kappa; &asymp; 13 of them.</p><p>Print the condition number of every matrix you invert. One line, and one day it saves a month.</p>"},{"i":"0A-12","v":"0A","s":"0a-11-eigenvalues-eigenvectors-and-the-spectral-th","q":"State the spectral theorem and give two things it buys you immediately.","a":"<p>Every real symmetric A = Q&Lambda;Q&#8868; with Q orthogonal and all &lambda;<sub>i</sub> real. Rotate into the eigenbasis, scale each axis, rotate back.</p><p><b>PCA is this theorem</b> applied to a covariance matrix. And <b>matrix functions become trivial</b>: A<sup>k</sup>, A<sup>1/2</sup>, A<sup>&minus;1</sup>, e<sup>A</sup> all follow by acting on &Lambda;.</p>"},{"i":"0A-13","v":"0A","s":"0a-12-positive-definiteness-cholesky-and-simulatin","q":"Give three equivalent characterisations of positive definiteness, and say why a covariance matrix must be PSD.","a":"<p>(1) x&#8868;Ax &gt; 0 for all non-zero x; (2) every eigenvalue is positive; (3) the Cholesky factorisation exists.</p><p>x&#8868;&Sigma;x <em>is</em> the variance of portfolio x. A non-PSD covariance asserts some portfolio has <b>negative variance</b> — a contradiction, not a modelling subtlety. Optimisers find that impossible direction and put money in it.</p>"},{"i":"0A-14","v":"0A","s":"0a-12-positive-definiteness-cholesky-and-simulatin","q":"How do you simulate correlated normal draws from &Sigma;, and why does it work?","a":"<p>Cholesky: &Sigma; = LL&#8868;, then x = Lz with z ~ N(0, I).</p><p>E[xx&#8868;] = L E[zz&#8868;] L&#8868; = L I L&#8868; = &Sigma;. Cholesky is twice as fast as an eigendecomposition and <b>fails loudly</b> if &Sigma; is not PD — use its success as your PSD test.</p>"},{"i":"0A-15","v":"0A","s":"0a-13-matrix-calculus-the-seven-identities-you-wil","q":"Derive the OLS estimator from the sum of squared residuals, and state what the normal equations mean geometrically.","a":"<p>S(b) = y&#8868;y &minus; 2b&#8868;X&#8868;y + b&#8868;X&#8868;Xb. Differentiating: &minus;2X&#8868;y + 2X&#8868;Xb = 0, so <b>b&#770; = (X&#8868;X)<sup>&minus;1</sup>X&#8868;y</b>.</p><p>Geometrically X&#8868;(y &minus; Xb&#770;) = 0: the residual is orthogonal to every regressor, so the fit is the <b>orthogonal projection</b> of y onto the column space of X.</p>"},{"i":"0A-16","v":"0A","s":"0a-14-probability-from-first-principles","q":"What is a filtration, and what does 'adapted' formalise?","a":"<p>An increasing family of &sigma;-algebras {F<sub>t</sub>}, where F<sub>t</sub> is 'everything knowable at time t'. Increasing means information is never lost.</p><p>A strategy is <b>adapted</b> if the position at t is F<sub>t</sub>-measurable — computable from information available at t. That is the formal definition of <b>not looking into the future</b>. Every lookahead bug is the same error: the strategy was not adapted to the filtration.</p>"},{"i":"0A-17","v":"0A","s":"0a-14-probability-from-first-principles","q":"Prior 5%, power 80%, size 10%. A strategy passes your validation. What is P(it is real)?","a":"<p><b>About 30%.</b> (0.8 &times; 0.05) / (0.8 &times; 0.05 + 0.1 &times; 0.95) = 0.040 / 0.135.</p><p>Seventy percent of what passes is noise — not because the test is bad, but because the prior is low. And this assumes you tested <em>one</em> idea.</p>"},{"i":"0A-18","v":"0A","s":"0a-15-random-variables-distributions-and-densities","q":"Why can a probability density exceed 1, and what follows for risk measurement?","a":"<p>Only the <em>integral</em> is a probability. A uniform on [0, 0.1] has density 10 everywhere on it.</p><p>P(X = x) = 0 for every single point of a continuous distribution. So VaR is defined by a <b>quantile of F</b>, never by a statement about the density, and 'probability the return is exactly &minus;2%' has the answer zero.</p>"},{"i":"0A-19","v":"0A","s":"0a-16-expectation-variance-and-covariance","q":"State Jensen's inequality and give three trading consequences.","a":"<p>For convex g: <b>E[g(X)] &ge; g(E[X])</b>.</p><ul><li>An option's value exceeds its value at the expected spot — that gap <em>is</em> time value, and gamma is its local measure</li><li>E[log wealth] &lt; log E[wealth] — why Kelly is not expected-value maximisation</li><li>Expected Sharpe &ne; Sharpe at expected parameters — one route into the deflated Sharpe ratio</li></ul>"},{"i":"0A-20","v":"0A","s":"0a-16-expectation-variance-and-covariance","q":"With n assets, how many variance terms and how many covariance terms are in portfolio variance? What follows?","a":"<p>n variances and <b>n(n&minus;1) covariances</b>. For n = 50: 50 versus 2,450.</p><p>Portfolio risk is almost entirely a statement about <b>correlations</b>, not individual volatilities — which is why diversification stops working precisely when correlations rise, which is when you need it.</p>"},{"i":"0A-21","v":"0A","s":"0a-16-expectation-variance-and-covariance","q":"Equal-weighting n assets with common correlation &rho; and vol &sigma;: what is the portfolio variance, and its limit?","a":"<p>&sigma;&sup2;(&rho; + (1&minus;&rho;)/n), tending to <b>&sigma;&sup2;&rho;</b>, not to zero.</p><p>At &sigma; = 20% and &rho; = 0.4 the floor is 20%&radic;0.4 &asymp; 12.6%. You reach about 13% with 20 names and <b>nothing beyond that helps.</b> Diversification has a floor and the floor is correlation.</p>"},{"i":"0A-22","v":"0A","s":"0a-17-the-distributions-you-actually-need","q":"Roughly what excess kurtosis do daily equity returns show, and what is the practical consequence?","a":"<p>Typically <b>3 to 8</b>, against the normal's 0. A five-sigma day under a normal is a once-in-7000-year event; the S&amp;P has had several since 1950.</p><p>Size positions on normal tails and you will be wrong in exactly the direction that hurts. Use Student-t with &nu; fitted, or empirical/EVT quantiles.</p>"},{"i":"0A-23","v":"0A","s":"0a-18-the-two-limit-theorems-and-what-they-do-not","q":"State four things the central limit theorem does <em>not</em> say.","a":"<ol><li>Nothing about the <b>tails</b> — convergence is fastest in the centre; the far tail can be poor at any sample size you will have</li><li>It requires <b>finite variance</b> — otherwise the limit is a stable law</li><li>It requires <b>weak dependence</b> — financial vol clusters, so the effective sample size is far below n</li><li>n = 30 is <b>not</b> sufficient for skewed, fat-tailed data</li></ol>"},{"i":"0A-24","v":"0A","s":"0a-18-the-two-limit-theorems-and-what-they-do-not","q":"What is the standard error of an annualised Sharpe ratio, and why is the units convention the trap?","a":"<p><b>SE &asymp; 1/&radic;T with T in years.</b> Exactly: &radic;((1 + SR&sup2;/(2q))/T), and the correction is divided by 2q = 504 for daily data, so it is negligible.</p><p>The trap: the textbook form &radic;((1 + &frac12;SR&sup2;)/n) uses the <b>per-period</b> Sharpe and n observations. Mixing an annualised SR into it overstates the error by roughly 20%.</p>"},{"i":"0A-25","v":"0A","s":"0a-20-hypothesis-testing-and-what-a-t-statistic-ac","q":"Give the identity relating a Sharpe ratio to a t-statistic.","a":"<p><b>t = SR &times; &radic;(years).</b> Exactly, not approximately.</p><p>Sharpe 2.0 over one year is t = 2.0 — not significant once you account for having looked at more than one strategy. Sharpe 1.0 over nine years is t = 3.0, which is real evidence. <b>If someone has not told you the track record length, they have not told you anything.</b></p>"},{"i":"0A-26","v":"0A","s":"0a-20-hypothesis-testing-and-what-a-t-statistic-ac","q":"State two things a p-value is not.","a":"<ul><li>It is <b>not</b> P(H<sub>0</sub> | data) — that needs a prior, and the two can differ by an order of magnitude, always flattering the researcher</li><li>It is <b>not</b> a measure of effect size — with 10M ticks an untradeable 0.01 bp edge has p &lt; 10<sup>&minus;9</sup></li><li>It is <b>not valid</b> if you chose the hypothesis after seeing the data</li></ul>"},{"i":"0A-27","v":"0A","s":"0a-20-hypothesis-testing-and-what-a-t-statistic-ac","q":"Which of Type I and Type II error should a trader fear more, and why is the convention backwards?","a":"<p>Convention sets &alpha; = 0.05 and tolerates &beta; = 0.20. For a trader that is backwards.</p><p>A <b>Type II</b> error costs you an opportunity. A <b>Type I</b> error costs you capital, time, and the confidence to run the next system. Given many tests and a low prior, the correct posture is a much stricter &alpha; — accepting that you will miss real edges as the price.</p>"},{"i":"0A-28","v":"0A","s":"0a-21-regression-derived-and-diagnosed","q":"Of the OLS assumptions, which one biases &beta;&#770; itself — and what do the others threaten?","a":"<p>Only <b>exogeneity</b> (E[&epsilon;|X] = 0) threatens the estimate. The others — homoscedasticity, no autocorrelation, normal errors — threaten the <b>standard errors</b>.</p><p>Which is why HAC (Newey&ndash;West) standard errors should be your default, not a robustness check. Textbook SEs on overlapping-window financial data inflate t-statistics by 2&ndash;3&times;.</p>"},{"i":"0A-29","v":"0A","s":"0a-22-optimisation-convexity-lagrange-and-kkt","q":"What does convexity buy you, and name two realistic constraints that destroy it.","a":"<p>For a convex objective over a convex set, <b>every local minimum is global</b>, solutions can be certified optimal, and solvers reach them reliably.</p><p>Destroyed by: <b>cardinality constraints</b> ('hold at most 30 names'), minimum lot sizes, and most realistic transaction-cost models. Then: no optimality certificate, start-point dependence, results that change when you reorder the assets.</p>"},{"i":"0A-30","v":"0A","s":"0a-22-optimisation-convexity-lagrange-and-kkt","q":"What does a KKT multiplier of zero on a position cap tell you? And a large positive one?","a":"<p>Complementary slackness: &mu;h(x) = 0 with &mu; &ge; 0.</p><p><b>Zero</b> — the constraint is slack; the position is below its cap and unaffected by it. <b>Positive</b> — the constraint binds, and its value is the <b>shadow price</b>: what relaxing that cap is worth. Scanning the multipliers after an optimise is the fastest way to see what is actually driving a solution.</p>"},{"i":"0A-31","v":"0A","s":"0a-23-numerical-hygiene-when-the-arithmetic-lies","q":"Why should money never be stored as a float?","a":"<p>Rounding eventually produces an order for 99.99999999 shares, which some venues reject and others silently truncate — and reconciliation then breaks with a discrepancy nobody can source.</p><p>Use <b>integer minor units</b> (cents, satoshis) or a decimal type. Free at the start, genuinely painful to retrofit.</p>"},{"i":"0A-32","v":"0A","s":"0a-23-numerical-hygiene-when-the-arithmetic-lies","q":"Name the numerically stable way to compute a variance in a stream, and why the textbook formula fails.","a":"<p><b>Welford's algorithm.</b> E[X&sup2;] &minus; (E[X])&sup2; subtracts two large nearly-equal numbers and can return a <em>negative</em> variance on real price data — which then propagates as NaN through a square root, usually two modules away from the cause.</p>"},{"i":"0B-1","v":"0B","s":"0b-1-the-environment-set-up-once-and-correctly","q":"Why is a lockfile not optional in research code?","a":"<p>A backtest result is a claim about the world. If it depends on the pandas version installed when you ran it — and behaviour <em>does</em> change between versions around resampling, alignment and NaN handling — the claim is not reproducible and the number is not evidence.</p><p>The lockfile is what turns 'I got Sharpe 1.3' into a statement anyone, including you in six months, can check. Commit it.</p>"},{"i":"0B-2","v":"0B","s":"0b-2-the-language-in-one-pass-for-numerical-work","q":"What is wrong with <code>def f(x, history=[]):</code>?","a":"<p>The list is created <b>once, at definition</b>, and shared by every call forever. State leaks between backtest runs, and it never raises.</p><p>Correct: <code>history=None</code> then <code>history = [] if history is None else history</code>.</p>"},{"i":"0B-3","v":"0B","s":"0b-3-numpy-the-mental-model-then-the-api","q":"In NumPy, what does the <code>axis</code> argument name?","a":"<p>The dimension that <b>collapses</b>. For a (days &times; assets) array, <code>axis=0</code> collapses days and leaves one number per asset; <code>axis=1</code> collapses assets and leaves one number per day.</p><p>If you can state which dimension should disappear, you know which axis to pass, every time.</p>"},{"i":"0B-4","v":"0B","s":"0b-3-numpy-the-mental-model-then-the-api","q":"List the NumPy performance rules in order of impact.","a":"<ol><li><b>Do not loop over rows</b> — vectorised is 50&ndash;200&times; faster; this is the whole game</li><li><b>Preallocate</b> — <code>np.append</code> in a loop is quadratic</li><li><b>Watch dtype</b> — an accidental <code>object</code> dtype loses every advantage</li><li><b>Mind memory layout</b> — last-axis operations are far faster on C-ordered arrays</li><li><b>numba/Cython last</b>, and only after profiling</li></ol>"},{"i":"0B-5","v":"0B","s":"0b-4-pandas-the-safe-parts-and-the-parts-that-will","q":"Name the four pandas defaults that produce lookahead or silent corruption.","a":"<ol><li><code>rolling(n)</code> <b>includes the current bar</b> — you must <code>.shift(1)</code></li><li><code>ffill()</code> on fundamentals can propagate backwards in reporting time</li><li><code>dropna()</code> silently changes the universe and can introduce survivorship bias</li><li><code>df.corr()</code> uses pairwise-complete observations, so pairs are computed over different windows and the matrix need not be PSD</li></ol>"},{"i":"0B-6","v":"0B","s":"0b-6-time-timezones-and-the-bug-that-silently-inva","q":"What is the highest-yield single test on any new strategy?","a":"<p><b>Shift the entire signal forward by one bar and re-run.</b></p><p>Performance should degrade, sharply for a short-horizon strategy. If it improves, or barely changes, you have a lookahead problem or no edge at all. One line.</p>"},{"i":"0B-7","v":"0B","s":"0b-6-time-timezones-and-the-bug-that-silently-inva","q":"Name five rules for handling time in a trading system.","a":"<ol><li>Store everything in <b>UTC</b>; a naive timestamp should not exist in your system</li><li>Know your <b>bar convention</b> — open-stamped or close-stamped</li><li>Use real <b>exchange calendars</b>, not business-day ranges</li><li>Handle <b>DST</b> explicitly — US and Europe switch on different dates</li><li>Never <code>utcnow()</code> — it returns a naive datetime that lies about itself</li></ol>"},{"i":"0B-8","v":"0B","s":"0b-8-testing-numerical-code","q":"Name the four testing techniques that cover most numerical code.","a":"<ol><li><b>Closed-form comparison</b> — a case you can solve by hand</li><li><b>Property / invariant tests</b> — e.g. x&#8868;&Sigma;x &ge; 0 for any x</li><li><b>Golden files</b> — freeze a known-good output and diff</li><li><b>Metamorphic tests</b> — relations between outputs (doubling gross doubles pre-cost P&amp;L)</li></ol>"},{"i":"0B-9","v":"0B","s":"0b-9-git-as-a-research-log","q":"What makes a research commit worth reading six months later?","a":"<p>The <b>message</b>, not the diff. Prefix conventions: <code>exp:</code> with the result in the message, <code>fix:</code> saying what was wrong, <code>data:</code> flagging that prior results are invalidated.</p><p>And: <b>tag every result you will cite</b>, with the headline numbers in the tag message. A tagged commit is a complete restorable statement — code, config, environment.</p>"},{"i":"0B-10","v":"0B","s":"0b-10-notebooks-and-modules-a-working-compromise","q":"What is the working compromise between notebooks and modules?","a":"<p>All logic in <code>src/</code> as importable modules; notebooks contain <b>orchestration and plots only</b>. Any function that grows past ten lines in a notebook moves out immediately.</p><p>Restart-and-run-all before believing any notebook result. Strip outputs before committing.</p>"},{"i":"0B-11","v":"0B","s":"0b-12-your-first-backtest-end-to-end-and-correct","q":"In a backtest report, in what order should you read the statistics?","a":"<ol><li><b>t-statistic</b>, not Sharpe — the Sharpe is the headline, the t-stat is the content</li><li><b>Standard error</b> — if comparable to the Sharpe you have measured nothing</li><li><b>Turnover &times; cost</b> — is your cost assumption now the most important parameter?</li><li><b>Days in drawdown</b> — what running it will actually feel like</li><li><b>Max drawdown last</b> — most cited, least informative; a single order statistic</li></ol>"},{"i":"0B-12","v":"0B","s":"0b-13-a-repository-layout-that-survives-a-year","q":"Which file in a research repository is the load-bearing one, and why?","a":"<p><code>research/registry.py</code> — the <b>trial counter</b>. Every fit, sweep and 'quick check' appends a row; the row count <em>is</em> your trial count, which the deflated Sharpe ratio needs to mean anything.</p><p>A count maintained by hand is a count you will under-report — not dishonestly, just humanly, because failed quick checks do not feel like trials.</p>"},{"i":"01-1","v":"01","s":"1-2-martingales-and-the-two-fundamental-theorems","q":"State the two Fundamental Theorems of Asset Pricing precisely \u2014 name the no-arbitrage condition, and say what discounted prices become under Q.","a":"<p><b>FTAP I.</b> No free lunch with vanishing risk &hArr; there exists an equivalent measure Q under which discounted prices are local martingales.</p><p><b>FTAP II.</b> The market is complete (every contingent claim replicable) &hArr; that Q is <b>unique</b>.</p>"},{"i":"01-2","v":"01","s":"1-3-brownian-motion-and-quadratic-variation","q":"What is the quadratic variation of Brownian motion over [0,T], and why does it matter?","a":"<p><b>[W,W]<sub>T</sub> = T</b>, in L&sup2; and almost surely. Ordinary differentiable functions have zero quadratic variation.</p><p>This is the precise statement of (dW)&sup2; = dt, which is the extra term in Itô's lemma.</p>"},{"i":"01-3","v":"01","s":"1-5-it-s-lemma","q":"State Itô's lemma for f(t, X<sub>t</sub>) with dX = &mu;dt + &sigma;dW.","a":"<p>df = (&part;<sub>t</sub>f + &mu;&part;<sub>x</sub>f + &frac12;&sigma;&sup2;&part;<sub>xx</sub>f) dt + &sigma;&part;<sub>x</sub>f dW.</p><p>It is the chain rule plus one second-order term, present because (dW)&sup2; = dt rather than being negligible.</p>"},{"i":"01-4","v":"01","s":"1-6-the-four-processes-worth-knowing","q":"Name the four processes worth knowing and the one thing each is used for.","a":"<ul><li><b>Brownian with drift</b> — the null model for a price</li><li><b>Geometric Brownian</b> — prices that stay positive; Black&ndash;Scholes</li><li><b>Ornstein&ndash;Uhlenbeck</b> — mean reversion; every spread in Volume 3</li><li><b>Jump diffusion</b> — the tail behaviour a diffusion cannot produce</li></ul>"},{"i":"01-5","v":"01","s":"1-6-the-four-processes-worth-knowing","q":"Give the OU half-life and why it is the number you actually trade on.","a":"<p><b>t<sub>&frac12;</sub> = ln 2 / &theta;.</b></p><p>It sets holding period, and therefore turnover, and therefore whether costs eat the edge. An OU spread with a two-day half-life and 8 bp round-trip costs is usually untradeable; the same spread with a twenty-day half-life may not be.</p>"},{"i":"01-6","v":"01","s":"1-7-girsanov-buying-a-drift-change","q":"What does Girsanov let you do, and what does it not change?","a":"<p>Change the <b>drift</b> of a Brownian motion by changing measure. Under the new measure the process is still Brownian, with a different drift.</p><p>It does <b>not</b> change the volatility, and it does not change which events have probability zero (the measures are equivalent). This is why pricing is drift-free but volatility matters enormously.</p>"},{"i":"01-7","v":"01","s":"1-9-discretisation-and-the-error-you-are-actually-ma","q":"Euler&ndash;Maruyama versus Milstein: what are the convergence orders, and which matters for what?","a":"<p>Euler&ndash;Maruyama: <b>strong order 0.5</b>, weak order 1. Milstein: <b>strong order 1</b>.</p><p><b>Strong</b> order matters when you care about the path (barriers, path-dependent payoffs). <b>Weak</b> order matters when you only need the distribution at maturity (a European price). Most option pricing needs only weak convergence, which is why Euler survives.</p>"},{"i":"01-8","v":"01","s":"1-10-calibrating-an-ou-process-from-data","q":"How do you calibrate an OU process from data, and what is the estimator's known problem?","a":"<p>Regress &Delta;X<sub>t</sub> on X<sub>t&minus;1</sub>: the slope gives &theta;, the intercept &theta;&mu;, the residual variance &sigma;&sup2;.</p><p>The problem: mean-reversion speed is <b>biased upward in small samples</b> — the same bias that makes unit-root tests over-reject. Your half-life estimate is optimistic, and so is the strategy built on it.</p>"},{"i":"02-1","v":"02","s":"2-1-the-continuous-double-auction","q":"In a continuous double auction, what are the two ways an order can be handled, and what does each cost you?","a":"<p><b>Aggressive</b> (crosses the spread) — immediate fill, pay half the spread plus impact. <b>Passive</b> (rests in the book) — earn the spread, but only fill when someone wants to trade against you, which is disproportionately when they know something.</p><p>That asymmetry is adverse selection and it is the subject of 2.2.</p>"},{"i":"02-2","v":"02","s":"2-2-adverse-selection-glosten-milgrom","q":"What does Glosten&ndash;Milgrom say determines the spread?","a":"<p>The spread compensates the market maker for <b>adverse selection</b>: the probability the counterparty is informed. It exists even with zero inventory cost, zero fees and infinite competition.</p><p>Consequence: a wider spread signals more informed flow, not less liquidity provision.</p>"},{"i":"02-3","v":"02","s":"2-3-kyle-s-lambda-and-market-impact","q":"Define Kyle's lambda and state the three ways it is wrong.","a":"<p>&lambda; = the linear, permanent price impact per unit of signed order flow: &Delta;P = &lambda;Q.</p><p>Wrong because impact is <b>concave</b> (square root, not linear), <b>decays</b> rather than persisting, and is <b>cross-sectional</b> — trading one asset moves correlated assets. Volume 2A fixes all three.</p>"},{"i":"02-4","v":"02","s":"2-4-order-flow-imbalance","q":"What is order flow imbalance and what is it good for?","a":"<p>Signed volume or signed book-change over a window. It is the single most reliable short-horizon price predictor in microstructure.</p><p>It is also almost entirely arbitraged at institutional latency; for a retail-latency trader its value is in <b>execution</b> (when to cross) rather than as standalone alpha.</p>"},{"i":"02-5","v":"02","s":"2-6-queue-position-the-variable-that-decides-whether","q":"Why is queue position the variable that decides whether you get filled?","a":"<p>A passive order joins the <b>back</b> of the queue and advances only as orders ahead of it trade or cancel. At the front you fill often and on your terms; at the back you fill mainly when the price is about to move against you.</p><p>A backtest that fills limit orders at the touch without modelling queue position is not slightly optimistic — it is modelling a different market.</p>"},{"i":"02-6","v":"02","s":"2-8-realistic-cost-accounting","q":"What does realistic cost accounting have to include beyond commission?","a":"<p>Spread crossed, market impact (2A), <b>borrow</b> for shorts, <b>financing</b> on leverage, and the opportunity cost of unfilled passive orders.</p><p>The last is invisible in most backtests: an order that did not fill has a cost equal to the move you missed, and passive strategies fail live largely through this channel.</p>"},{"i":"2A-1","v":"2A","s":"2a-1-why-linear-permanent-impact-cannot-be-right","q":"State the square-root law of market impact and its four practical features.","a":"<p>&Delta;P &asymp; Y &sigma; &radic;(Q/V).</p><ul><li><b>Concave</b> — doubling size costs 1.41&times;, not 2&times;</li><li>Scales with <b>&sigma;</b> — cost is quoted in volatility units</li><li>Depends on <b>Q/V only</b> — participation rate is the state variable</li><li>No dependence on horizon — the total is set by size; the <em>path</em> sets how much is temporary</li></ul>"},{"i":"2A-2","v":"2A","s":"2a-1-why-linear-permanent-impact-cannot-be-right","q":"Give the no-data argument that linear permanent impact cannot be right.","a":"<p>Buy Q then immediately sell Q. Under linear permanence you moved the price up &lambda;Q and back down &lambda;Q, at <b>zero net cost</b> — a zero-time round trip for free.</p><p>So impact is not permanent, or not linear, or both. Empirically both.</p>"},{"i":"2A-3","v":"2A","s":"2a-2-the-propagator-model","q":"Order flow is strongly autocorrelated but prices are near-martingales. How are those reconciled?","a":"<p>Impact must <b>decay at exactly the rate that offsets the flow autocorrelation</b>. This gives the diffusivity constraint &beta; &asymp; (1&minus;&gamma;)/2 relating the propagator decay to the flow autocorrelation exponent.</p><p>So &beta; is not a free parameter you fit. If your fitted &beta; badly violates the relation, the fit is wrong, not the market.</p>"},{"i":"2A-4","v":"2A","s":"2a-2-the-propagator-model","q":"Roughly what fraction of a metaorder's peak impact is permanent, and why does the split matter for a backtest?","a":"<p>About <b>one third permanent, two thirds decays</b> after the metaorder completes.</p><p>Charge permanent impact on the <b>position</b> and temporary on the <b>trajectory</b>. A flat basis-point charge cannot express that a two-day and a two-month holding period at the same turnover face different costs.</p>"},{"i":"2A-5","v":"2A","s":"2a-3-the-microprice","q":"Why is the mid-price a poor state variable, and what replaces it?","a":"<p>With 10,000 on the bid and 100 on the ask, the next trade will probably lift the ask — the mid is not the expectation of the next price.</p><p>The <b>microprice</b> is the actual conditional expectation of the future mid given imbalance and spread, estimated by iterating to a fixed point. It is a martingale by construction, which is what makes it the right quoting anchor and the right benchmark for execution quality.</p>"},{"i":"2A-6","v":"2A","s":"2a-4-cross-impact","q":"What sets the capacity of a factor-concentrated portfolio, and why?","a":"<p>Its <b>factor exposure</b>, not the liquidity of its individual names.</p><p>Cross-impact means buying a whole sector costs closer to one metaorder in the combined factor exposure than to n independent square-root costs — and that is <em>larger</em>, because impact is concave in each name but factor exposure adds linearly.</p>"},{"i":"2A-7","v":"2A","s":"2a-5-calibrating-impact-from-your-own-fills","q":"Why is every naive impact estimate biased downward, and by how much?","a":"<p>You trade more when you expect to, which is often when liquidity is good. Conditioning on executed orders selects favourable conditions.</p><p>Typically <b>20&ndash;40% too low</b>, worst for opportunistic strategies — the ones that need the estimate most. Assume your fitted Y is optimistic and stress it upward in any capacity calculation.</p>"},{"i":"03-1","v":"03","s":"3-1-stationarity-unit-roots-and-the-difference-that-","q":"What is a spurious regression and what prevents it?","a":"<p>Regressing one random walk on another produces high R&sup2; and a large t-statistic with no relationship. The t-statistic <b>diverges</b> rather than being centred on zero.</p><p>Prevention: test for unit roots first, and work with returns or a cointegrating combination — never with levels.</p>"},{"i":"03-2","v":"03","s":"3-2-cointegration-engle-granger-and-johansen","q":"Engle&ndash;Granger versus Johansen: when do you use each?","a":"<p><b>Engle&ndash;Granger</b>: two series, one cointegrating relation, simple two-step. Sensitive to which variable you put on the left.</p><p><b>Johansen</b>: n series, tests for the <em>number</em> of cointegrating relations, symmetric in the variables. Use it for baskets; use Engle&ndash;Granger for a single pair when you want something you can debug.</p>"},{"i":"03-3","v":"03","s":"3-3-from-spread-to-trade-the-ou-layer","q":"How does a cointegration test become a trade?","a":"<p>Fit the cointegrating vector to get the spread, then fit an <b>OU process</b> to the spread. The OU gives you &theta; (hence half-life), &mu; (fair value) and &sigma; (the scale for z-score entry thresholds).</p><p>Without the OU layer you have a statistical relationship and no holding period, which means no way to know whether costs eat it.</p>"},{"i":"03-4","v":"03","s":"3-5-selecting-pairs-without-discovering-noise","q":"How do you select pairs without discovering noise?","a":"<p>Restrict the candidate set <b>economically before testing</b> (same sector, same supply chain, dual listings), not by scanning all n(n&minus;1)/2 combinations.</p><p>With 500 names there are 124,750 pairs; at a 5% test size, over 6,000 will pass by chance. The trial count is the whole problem, and pre-restricting the universe is the only real defence.</p>"},{"i":"03-5","v":"03","s":"3-6-why-cointegration-breaks","q":"Name the three ways cointegration breaks.","a":"<ol><li><b>Structural</b> — a merger, a spin-off, a change of business mix. The relationship genuinely no longer exists</li><li><b>Crowding</b> — the trade works until enough capital is in it, then the exit is simultaneous</li><li><b>It was never there</b> — the relation was a Type I error from the selection scan</li></ol><p>Only the first is detectable in advance, and only sometimes.</p>"},{"i":"04-1","v":"04","s":"4-1-the-stylised-facts-any-model-must-reproduce","q":"Name the stylised facts of returns any model must reproduce.","a":"<ul><li>Near-zero autocorrelation in returns</li><li><b>Strong, persistent autocorrelation in |returns|</b> — volatility clustering</li><li>Fat tails (excess kurtosis 3&ndash;8 daily)</li><li>Leverage effect — negative returns raise future volatility more than positive ones</li><li>Aggregational Gaussianity — monthly returns are much closer to normal than daily</li></ul>"},{"i":"04-2","v":"04","s":"4-3-garch-and-its-asymmetric-extensions","q":"Write GARCH(1,1) and say what each parameter controls.","a":"<p>&sigma;&sup2;<sub>t</sub> = &omega; + &alpha;&epsilon;&sup2;<sub>t&minus;1</sub> + &beta;&sigma;&sup2;<sub>t&minus;1</sub>.</p><p><b>&alpha;</b> — reaction to the last shock. <b>&beta;</b> — persistence. <b>&alpha;+&beta;</b> — how slowly volatility mean-reverts; typically 0.95&ndash;0.99 for daily equities, which is why volatility forecasts have long memory. &omega;/(1&minus;&alpha;&minus;&beta;) is the long-run variance.</p>"},{"i":"04-3","v":"04","s":"4-4-estimation-quasi-maximum-likelihood","q":"Why is GARCH estimated by <em>quasi</em>-maximum likelihood?","a":"<p>Because the Gaussian likelihood gives consistent parameter estimates <b>even when the true innovations are not Gaussian</b> — which they are not.</p><p>The standard errors, however, need a sandwich correction. Using the naive Gaussian standard errors on fat-tailed data understates them.</p>"},{"i":"04-4","v":"04","s":"4-5-realised-volatility-and-the-har-model","q":"What is the HAR model and why does something so simple work?","a":"<p>Regress realised volatility on its own daily, weekly and monthly averages.</p><p>It works because it approximates <b>long memory</b> with three terms and no long-memory machinery, and because the heterogeneous-horizon structure has an economic story (different participants act on different horizons). It routinely beats GARCH on realised-volatility data.</p>"},{"i":"04-5","v":"04","s":"4-6-markov-regime-switching","q":"What is the trap in evaluating a Markov regime-switching model?","a":"<p>The <b>smoothed</b> probability P(s<sub>t</sub> | all data) uses the future. It identifies every crisis perfectly and is unusable for trading.</p><p>The <b>filtered</b> probability P(s<sub>t</sub> | data to t) is what you can act on: much noisier, lagging by days to weeks. A backtest on smoothed probabilities can show three times the Sharpe of the same strategy on filtered ones.</p>"},{"i":"04-6","v":"04","s":"4-8-choosing-a-model-for-a-purpose","q":"Match the model to the purpose: forecasting variance, forecasting direction, describing tails, detecting a state change.","a":"<ul><li><b>Variance</b> — GARCH or HAR (HAR if you have intraday data)</li><li><b>Direction</b> — essentially nothing in this volume; returns are near-unpredictable in the mean</li><li><b>Tails</b> — EVT (12.2), not a fitted parametric distribution</li><li><b>State change</b> — regime switching, and only as a <em>sizing</em> input, not a timing signal</li></ul>"},{"i":"4A-1","v":"4A","s":"4a-1-why-a-posterior-beats-a-point-estimate-here","q":"Why is the Bayesian framing practically, not philosophically, motivated in finance?","a":"<p>Financial data is short relative to the number of things you want to estimate, so the likelihood is often nearly flat in the directions that matter — and a flat likelihood maximised is a number with no content.</p><p>Ridge is a posterior mode under a Gaussian prior; the lasso under a Laplace prior; Ledoit&ndash;Wolf shrinkage is a Bayesian estimator in frequentist clothes; Black&ndash;Litterman is explicitly Bayesian. If you accept shrinkage you already accept the argument.</p>"},{"i":"4A-2","v":"4A","s":"4a-2-mcmc-in-the-amount-of-detail-you-need","q":"Name the four MCMC convergence diagnostics and their thresholds.","a":"<ol><li><b>Split R&#770;</b> across &ge;4 chains — require &lt; 1.01</li><li><b>Effective sample size</b> — &ge; 400 per parameter for stable tail quantiles</li><li><b>Divergences</b> (HMC/NUTS) — <em>any</em> divergence invalidates the run; reparameterise</li><li><b>Trace plots</b> — look at them; unmixed chains are obvious in two seconds and invisible in a summary table</li></ol>"},{"i":"4A-3","v":"4A","s":"4a-3-state-space-models-and-filtering","q":"Give the two-step structure every filter shares, and the two Kalman implementation details that matter.","a":"<p><b>Predict</b> forward using the dynamics, then <b>correct</b> using the observation, weighted by relative uncertainty.</p><p>(1) Use the <b>Joseph form</b> for the covariance update — the compact form loses symmetry and the filter diverges silently after a few thousand steps. (2) Fit Q and R by <b>maximising the returned log-likelihood</b>; their ratio controls how fast the state may move, so choosing it by eye is choosing your answer.</p>"},{"i":"4A-4","v":"4A","s":"4a-4-hidden-markov-models-and-regimes","q":"What are regime models actually good for?","a":"<p><b>Position sizing and expectation setting</b>, not timing entries. The filtered signal lags too much and is too noisy to beat a simple volatility target at timing.</p><p>Scaling exposure by P(calm) is a smooth, well-behaved risk control, and knowing the model puts 40% weight on the stressed regime is useful context for a drawdown diagnostic.</p>"},{"i":"05-1","v":"05","s":"5-1-the-linear-factor-model","q":"Write the linear factor model and say what each piece is estimated from.","a":"<p>r<sub>i</sub> = &alpha;<sub>i</sub> + &Sigma;<sub>k</sub> &beta;<sub>ik</sub>f<sub>k</sub> + &epsilon;<sub>i</sub>, giving &Sigma; = B&Omega;B&#8868; + D.</p><p>This reduces the covariance from n(n+1)/2 free parameters to nk + n — for n=3000, k=10 that is 33,000 rather than 4.5 million. Which is why factor models exist at all (see 11A.1).</p>"},{"i":"05-2","v":"05","s":"5-2-signal-hygiene-the-pipeline-every-alpha-must-pas","q":"Name the stages of signal hygiene, in order.","a":"<ol><li><b>Winsorise or rank</b> — kill the outliers that will otherwise be the whole signal</li><li><b>Neutralise</b> — remove sector, size, beta exposure you did not intend to take</li><li><b>Standardise cross-sectionally</b> — z-score or rank within each date</li><li><b>Lag</b> — align to information actually available</li></ol><p>Skipping neutralisation is how a 'new alpha' turns out to be a sector bet.</p>"},{"i":"05-3","v":"05","s":"5-3-evaluating-a-signal-before-you-ever-backtest-it","q":"How do you evaluate a signal before ever running a backtest?","a":"<p><b>Information coefficient</b>: the cross-sectional rank correlation between the signal and forward returns, per date. Then look at the time series of ICs — mean, standard error, and stability.</p><p>An IC of 0.03&ndash;0.05 is a genuinely usable signal. This is far more informative than a backtest because it has no position sizing, no costs and no path dependence to hide behind.</p>"},{"i":"05-4","v":"05","s":"5-4-the-canonical-factors-and-what-is-left-of-them","q":"State the Fundamental Law of Active Management and its practical reading.","a":"<p>IR &asymp; IC &times; &radic;(breadth), with a transfer coefficient multiplier for constraints.</p><p>Practical reading: a weak signal applied to many names beats a strong signal applied to few. And <b>constraints destroy the relationship</b> — the transfer coefficient is often 0.3&ndash;0.6 in a real constrained portfolio, which quietly halves your information ratio.</p>"},{"i":"06-1","v":"06","s":"6-1-structuring-data-information-driven-bars","q":"Why use information-driven bars instead of time bars?","a":"<p>Time bars sample a market that does not deliver information at a constant rate: a 5-minute bar at 03:00 and at the open contain wildly different amounts of it.</p><p>Volume, dollar or imbalance bars sample at roughly constant information, which gives returns closer to IID and much closer to normal — which is what every downstream statistical method assumes.</p>"},{"i":"06-2","v":"06","s":"6-2-labelling-the-triple-barrier-method","q":"What is the triple-barrier method labelling, and what does it fix?","a":"<p>Label each observation by which of three barriers is hit first: profit target, stop loss, or time limit.</p><p>It fixes the fact that a fixed-horizon return label ignores the path — a position that would have been stopped out on day 2 is labelled by its day-10 return, which is a trade you would never have held.</p>"},{"i":"06-3","v":"06","s":"6-3-meta-labelling-separate-direction-from-size","q":"What is meta-labelling and why does it help?","a":"<p>A primary model decides <b>direction</b>; a secondary model decides <b>whether to act and at what size</b>, trained on whether the primary model's calls were right.</p><p>It helps because the two problems have different signal-to-noise. Direction is nearly unpredictable; 'is this particular call likely to be right' is a much easier, better-balanced classification, and it improves precision without touching the primary model.</p>"},{"i":"06-4","v":"06","s":"6-4-fractional-differentiation-stationarity-without-","q":"What problem does fractional differentiation solve?","a":"<p>Prices are non-stationary; returns are stationary but have thrown away all memory of the level. Fractional differencing with 0 &lt; d &lt; 1 finds the <b>minimum</b> differencing that achieves stationarity while retaining as much memory as possible.</p><p>Typically d &asymp; 0.3&ndash;0.5 suffices, which keeps far more information than d = 1.</p>"},{"i":"06-5","v":"06","s":"6-5-the-validation-problem-and-why-it-is-the-whole-b","q":"Why does standard k-fold cross-validation fail on financial data, and what replaces it?","a":"<p>Observations overlap in time and are serially dependent, so a random fold puts near-duplicate observations in train and test — the model is scored on data it effectively saw.</p><p>Replace with <b>purged k-fold with embargo</b>: remove training observations whose label horizon overlaps the test set, and embargo a further window after it. Or walk-forward.</p>"},{"i":"06-6","v":"06","s":"6-6-sample-weights-not-every-observation-is-worth-th","q":"Why weight samples in financial ML, and by what?","a":"<p>Because overlapping labels mean observations are not equally informative. Weight by <b>uniqueness</b> — the inverse of how many other labels share the same return window.</p><p>Without this, a period with many overlapping labels dominates the fit purely by being over-counted.</p>"},{"i":"06-7","v":"06","s":"6-7-feature-importance-without-fooling-yourself","q":"What is wrong with standard feature importance on correlated features?","a":"<p>With substitute effects, importance is <b>split arbitrarily</b> between correlated features — each looks unimportant because the other can do its job.</p><p>Use mean-decrease-accuracy on a purged CV, cluster correlated features and report importance per cluster, or use single-feature importance to detect substitution.</p>"},{"i":"07-1","v":"07","s":"7-1-sequence-architectures-and-what-each-is-for","q":"When does deep learning beat gradient boosting on financial data, and when does it not?","a":"<p>It wins where the input has <b>structure a network can exploit</b>: raw order-book snapshots, text, images, long sequences. It loses on tabular cross-sectional features, where gradient-boosted trees are better and far cheaper.</p><p>Most 'alpha from deep learning' claims are on tabular data, where the honest baseline is a boosted tree and it is rarely beaten.</p>"},{"i":"07-2","v":"07","s":"7-2-financial-nlp-that-is-worth-the-effort","q":"What is the main risk in using a language model on financial text?","a":"<p><b>Lookahead through the model itself.</b> A model pretrained on data through 2024 already knows what happened, so applying it to 2020 text is not an out-of-sample test — the sentiment it assigns is contaminated by hindsight.</p><p>Only a model whose training cutoff precedes the evaluation period gives an honest backtest.</p>"},{"i":"07-3","v":"07","s":"7-4-language-models-as-extraction-tools-not-oracles","q":"Why is a Sharpe from a deep-learning backtest less trustworthy than the same Sharpe from a linear model?","a":"<p>Because the effective number of trials is enormous and mostly unrecorded: architecture, depth, width, learning rate, seed, early-stopping point. Every one is a trial.</p><p>Volume 18.2's deflation needs a trial count, and for a neural network the honest count is in the hundreds even if you only 'ran it a few times'.</p>"},{"i":"08-1","v":"08","s":"8-1-black-scholes-from-the-hedging-argument","q":"Give the Black&ndash;Scholes PDE and say what its derivation actually assumes.","a":"<p>&part;<sub>t</sub>V + &frac12;&sigma;&sup2;S&sup2;&part;<sub>SS</sub>V + rS&part;<sub>S</sub>V &minus; rV = 0.</p><p>It assumes <b>continuous costless hedging</b> and constant &sigma;. The derivation is a hedging argument: hold &minus;&part;<sub>S</sub>V of the underlying and the portfolio becomes riskless, so it must earn r.</p>"},{"i":"08-2","v":"08","s":"8-2-the-greeks-with-their-trading-meaning","q":"Which Greek is the P&amp;L of a delta-hedged option position, and what is the formula?","a":"<p><b>Gamma.</b> Delta-hedged P&amp;L over dt &asymp; &frac12;&Gamma;S&sup2;(realised variance &minus; implied variance) dt.</p><p>So a delta-hedged long option is a <b>long realised-vol, short implied-vol</b> position. That is the trade, and every other Greek is bookkeeping around it.</p>"},{"i":"08-3","v":"08","s":"8-3-the-volatility-surface-what-the-smile-is-telling","q":"Why is implied volatility not a forecast of realised volatility?","a":"<p>Because it contains a <b>variance risk premium</b>. Implied exceeds subsequent realised on average, across markets and decades, as compensation to whoever is short volatility.</p><p>Treating implied as a forecast produces a systematic 'the market is too scared' signal that is actually you being paid to bear a real risk.</p>"},{"i":"08-4","v":"08","s":"8-5-variance-swaps-and-model-free-replication","q":"What is the difference between sticky-strike and sticky-delta, and why does it matter?","a":"<p><b>Sticky-strike</b>: implied vol at a fixed strike stays put as spot moves. <b>Sticky-delta (moneyness)</b>: the smile moves with spot.</p><p>They imply different deltas for the same option. Your hedge ratio depends on which you assume, and being wrong shows up as a systematic hedging P&amp;L that looks like a trading loss.</p>"},{"i":"8A-1","v":"8A","s":"8a-1-what-the-surface-actually-looks-like","q":"What single empirical fact rules out ordinary diffusive stochastic volatility?","a":"<p>The <b>at-the-money skew decays too slowly</b>. Diffusive models give T<sup>&minus;1/2</sup>; the market shows a power law with a small exponent, so such models cannot fit the one-week and one-month smiles with the same parameters.</p><p>Two escapes: add <b>jumps</b>, or make the variance <b>rough</b> (H &asymp; 0.1).</p>"},{"i":"8A-2","v":"8A","s":"8a-2-heston","q":"Map the five Heston parameters to the surface features they control.","a":"<ul><li><b>&kappa;</b> — speed of variance mean reversion</li><li><b>&theta;</b> — long-run variance; the level the term structure approaches</li><li><b>&xi;</b> — vol of vol; smile convexity</li><li><b>&rho;</b> — spot/vol correlation; the skew</li><li><b>v<sub>0</sub></b> — current variance; the ATM level</li></ul>"},{"i":"8A-3","v":"8A","s":"8a-2-heston","q":"What is the Feller condition, and what do you do when calibration violates it?","a":"<p>2&kappa;&theta; &ge; &xi;&sup2; keeps the variance strictly positive. Fitting real equity smiles almost always violates it, because the observed convexity needs a large &xi;.</p><p>Standard response: let it violate and use a scheme built for it (<b>QE</b> or full-truncation Euler). Naive Euler gives negative variances, and clipping at zero biases prices upward in a way that grows with &xi; and is invisible.</p>"},{"i":"8A-4","v":"8A","s":"8a-3-sabr-and-why-it-dominates-in-rates","q":"In SABR, why is &beta; fixed by convention rather than fitted?","a":"<p>&beta; and &rho; are close to <b>jointly unidentified</b> from a single smile — many combinations fit equally well, so fitting both gives parameters that jump between days without the market moving.</p><p>Fix &beta; from the observed backbone (a time-series question) and fit only &rho; and &nu; daily. General lesson: when two parameters are jointly unidentified, pin one from a different data source.</p>"},{"i":"8A-5","v":"8A","s":"8a-4-local-volatility-lsv-and-rough-volatility","q":"What is local volatility good for, and what is it definitively not good for?","a":"<p><b>Good for</b>: pricing European exotics consistently with the vanilla surface, which it reproduces exactly by construction.</p><p><b>Not good for</b>: anything path-dependent or forward-starting, and not for hedge ratios. Its <em>dynamics</em> are wrong — it predicts the smile moves in a way the market does not.</p>"},{"i":"8A-6","v":"8A","s":"8a-4-local-volatility-lsv-and-rough-volatility","q":"What is the one model-independent takeaway from rough volatility for a systematic trader?","a":"<p>Log-volatility is <b>rough</b> (H &asymp; 0.1), far below the H = 0.5 of a diffusion. Consequence: <b>volatility forecasts decay much faster than a smooth mean-reverting model implies</b>.</p><p>A GARCH-style forecast systematically overstates volatility persistence at short horizons. That single observation improves vol targeting and costs nothing to adopt.</p>"},{"i":"8A-7","v":"8A","s":"8a-5-choosing-and-the-variance-risk-premium","q":"Why do standard statistics flatter a short-volatility strategy, and what should replace them?","a":"<p>Sharpe, hit rate, max drawdown over five years and the equity-curve shape all assume roughly symmetric returns. A short-variance payoff has skew around &minus;3 and kurtosis in the tens.</p><p>Size it by <b>maximum loss</b>, not by volatility or Sharpe: defined-risk structures, explicit tail hedges, and a size that survives the worst historically observed single-day move.</p>"},{"i":"09-1","v":"09","s":"9-1-the-latency-hierarchy","q":"What actually dominates end-to-end latency, and what does that imply about optimisation effort?","a":"<p>Network path and exchange gateway time, not your code — unless your code is doing something pathological. Then: kernel bypass, then serialisation, then application logic.</p><p>Implication: measure the whole path before optimising any part. Most latency work on the application side is effort spent on 5% of the budget.</p>"},{"i":"09-2","v":"09","s":"9-2-mechanical-sympathy-the-three-rules","q":"Why do you measure latency in percentiles rather than means?","a":"<p>Because the distribution is heavily right-tailed and the <b>tail is where you lose money</b>. A mean of 20&micro;s with a p99.9 of 4ms means one in a thousand orders arrives after the state has changed.</p><p>Report p50, p99, p99.9 and max. A mean latency figure is close to meaningless.</p>"},{"i":"09-3","v":"09","s":"9-4-measure-the-tail-never-the-mean","q":"Name three sources of jitter that are not your code.","a":"<ul><li><b>GC pauses</b> in a managed runtime</li><li><b>Page faults</b> and TLB misses — pre-fault and pin memory</li><li><b>Scheduler migration</b> and interrupts — pin threads to isolated cores</li></ul><p>Also NUMA effects: memory on the wrong socket costs more than most algorithmic choices you will make.</p>"},{"i":"10-1","v":"10","s":"10-1-the-almgren-chriss-framework","q":"State the Almgren&ndash;Chriss trade-off and what determines the optimal trajectory shape.","a":"<p>Trade fast and pay <b>impact</b>; trade slow and bear <b>timing risk</b>. The optimum minimises E[cost] + &lambda;Var[cost].</p><p>Higher risk aversion or higher volatility &rarr; front-loaded. Lower &rarr; closer to linear (TWAP). The urgency parameter is &radic;(&lambda;&sigma;&sup2;/&eta;).</p>"},{"i":"10-2","v":"10","s":"10-3-alpha-decay-changes-everything","q":"How does alpha decay change the optimal execution schedule?","a":"<p>It front-loads it, and often dramatically. If your signal has a half-life of hours, executing over a day means trading most of your size after the alpha is gone.</p><p>The correct comparison is not 'impact versus risk' but 'impact versus <b>alpha lost to delay</b>', and for a fast signal the second term dominates.</p>"},{"i":"10-3","v":"10","s":"10-4-measuring-execution-quality","q":"Name the standard execution benchmarks and the flaw in each.","a":"<ul><li><b>Arrival price / implementation shortfall</b> — the honest one; captures everything including delay</li><li><b>VWAP</b> — contaminated by your own trading if you are a large share of volume</li><li><b>TWAP</b> — ignores where the volume actually was</li><li><b>Closing price</b> — encourages dangerous end-of-day concentration</li></ul>"},{"i":"10A-1","v":"10A","s":"10a-1-execution-as-a-markov-decision-process","q":"Give a free correctness test for any RL execution agent.","a":"<p>Train it in a simulator with <b>linear impact and no state beyond (remaining quantity, time)</b>. It must converge to the Almgren&ndash;Chriss trajectory, which is the closed-form solution of exactly that MDP.</p><p>If it does not, the bug is in your implementation, not the market. Almost nobody runs this test and it catches a great deal.</p>"},{"i":"10A-2","v":"10A","s":"10a-3-the-simulator-is-the-hard-part","q":"Name four simulator shortcuts and the policy each one teaches the agent.","a":"<ul><li><b>Limit orders always fill at the touch</b> &rarr; quote passively, never cross &rarr; no fills at all live</li><li><b>No queue position</b> &rarr; post and expect execution &rarr; fills only on adverse moves</li><li><b>Own orders do not move price</b> &rarr; trade one huge slice</li><li><b>Replay the book unchanged</b> &rarr; front-run the recorded future flow &rarr; spectacular backtest, zero live edge</li></ul>"},{"i":"10A-3","v":"10A","s":"10a-4-where-rl-wins-and-where-it-does-not","q":"State the criterion that decides whether RL belongs near a problem.","a":"<p><b>Reward density and horizon.</b> RL needs many independent informative rewards.</p><p>Execution supplies them — thousands of labelled child orders a day, minutes-long horizon. Portfolio allocation supplies about 120 noisy rewards in a decade, and no algorithm extracts a policy from that. This is information-theoretic, not a limitation of current methods.</p>"},{"i":"11-1","v":"11","s":"11-1-mean-variance-and-why-it-fails-in-practice","q":"Why is mean&ndash;variance optimisation called an 'error maximiser'?","a":"<p>&Sigma;<sup>&minus;1</sup> inverts the eigenvalues, so the <b>smallest</b> eigenvalues become the <b>largest</b> weights. The optimiser places its biggest bets on the directions it has estimated worst.</p><p>Stated that way it is obviously a fixable estimation problem rather than a defect in the objective.</p>"},{"i":"11-2","v":"11","s":"11-2-shrinkage-ledoit-wolf","q":"What does Ledoit&ndash;Wolf shrinkage do and why does a biased estimator win?","a":"<p>&Sigma;&#770; = (1&minus;&delta;)S + &delta;F, with &delta;* minimising expected Frobenius loss.</p><p>MSE = Bias&sup2; + Variance. In high dimensions the variance term dominates, so a little bias buys a lot of variance reduction. Unbiasedness is a luxury when you have more parameters than data to support them.</p>"},{"i":"11-3","v":"11","s":"11-3-black-litterman-priors-done-properly","q":"What is Black&ndash;Litterman actually doing?","a":"<p>Bayesian updating. The <b>prior</b> is the market-implied equilibrium return (reverse-optimised from market cap weights); your <b>views</b> are the likelihood, with your stated confidence as its precision.</p><p>The output is a posterior return vector that reduces to the market portfolio when you have no views — which is the property that makes it well-behaved, unlike raw Markowitz.</p>"},{"i":"11-4","v":"11","s":"11-4-hierarchical-risk-parity","q":"What does hierarchical risk parity avoid, and what does it give up?","a":"<p>It <b>avoids inverting the covariance matrix</b> entirely: cluster assets by correlation distance, then allocate recursively down the tree by inverse variance.</p><p>Gives up an explicit risk model and clean attribution. Wins out of sample mainly because it never touches the noisy small eigenvalues.</p>"},{"i":"11-5","v":"11","s":"11-5-the-alternatives-that-keep-winning","q":"Which simple allocators keep beating optimisation out of sample, and why?","a":"<p><b>Equal weight</b>, <b>inverse volatility</b>, <b>equal risk contribution</b>. They win because they use less estimated information: 1/N estimates nothing, inverse-vol estimates only variances (which are far better estimated than covariances).</p><p>The bar for a full optimiser is that it must beat these <em>after</em> costs and turnover, and it frequently does not.</p>"},{"i":"11-6","v":"11","s":"11-6-constraints-turnover-and-the-cost-of-rebalancin","q":"Why does turnover belong inside the optimisation rather than after it?","a":"<p>Because rebalancing to an unconstrained optimum and then trimming trades gives a portfolio that is neither optimal nor low-turnover.</p><p>Put a cost term in the objective: max &mu;&#8868;w &minus; &frac12;&gamma;w&#8868;&Sigma;w &minus; c&#8868;|w &minus; w<sub>0</sub>|. The solution is a <b>no-trade region</b> around the current holding — do nothing until the gain exceeds the cost.</p>"},{"i":"11A-1","v":"11A","s":"11a-1-the-marchenko-pastur-law","q":"Give the Marchenko&ndash;Pastur edges and the number they produce at n = 500, T = 1000.","a":"<p>&lambda;<sub>&plusmn;</sub> = &sigma;&sup2;(1 &plusmn; &radic;q)&sup2; with q = n/T.</p><p>At q = 0.5: &lambda;<sub>&minus;</sub> = 0.086, &lambda;<sub>+</sub> = 2.91. <b>Pure noise produces eigenvalues varying by a factor of 34</b>, every one of which will look like a nameable component.</p>"},{"i":"11A-2","v":"11A","s":"11a-1-the-marchenko-pastur-law","q":"How many days of daily data does a 3000-name universe need merely to have an invertible sample covariance?","a":"<p>More than 3000 — about <b>twelve years</b>. And the correlation structure twelve years ago is not today's.</p><p>This is why factor models exist: k factors need nk + n parameters instead of n(n+1)/2, which for n=3000, k=10 is 33,000 against 4.5 million.</p>"},{"i":"11A-3","v":"11A","s":"11a-2-cleaning-the-spectrum","q":"Describe the RMT cleaning recipe, including the step people get wrong.","a":"<ol><li>Correlation matrix of standardised returns</li><li>Compute &lambda;<sub>+</sub> for this (n, T)</li><li>Keep eigenvalues above the edge as estimated</li><li><b>Replace the bulk by its average, not by &lambda;<sub>+</sub></b> — this preserves the trace</li><li>Rescale the diagonal to exactly one</li></ol><p>Clipping to &lambda;<sub>+</sub> inflates total variance and makes every downstream risk number too big.</p>"},{"i":"11A-4","v":"11A","s":"11a-3-shrinkage-and-why-it-works","q":"How do you estimate the noise edge without assuming i.i.d. normal returns?","a":"<p><b>Permutation.</b> Shuffle each column's time index independently — this destroys cross-sectional dependence while preserving each series' own marginal, including fat tails and volatility clustering.</p><p>The resulting distribution of the largest eigenvalue <em>is</em> the null, measured rather than assumed. Take its 99th percentile.</p>"},{"i":"11A-5","v":"11A","s":"11a-4-how-many-factors-are-real","q":"What is the single out-of-sample test that overrules every other covariance diagnostic?","a":"<p>Build the minimum-variance portfolio from &Sigma;&#770; on the estimation window, hold it out of sample, and compare <b>realised volatility to predicted</b>. A good estimator lands within about 15%.</p><p>The raw sample covariance at q = 0.5 typically <b>under</b>-predicts by a factor of two or more. Run this before trusting any risk model, including a vendor's.</p>"},{"i":"12-1","v":"12","s":"12-1-var-and-its-two-serious-defects","q":"Name VaR's two serious defects.","a":"<ol><li>It says <b>nothing about the size of the loss beyond it</b> — two books with identical VaR can have wildly different tails</li><li>It is <b>not subadditive</b>: VaR of a combined book can exceed the sum of the parts, so it can penalise diversification and cannot be safely allocated across desks</li></ol><p>Expected shortfall (CVaR) fixes both and is the correct default.</p>"},{"i":"12-2","v":"12","s":"12-2-extreme-value-theory-for-the-part-that-matters","q":"What does extreme value theory model, and what is the practical parameter?","a":"<p>Only the <b>tail</b>: exceedances over a high threshold converge to a generalised Pareto distribution regardless of the underlying.</p><p>The shape parameter &xi; is the number that matters. &xi; &gt; 0 means a power-law tail; &xi; &ge; 0.5 means infinite variance. Daily equities typically show &xi; &asymp; 0.2&ndash;0.35.</p>"},{"i":"12-3","v":"12","s":"12-3-drawdown-the-risk-measure-that-actually-binds","q":"Why is drawdown the risk measure that actually binds?","a":"<p>Because it is the one that ends careers and mandates. Volatility is symmetric and a Sharpe ratio is a summary; a drawdown is a path, and the path is what you and your capital providers actually live through.</p><p>It is also badly estimated: maximum drawdown is a single order statistic with enormous sampling error, which is why the base-rate table matters more than the historical figure.</p>"},{"i":"12-4","v":"12","s":"12-4-kelly-and-why-you-should-not-use-full-kelly","q":"Give the Kelly fraction and the three reasons never to use full Kelly.","a":"<p>f* = &mu;/&sigma;&sup2; for a continuous bet.</p><ol><li><b>&mu; is estimated</b>, and far more noisily than &sigma; — full Kelly on an over-estimated &mu; is over-betting</li><li>The growth curve is <b>flat near the optimum and falls off a cliff past it</b>; double Kelly has growth rate zero</li><li>The drawdowns at full Kelly are unsurvivable in practice — expect drawdowns of the order of 50%</li></ol><p>Half Kelly keeps ~75% of the growth for half the volatility.</p>"},{"i":"12-5","v":"12","s":"12-5-stress-testing-that-is-not-theatre","q":"What separates a real stress test from theatre?","a":"<p>Theatre: shocking correlations entry by entry (usually destroying PSD), replaying 2008 on a book that did not exist then, or picking scenarios that the book happens to survive.</p><p>Real: stress the <b>dependence structure</b> coherently (12A.3), include funding and liquidity in the scenario, and define in advance what action a given result triggers. A stress test with no pre-committed response is a report, not a control.</p>"},{"i":"12-6","v":"12","s":"12-6-the-risk-limit-hierarchy","q":"Give the risk-limit hierarchy from most to least binding.","a":"<ol><li><b>Loss limits</b> — daily, monthly, and a hard stop at the mandate level</li><li><b>Drawdown-linked de-risking</b> — automatic, in code, in advance</li><li><b>Concentration limits</b> — per name, per sector, per factor</li><li><b>Gross and net exposure</b></li><li><b>Volatility target</b> — the softest, and the one that does most of the work day to day</li></ol><p>Each should live where you cannot edit it while emotional.</p>"},{"i":"12A-1","v":"12A","s":"12a-1-sklar-s-theorem","q":"State Sklar's theorem and give two reasons the decomposition is the right one.","a":"<p>F(x<sub>1</sub>,&hellip;,x<sub>n</sub>) = C(F<sub>1</sub>(x<sub>1</sub>),&hellip;,F<sub>n</sub>(x<sub>n</sub>)), with C unique for continuous marginals.</p><p>(1) The copula is <b>invariant to monotone transformation</b> — correlation is not, which is why correlations on prices, returns and log returns differ. (2) It lets you <b>stress dependence while holding marginals fixed</b>, which is what 'correlations go to one in a crisis' actually means.</p>"},{"i":"12A-2","v":"12A","s":"12a-2-tail-dependence-the-coefficient-that-matters","q":"What is the tail dependence of a Gaussian copula, and why is that a problem?","a":"<p><b>Exactly zero</b>, for any correlation below 1. Two assets correlated at 0.95 become asymptotically independent in the extreme tail.</p><p>That is not an approximation that degrades gracefully — it is qualitatively false. A t-copula with &rho;=0.5, &nu;=4 gives &lambda; &asymp; 0.25: a one-in-four chance the other asset also has an extreme loss.</p>"},{"i":"12A-3","v":"12A","s":"12a-3-simulating-from-a-copula-and-stressing-it","q":"Why must a correlation stress be applied to the whole matrix rather than entry by entry?","a":"<p>Shocking entries individually usually destroys <b>positive semi-definiteness</b>. The optimiser then finds the impossible direction and puts the whole book in it — a stress test that produces a fictional portfolio.</p><p>Scale all off-diagonals together, then project back onto the PSD cone and rescale the diagonal.</p>"},{"i":"12A-4","v":"12A","s":"12a-4-when-not-to-use-a-copula","q":"Name the three limitations of copulas.","a":"<ol><li><b>Static</b> — a fitted copula is unconditional; real dependence rises in stress</li><li><b>Scale badly</b> — beyond 5&ndash;6 dimensions only elliptical copulas are tractable, and they impose one structure on every pair</li><li><b>The tail estimate is intrinsically noisy</b> — it is a statement about the region where you have twenty observations</li></ol>"},{"i":"13-1","v":"13","s":"13-1-time-series-momentum","q":"Why does time-series momentum work, and what is the honest caveat?","a":"<p>Two stories: <b>under-reaction</b> to slow information, and <b>risk transfer</b> — trend followers are paid to take the other side of hedgers. Both have support.</p><p>The caveat: nearly all of the measured performance of a trend book comes from the <b>volatility targeting</b>, not from the signal. Test the signal against a vol-targeted random-sign benchmark before believing it.</p>"},{"i":"13-2","v":"13","s":"13-2-volatility-targeting-the-mechanism-that-does-mo","q":"Why does volatility targeting do most of the work in a trend book?","a":"<p>It equalises risk contribution across instruments and through time, which (a) stops one volatile market dominating, (b) mechanically reduces exposure into turbulent periods, and (c) improves the geometric return by cutting volatility drag.</p><p>It is also the component with the least estimation risk — variance is far better estimated than mean.</p>"},{"i":"13-3","v":"13","s":"13-3-why-trend-following-works-and-when-it-does-not","q":"When does trend following stop working?","a":"<p>In <b>sharp reversals</b> and in choppy range-bound regimes. The payoff is structurally similar to a long straddle: many small losses, occasional large gains, and the small losses cluster when nothing is trending.</p><p>Expect long flat stretches. A three-year drawdown is within the historical distribution, and that fact is worth knowing in advance rather than discovering.</p>"},{"i":"13-4","v":"13","s":"13-4-carry","q":"Define carry generically and give its sign in four markets.","a":"<p>Carry is the return earned if the price does not move: (F &minus; S)/S per unit time.</p><ul><li><b>Equity index</b> — usually negative (financing above dividends)</li><li><b>Bond future</b> — positive when the curve slopes up</li><li><b>FX forward</b> — the interest differential, either sign</li><li><b>Commodity</b> — positive in backwardation, negative in contango</li></ul>"},{"i":"13-5","v":"13","s":"13-5-building-a-diversified-managed-futures-book","q":"What actually diversifies a managed-futures book?","a":"<p><b>Sector and horizon</b>, not instrument count. Twenty equity index futures are one bet. Equities, rates, FX and commodities across fast, medium and slow lookbacks is several.</p><p>And measure it: the effective number of bets is (&Sigma;&lambda;<sub>i</sub>)&sup2;/&Sigma;&lambda;<sub>i</sub>&sup2; on the risk-contribution spectrum, which is usually far smaller than the number of instruments.</p>"},{"i":"13A-1","v":"13A","s":"13a-1-the-yield-curve-and-the-three-numbers-that-d","q":"What are the three Nelson&ndash;Siegel factors, and what are their PCA counterparts?","a":"<ul><li><b>&beta;<sub>0</sub> level</b> — PC1, ~85&ndash;90% of variance</li><li><b>&beta;<sub>1</sub> slope</b> — PC2, ~5&ndash;10%</li><li><b>&beta;<sub>2</sub> curvature</b> — PC3, ~1&ndash;3%</li></ul><p>Use PCA to understand the risk, Nelson&ndash;Siegel to build the curve: its parameters are stable and comparable across dates where PCA eigenvectors rotate and flip sign.</p>"},{"i":"13A-2","v":"13A","s":"13a-2-duration-convexity-and-dv01","q":"Why is DV01 the right unit for a rates book rather than duration?","a":"<p>Duration is a <b>percentage</b> and does not add across instruments with different notionals. DV01 is a currency amount per basis point and <b>does add</b>.</p><p>Long &pound;40k DV01 gilts against short &pound;40k DV01 Bunds is duration-neutral in the only sense that matters. For a bond future, use the DV01 of the cheapest-to-deliver divided by its conversion factor.</p>"},{"i":"13A-3","v":"13A","s":"13a-2-duration-convexity-and-dv01","q":"Is convexity a correction term or a return?","a":"<p>A <b>return</b>. Positive convexity means you gain more from a yield fall than you lose from an equal rise, worth roughly &frac12;C&sigma;<sub>y</sub>&sup2; per unit time.</p><p>The market prices it, which is why long-dated bonds yield less than a pure expectations model predicts, and why a duration-matched barbell is not equivalent to a bullet — the difference is a volatility position.</p>"},{"i":"13A-4","v":"13A","s":"13a-3-futures-swaps-and-the-carry-decomposition","q":"Why is FX carry different in kind from every other carry?","a":"<p>Covered interest parity is an <b>arbitrage relation</b>: the forward <em>is</em> the interest differential, by construction. So FX carry is not a forecast.</p><p>The trade earns money because <b>uncovered</b> parity fails — spot does not on average move to offset the differential. That is a genuine anomaly with a characteristic payoff: small positive returns punctuated by sharp reversals when funding tightens. Close to short volatility in disguise.</p>"},{"i":"13A-5","v":"13A","s":"13a-4-credit-default-risk-and-spread-risk-are-diff","q":"In an investment-grade credit spread, roughly how much is expected loss?","a":"<p>Only about <b>a fifth to a third</b>. The rest is compensation for illiquidity, the systematic timing of defaults, and spread volatility — the 'credit spread puzzle'.</p><p>So a strategy premised on realised defaults being lower than the spread implies is usually right and occasionally catastrophically wrong.</p>"},{"i":"13A-6","v":"13A","s":"13a-5-what-a-cross-asset-book-actually-needs","q":"What does back-adjusting a futures series wrong look like in a backtest?","a":"<p><b>Performance concentrated on roll dates.</b></p><p>Difference-adjusted series can go negative over long histories, making percentage returns meaningless; ratio-adjusted distort price levels, making level-conditioning meaningless. Build both — ratio for returns, difference for spread and level logic — and keep the raw contracts.</p>"},{"i":"14-1","v":"14","s":"14-1-the-constant-product-amm","q":"Give the constant-product AMM invariant and what it implies about price.","a":"<p>x &middot; y = k. The marginal price is y/x, and a trade of &Delta;x moves it along the curve.</p><p>Slippage is deterministic and computable in advance, which is the one genuine advantage of an AMM over an order book: you know your fill exactly before you send.</p>"},{"i":"14-2","v":"14","s":"14-2-impermanent-loss-is-a-short-volatility-position","q":"Why is impermanent loss a short-volatility position?","a":"<p>An LP is short a straddle: the value of the position relative to holding falls as the price moves in <em>either</em> direction, and the loss grows with realised variance.</p><p>Fees are the premium. Providing liquidity is profitable exactly when fee income exceeds realised variance — the same trade as selling options, with the same failure mode.</p>"},{"i":"14-3","v":"14","s":"14-3-perpetual-futures-and-the-funding-rate","q":"What does the perpetual funding rate do, and what is the carry trade?","a":"<p>It tethers the perpetual to spot: when the perp trades above spot, longs pay shorts.</p><p>The basis trade is long spot, short perp, collecting funding. Its risks are <b>liquidation</b> on the short leg during a squeeze and <b>exchange/custody</b> risk, both of which are the real position — the funding is not free money, it is compensation for those.</p>"},{"i":"14-4","v":"14","s":"14-4-mev-the-mechanics","q":"Where do the structural edges in crypto actually sit?","a":"<p>In the <b>plumbing</b>, not in prediction: cross-venue basis and funding, liquidation cascades, and the mechanics of settlement and custody.</p><p>Directional crypto alpha is as hard as anywhere else and the data is worse. The edges that persist are compensation for operational and counterparty risk that most participants cannot or will not take.</p>"},{"i":"15-1","v":"15","s":"15-1-point-in-time-the-discipline","q":"What does 'point in time' mean, and what is the standard failure?","a":"<p>Every value must be joined on the date it <b>became public</b>, not the period it describes.</p><p>The standard failure is using a restated fundamental: a company's 2015 earnings as reported today are not what was known in 2015. Backtests using restated data show an edge that was never available.</p>"},{"i":"15-2","v":"15","s":"15-2-survivorship-and-the-biases-that-inflate-every-","q":"Name the biases that inflate every naive backtest.","a":"<ul><li><b>Survivorship</b> — today's index members, backfilled</li><li><b>Look-ahead</b> — information used before it existed</li><li><b>Backfill / instant history</b> — a database adds a fund's good early years retrospectively</li><li><b>Delisting</b> — bankrupt names simply disappear instead of returning &minus;100%</li></ul><p>Delisting bias alone can add several percent a year to a small-cap backtest.</p>"},{"i":"15-3","v":"15","s":"15-4-alternative-data-what-to-ask-before-paying-for-","q":"What should you ask before paying for an alternative dataset?","a":"<ol><li><b>Is it point-in-time</b>, with a documented as-of timestamp?</li><li><b>How many others have it</b>, and for how long?</li><li><b>What is the history</b>, and was it collected live or reconstructed?</li><li><b>What is the entity mapping</b>, and who maintains it?</li><li><b>Can you get a sample</b> to test the join before committing?</li></ol><p>Most alt-data value is competed away within 2&ndash;3 years of broad availability.</p>"},{"i":"15-4","v":"15","s":"15-3-entity-resolution-and-corporate-actions","q":"Why is entity resolution harder than it looks?","a":"<p>Tickers are reused, companies merge and spin off, identifiers change on corporate actions, and the same legal entity has different identifiers in every vendor's system.</p><p>A mis-mapped entity produces a series that silently splices two different companies — which looks like a large, tradeable return.</p>"},{"i":"16-1","v":"16","s":"16-1-the-architecture","q":"What is the architecture of an event-driven backtester, and why that shape?","a":"<p>A single time-ordered <b>event queue</b> — market data, signal, order, fill — processed one event at a time, with the strategy able to see only what has already been dequeued.</p><p>That shape makes lookahead <b>structurally impossible</b> rather than something you have to remember to avoid. The vectorised version is faster; the event-driven version is correct by construction.</p>"},{"i":"16-2","v":"16","s":"16-2-the-fill-model-is-the-backtest","q":"Why is the fill model the backtest?","a":"<p>Because for any strategy with meaningful turnover, the difference between optimistic and realistic fills exceeds the entire alpha.</p><p>Minimum honest model: market orders cross the spread and pay impact; limit orders fill only if the price <b>trades through</b> your level, not merely touches it; and partial fills are the norm.</p>"},{"i":"16-3","v":"16","s":"16-3-correctness-checks-that-catch-real-bugs","q":"List the six correctness checks every backtester must pass.","a":"<ol><li>Zero signal &rarr; zero P&amp;L</li><li>Constant long signal &rarr; buy-and-hold, to within costs</li><li>Doubling gross &rarr; doubles pre-cost P&amp;L</li><li>Shifting the signal forward one bar &rarr; <b>degrades</b> performance</li><li>Reversing the signal &rarr; negates pre-cost P&amp;L</li><li>No order ever executes outside the bar it was placed in</li></ol><p>Passing does not make it right; failing any one makes it definitely wrong.</p>"},{"i":"16-4","v":"16","s":"16-4-making-it-fast-enough-to-be-usable","q":"What is the acceptable way to make a backtester fast?","a":"<p>Keep the event-driven version as the <b>reference implementation</b>, write a vectorised version for research speed, and assert they agree to floating-point tolerance on a fixed fixture.</p><p>Optimising the event-driven engine directly is where subtle lookahead gets introduced, because the optimisations are exactly the ones that peek ahead.</p>"},{"i":"17-1","v":"17","s":"17-2-fix-in-the-amount-of-detail-you-need","q":"What is the minimum you need to know about FIX?","a":"<p>It is a tag=value session protocol with sequence numbers. The parts that matter: <b>sequence number gaps</b> mean a message was lost and you must resend; <b>ClOrdID</b> uniquely identifies your order and must be idempotent; and <b>ExecType/OrdStatus</b> together tell you the real state, not either alone.</p>"},{"i":"17-2","v":"17","s":"17-3-idempotency-and-exactly-once-semantics","q":"Why does idempotency matter in an order gateway?","a":"<p>Because networks retry. Without idempotent client order IDs, a retried 'send order' becomes <b>two orders</b>, and the first you learn of it is a double position.</p><p>Every mutating operation must be safe to repeat: generate the ID before the first attempt, never inside the retry loop.</p>"},{"i":"17-3","v":"17","s":"17-4-reconciliation","q":"What does reconciliation compare, and how often?","a":"<p>Your believed positions, cash and orders against the <b>broker's record</b>, at least daily and ideally continuously.</p><p>A discrepancy is treated as an incident, not a rounding difference. Most catastrophic failures start as a small unexplained break that nobody chased.</p>"},{"i":"17-4","v":"17","s":"17-6-monitoring-what-to-alert-on","q":"What should you alert on, and what should you never alert on?","a":"<p><b>Alert</b>: the system did not run, reconciliation broke, slippage outside its band, data staleness, an order rejected, risk limit approached.</p><p><b>Never alert on P&amp;L.</b> It generates alarms you cannot act on, trains you to ignore alerts, and turns a monitoring system into an anxiety machine.</p>"},{"i":"18-1","v":"18","s":"18-1-the-arithmetic-of-selection-bias","q":"State the arithmetic of selection bias.","a":"<p>With n independent strategies of zero true edge, the expected <b>maximum</b> Sharpe is roughly &radic;(2 ln n) in per-period standard-error units.</p><p>At n = 100 that is about 3.0. So a t-statistic of 3 from a search over 100 variants is exactly what pure noise produces, and means nothing.</p>"},{"i":"18-2","v":"18","s":"18-2-the-deflated-sharpe-ratio","q":"What does the deflated Sharpe ratio deflate by, and what input do people fake?","a":"<p>By the <b>expected maximum Sharpe under the null</b> across the number of trials, adjusted for the track record's own skew and kurtosis.</p><p>The faked input is the <b>trial count</b>. Not dishonestly — the failed quick checks genuinely do not feel like trials. Which is why the counter has to be automatic.</p>"},{"i":"18-3","v":"18","s":"18-3-the-probability-of-backtest-overfitting","q":"What does the probability of backtest overfitting measure?","a":"<p>Via combinatorially symmetric cross-validation: across many train/test splits, how often the configuration that was best in-sample is <b>below median</b> out of sample.</p><p>A PBO above ~50% means your selection procedure is anti-predictive — you would do better picking at random.</p>"},{"i":"18-4","v":"18","s":"18-5-a-research-protocol-that-resists-self-deception","q":"Give the research protocol that resists self-deception.","a":"<ol><li><b>Pre-register</b> the hypothesis, the number of configurations and the threshold, in version control with a timestamp</li><li><b>Count trials automatically</b></li><li>Keep a holdout you <b>cannot casually open</b> — encrypt it</li><li><b>Time-box</b> the cycle; exceeding the trial count ends it and the result is discarded, not deflated</li><li>Deploy, shelve or abandon at the end. Shelving is legitimate; continuing indefinitely is not</li></ol>"},{"i":"19-1","v":"19","s":"19-2-the-interview-process-stage-by-stage","q":"What does a quant interview actually test, stage by stage?","a":"<p>Early stages test <b>mechanics</b> — probability, mental maths, coding under observation. Later stages test <b>judgement</b>: can you say what you would check, what would change your mind, and where your own result might be wrong.</p><p>The second is where most technically strong candidates fail, and it is practised by talking through problems out loud with an audience, not by solving more of them alone.</p>"},{"i":"19-2","v":"19","s":"19-4-the-honest-picture-for-an-independent-trader","q":"What is the honest picture for an independent trader?","a":"<p>You cannot compete on latency, data spend or headcount. You <b>can</b> compete in the region below roughly $50m of capacity, where a large fund's overhead makes deployment not worth it.</p><p>That region is genuinely uncontested by the best-capitalised participants. It is the structural reason independent systematic trading is possible at all.</p>"},{"i":"19-3","v":"19","s":"19-5-building-evidence-that-someone-else-can-verify","q":"What counts as evidence someone else can verify?","a":"<p>A tagged commit with the environment lockfile, the trial count, the deflated Sharpe, the cost model and the out-of-sample window — such that a stranger can re-run it and get your number.</p><p>An equity curve is not evidence. A screenshot is not evidence. The distinction matters for interviews and for your own future self equally.</p>"},{"i":"19A-1","v":"19A","s":"19a-1-where-the-money-is-held","q":"What does portfolio margin change, and why is that the threshold that matters?","a":"<p>Reg T charges 50% on each position independently, so a hedged book is charged as if the hedge did not exist. Portfolio margin charges the <b>stressed loss of the portfolio</b>.</p><p>For a market-neutral book that is often the difference between 2:1 and 6:1 on the same risk — which is the difference between an uninvestable Sharpe-0.8 strategy and an interesting one.</p>"},{"i":"19A-2","v":"19A","s":"19a-1-where-the-money-is-held","q":"Name the counterweight to portfolio margin that people forget.","a":"<p>It <b>recalculates daily on stressed scenarios</b>, so your requirement rises exactly when your equity falls. Margin calls arrive at the worst possible moment by construction.</p><p>And more available leverage is not a reason to use it — the fractional-Kelly argument applies with more force when the broker will let you exceed the optimum.</p>"},{"i":"19A-3","v":"19A","s":"19a-2-financing-borrow-and-the-costs-nobody-backte","q":"Why does the short leg break naive backtests, in two ways?","a":"<ol><li>The names a short signal selects — small, volatile, heavily shorted — are exactly the <b>hard-to-borrow</b> ones. A flat 40 bp assumption against a real 6% weighted borrow removes most of the return</li><li><b>Recall</b>: the lender can demand shares back, forcing a buy-in during a squeeze with no discretion over timing. Not modelled in any standard backtester</li></ol>"},{"i":"19A-4","v":"19A","s":"19a-2-financing-borrow-and-the-costs-nobody-backte","q":"Why decompose costs rather than using one net figure?","a":"<p>Because they respond to <b>different fixes</b>: turnover costs fall by trading less, financing falls by using less leverage, borrow falls by changing the short universe.</p><p>A single net number tells you the strategy is expensive but not what to do about it.</p>"},{"i":"19A-5","v":"19A","s":"19a-3-capacity","q":"How do capacity and Sharpe trade off, and what does that mean for you?","a":"<p>Almost mechanically inversely. High-Sharpe strategies are high-turnover and small-capacity; large-capacity strategies are slow with Sharpe below 1. There is no Sharpe-3, billion-dollar strategy — it would have been arbitraged to one extreme.</p><p>For an individual, <b>the capacity constraint is the competitive advantage</b>: strategies capping at $20m are not worth a $2bn fund's operational overhead.</p>"},{"i":"19A-6","v":"19A","s":"19a-4-regulation-in-the-shape-that-affects-you","q":"Which regulatory issue most often surprises systematic traders?","a":"<p><b>Order-to-trade ratios and cancellation behaviour are surveilled.</b> An opportunistic-limit strategy that posts and cancels aggressively can trip exchange thresholds and, in a bad case, resemble layering — prosecuted on the pattern, not on proven intent.</p><p>Defences: monitor your own order-to-trade ratio, and keep strategy logic and rationale in timestamped version control.</p>"},{"i":"19A-7","v":"19A","s":"19a-5-tax-and-the-compounding-it-destroys","q":"Describe the twenty-minute calculation that ends bad projects.","a":"<p>Take gross return, subtract full costs, then apply the tax treatment that will actually apply, <b>compounding annually on the after-tax figure</b> — not deducting once at the end. Compare against a passive benchmark under the same treatment.</p><p>Common result: gross Sharpe 1.0 with 400% turnover and short-term tax treatment nets out <b>below a buy-and-hold index fund</b>. Do this before building anything.</p>"},{"i":"19A-8","v":"19A","s":"19a-5-tax-and-the-compounding-it-destroys","q":"Give two ways tax should change strategy design, not just reporting.","a":"<ol><li>Use <b>tax-advantaged capacity first</b> for your highest-turnover strategy, where the deferral is worth most</li><li>Prefer a <b>lower-frequency expression</b> of the same signal: monthly rather than weekly with 60% of the gross alpha may well net more</li></ol><p>Almost nobody optimises for this, which makes it one of the few uncrowded improvements available.</p>"},{"i":"20-1","v":"20","s":"20-1-quadratic-variation-of-brownian-motion-equals-t","q":"Prove that the quadratic variation of Brownian motion equals T. What is the key step?","a":"<p>Take the partition sum &Sigma;(W<sub>t<sub>i+1</sub></sub> &minus; W<sub>t<sub>i</sub></sub>)&sup2;. Its expectation is &Sigma;&Delta;t<sub>i</sub> = T exactly. Its <b>variance</b> is 2&Sigma;(&Delta;t<sub>i</sub>)&sup2; &le; 2&#8214;&Pi;&#8214;T &rarr; 0.</p><p>So the sum converges in L&sup2; to the constant T. The key step is that the variance vanishes as the mesh does.</p>"},{"i":"20-2","v":"20","s":"20-2-it-isometry","q":"State the Itô isometry and what it says about a strategy.","a":"<p>E[(&int;<sub>0</sub><sup>T</sup>&theta;<sub>t</sub>dW<sub>t</sub>)&sup2;] = E[&int;<sub>0</sub><sup>T</sup>&theta;<sub>t</sub>&sup2;dt].</p><p>The variance of your P&amp;L is the expected time-integral of squared position-times-volatility. Every volatility-targeting rule is a discrete attempt to hold that integrand constant.</p>"},{"i":"20-3","v":"20","s":"20-9-the-kelly-criterion","q":"Derive the Kelly criterion in one line for a continuous bet.","a":"<p>Maximise E[log wealth]: g(f) = f&mu; &minus; &frac12;f&sup2;&sigma;&sup2;. Differentiate: &mu; &minus; f&sigma;&sup2; = 0, so <b>f* = &mu;/&sigma;&sup2;</b>.</p><p>Note g is a downward parabola with roots at 0 and 2f*: <b>double Kelly has zero growth rate.</b></p>"},{"i":"20-4","v":"20","s":"20-11-the-fundamental-law-of-active-management","q":"State the Fundamental Law of Active Management and where it comes from.","a":"<p>IR = IC &times; &radic;BR &times; TC.</p><p>It falls out of the fact that combining BR independent forecasts each with correlation IC to the outcome gives an aggregate signal-to-noise scaling as &radic;BR. The transfer coefficient TC is what constraints do to it — typically 0.3&ndash;0.6 in practice.</p>"},{"i":"20-5","v":"20","s":"20-13-var-is-not-subadditive","q":"Give a concrete example of VaR failing subadditivity.","a":"<p>Two independent bonds, each defaulting with probability 4%, each losing 100. At the 95% level each has VaR 0 (default is in the 4% tail). Combined, the probability of at least one default is 7.8% &gt; 5%, so the portfolio VaR is <b>100</b>.</p><p>0 + 0 &lt; 100: diversifying <em>increased</em> measured risk. This is why VaR cannot be safely allocated across desks and why ES is the correct default.</p>"},{"i":"20-6","v":"20","s":"20-14-the-almgren-chriss-trajectory","q":"What shape is the Almgren&ndash;Chriss optimal trajectory and what sets it?","a":"<p>Exponential decay of remaining inventory, with rate &kappa; = &radic;(&lambda;&sigma;&sup2;/&eta;).</p><p>High risk aversion or volatility &rarr; front-loaded. Low &rarr; the limit is linear (TWAP). Alpha decay (10.3) front-loads it further and is usually the dominant term for a fast signal.</p>"},{"i":"21-1","v":"21","s":"21-1-research-harness-with-automatic-trial-counting","q":"What must a research harness do that a script does not?","a":"<p><b>Count trials automatically</b> and record each one with its config and git sha. The count is the input the deflated Sharpe ratio needs, and a count maintained by hand will always be under-reported.</p>"},{"i":"21-2","v":"21","s":"21-9-live-risk-monitor-and-kill-switch","q":"What should a kill switch require to re-enable, and why?","a":"<p>An <b>explicit reset with a written justification</b>, not a restart.</p><p>The friction is the feature: a kill switch you can clear with one keystroke while emotional is not a control, it is a pause button. Requiring writing forces the reasoning into a form you can re-read the next day.</p>"},{"i":"21-3","v":"21","s":"21-11-rust-rolling-window-statistics-kernel","q":"When is it worth dropping to Rust or C++ in a research stack?","a":"<p>Only for a genuinely path-dependent inner loop that cannot be vectorised — a fill model, a queue simulator, a rolling statistic with state.</p><p>Everything else should be NumPy or Polars. Rewriting vectorisable code in a systems language buys a small constant factor at a large maintenance cost.</p>"},{"i":"22-1","v":"22","s":"22-1-the-operator-and-data-language","q":"What is the operator language of the 101 alphas actually doing?","a":"<p>Almost all of them compose a handful of primitives: <code>rank</code> (cross-sectional), <code>delta</code>/<code>delay</code> (time), <code>ts_*</code> (rolling), <code>correlation</code>, and <code>scale</code>.</p><p>Reading them as combinations of those five, rather than as 101 separate ideas, is what makes the catalogue learnable.</p>"},{"i":"22-2","v":"22","s":"22-4-structure-of-the-catalogue","q":"What is the honest expected performance of a published formulaic alpha today?","a":"<p>Close to zero net of costs, individually. They were published in 2016 and were not new then.</p><p>Their value is as a <b>feature library</b> and as a worked demonstration of the operator language — not as strategies. Anyone selling them as strategies is selling a 2016 paper.</p>"},{"i":"23-1","v":"23","s":"23-1-how-to-use-this-bank","q":"How should you work a problem bank, and how should you not?","a":"<p><b>Not</b> in order to completion. Sample across categories, return to the ones you got wrong, and stop when you can reliably <em>narrate</em> a solution rather than when the list is finished.</p><p>An unfinished list is uncomfortable; an unpractised delivery is expensive.</p>"},{"i":"23-2","v":"23","s":"23-2-the-bank","q":"Why practise interview problems out loud rather than on paper?","a":"<p>Because the format is the constraint, not the content. Being watched, interrupted and wrong in real time is a different task from solving the same problem alone, and it is the one being assessed.</p><p>Familiarity is the entire fix and it only comes from repetition with an audience.</p>"},{"i":"24-1","v":"24","s":"24-2-the-honest-summary","q":"Name the four-facet combination that Volume 24 says matters more than everything else, and what it produces.","a":"<p><b>Orderliness 16 + Self-Efficacy 11 + Immoderation 15 + Vulnerability 13.</b></p><p>You will build a genuinely good system, doubt it precisely when it is working through a normal drawdown, and have difficulty resisting the urge to intervene in the moment.</p><p>One-sentence fix: <b>move every consequential decision out of the moment and into code you wrote while calm.</b></p>"},{"i":"24-2","v":"24","s":"24-2-the-honest-summary","q":"List the five things in your profile that work in your favour for systematic trading.","a":"<ol><li><b>Orderliness 16</b> — the single most useful trait in the discipline; the data hygiene that separates real research from plausible research</li><li><b>Intellect 16 + Imagination 16</b> — genuine capacity for original research</li><li><b>Low Gregariousness 8 / Friendliness 9</b> — in this field close to a requirement, not a cost</li><li><b>Assertiveness 13 with Modesty 10</b> — you can defend your work when challenged</li><li><b>Excitement-Seeking 12 / Activity Level 9</b> — slow strategies will not feel like deprivation</li></ol>"},{"i":"24-3","v":"24","s":"24-3-four-failure-modes-and-the-control-for-each","q":"Failure mode 1: overriding the system in a drawdown. What drives it and what are the four controls?","a":"<p><b>Driven by</b> Self-Efficacy 11, Vulnerability 13, Anxiety 16.</p><ol><li>Automatic de-risking ladder, <b>in code, in advance</b></li><li>Read 12.3 before you need it — a Sharpe-1 strategy has a 16% chance of a losing year</li><li>A written stopping rule as a hypothesis test with a stated false-alarm rate</li><li><b>A 24-hour delay on any manual override</b> — write the reason, wait a day, re-read it</li></ol>"},{"i":"24-4","v":"24","s":"24-3-four-failure-modes-and-the-control-for-each","q":"Failure mode 2: adding to a losing position. What drives it and what is the control that actually works?","a":"<p><b>Driven by</b> Immoderation 15, interacting with the fact that many models genuinely say a wider spread is a better entry.</p><p>The control that works: <b>maximum position fixed at entry, enforced at the broker or gateway</b> — not in your own script, which you can edit in thirty seconds. A limit you can change while emotional is a suggestion.</p>"},{"i":"24-5","v":"24","s":"24-3-four-failure-modes-and-the-control-for-each","q":"Failure mode 3: research that never converges. Why does it feel like diligence?","a":"<p>Imagination 16 and Intellect 16 generate hypotheses faster than any honest validation budget absorbs, and Orderliness 16 makes it <em>pleasant</em> to test all of them thoroughly.</p><p><b>Careful execution of an overfitting procedure is still overfitting</b>, and it feels like rigour the entire time. Control: pre-register, count trials automatically, encrypt the holdout, time-box to four weeks with a deploy/shelve/abandon decision.</p>"},{"i":"24-6","v":"24","s":"24-3-four-failure-modes-and-the-control-for-each","q":"Failure mode 4: infrastructure as procrastination. What is the psychological mechanism?","a":"<p>Orderliness 16 plus Self-Efficacy 11. Building a backtester has a <b>definite right answer and immediate verifiable feedback</b>; running a strategy does not. When the uncertain thing feels threatening, the certain thing becomes very attractive.</p><p>Control: a written completion criterion set <em>before</em> you start, because afterwards every individual improvement will sound defensible.</p>"},{"i":"24-7","v":"24","s":"24-4-the-drawdown-protocol","q":"Recite the drawdown ladder: what happens at each level?","a":"<ul><li><b>0 to &minus;5%</b> — nothing. Do not look more often than usual</li><li><b>&minus;5 to &minus;8%</b> — log it. Change nothing</li><li><b>&minus;8%</b> — system automatically halves size. Verify it executed; do not investigate yet</li><li><b>&minus;8 to &minus;15%</b> — run the diagnostic checklist <b>once, in writing</b></li><li><b>&minus;15%</b> — automatic flatten and halt. Three days away from the screen</li><li><b>Re-enable</b> — written justification, diagnostics complete, 48 hours elapsed</li></ul>"},{"i":"24-8","v":"24","s":"24-4-the-drawdown-protocol","q":"Give the drawdown diagnostic checklist in order.","a":"<ol><li>Is realised <b>slippage</b> in line with the model? (Most 'broken' strategies are cost problems)</li><li>Is the signal's <b>information coefficient</b> still in its historical range? IC decays visibly long before P&amp;L does</li><li>Have <b>factor exposures</b> drifted from what you tested?</li><li>Is the drawdown inside the <b>1st-percentile band</b> of the bootstrap?</li><li>Has anything changed <b>operationally</b> — data, broker, universe, a deployment?</li></ol><p>If 1&ndash;5 pass, the strategy is behaving as designed. That is the most common outcome and the hardest to accept.</p>"},{"i":"24-9","v":"24","s":"24-5-reporting-discipline","q":"Why is monthly reporting a risk control for you specifically, not just a preference?","a":"<p>Daily P&amp;L on a Sharpe-1 strategy is negative <b>46% of days</b>. Watching a number that disappoints you nearly every other day, with Depression 14 and Self-Consciousness 14, imposes a real cost and produces <b>no information</b>.</p><p>Report at portfolio level, track process metrics weekly instead, keep a <b>decision</b> journal rather than a results journal, and automate the reports so checking is a scheduled event rather than an available compulsion.</p>"},{"i":"24-10","v":"24","s":"24-6-cognitive-biases-weighted-for-you","q":"Which cognitive biases are you most exposed to, and by which facet?","a":"<ul><li><b>Disposition effect</b> — high. Immoderation 15 pushes toward realising gains; Vulnerability 13 makes holding a loser intolerable until it is too large to face</li><li><b>Loss aversion</b> — high, elevated across every Neuroticism facet</li><li><b>Confirmation bias</b> — high in research. Imagination 16 generates a hypothesis you become attached to</li><li><b>Outcome bias</b> — high. Low Self-Efficacy reads a bad outcome as evidence about you</li></ul>"},{"i":"25-1","v":"25","s":"25-6-weekly-rhythm","q":"What is the prescribed weekly rhythm, and what is the single most important rule in it?","a":"<p>Five sessions, ninety minutes each, morning if possible, one item per session. Friday: a thirty-minute written review.</p><p>The load-bearing rule: <b>stop on the timer, not on the task.</b> Finishing the task means the hardest sessions become the longest, which is exactly backwards for a Burnout Buffer of 44 — and stopping mid-problem leaves a clear re-entry point.</p>"},{"i":"25-2","v":"25","s":"25-7-the-honest-expectation","q":"What is the honest expectation for the twelve months?","a":"<p>Not a profitable strategy — that is not a twelve-month outcome for anyone honest. The realistic deliverable is: a correct data layer, a verified backtester, one strategy running live at trivial size, a trial registry with real numbers in it, and the judgement to read your own results properly.</p><p>Anyone promising more in twelve months is selling something.</p>"},{"i":"25-3","v":"25","s":"25-2-quarter-2-a-first-strategy-end-to-end","q":"Why does the curriculum insist on going live in Quarter 2 at trivial size?","a":"<p>Because failure mode 4 (infrastructure as procrastination) is the second most likely way the project dies, and the only reliable antidote is <b>shipping something small and live early</b>.</p><p>A tiny live position teaches you more about your actual pipeline than three more months of building — and it converts an uncertain, threatening activity into a familiar one before the stakes are real.</p>"},{"i":"25A-1","v":"25A","s":"25a-1-the-profile-read-as-a-system-rather-than-a-l","q":"Name the four structural combinations in your profile, none of which is visible from a single facet.","a":"<ol><li><b>The build&ndash;doubt loop</b> — Orderliness 16 + Self-Efficacy 11 + Vulnerability 13</li><li><b>Amplitude, not just downside</b> — Neuroticism 86 <em>and</em> Cheerfulness 15</li><li><b>Public conviction, private doubt</b> — Assertiveness 13 + Modesty 10 + Self-Efficacy 11</li><li><b>Novelty appetite, ambiguity aversion</b> — Imagination 16 + Intellect 16 + Liberalism 9</li></ol>"},{"i":"25A-2","v":"25A","s":"25a-1-the-profile-read-as-a-system-rather-than-a-l","q":"What are the three consequences of low Morality (candour, 8th percentile) in systematic trading, and the single control?","a":"<ol><li><b>Under-reporting losses to yourself</b> — not falsifying, deferring. The month you do not open the report</li><li><b>Not seeking help</b> — solving alone what a thirty-minute conversation would resolve</li><li><b>Selective disclosure to people with a stake</b> — true statements that omit the worrying part</li></ol><p>One control for all three: <b>make disclosure automatic and scheduled</b>, so no individual decision to disclose is ever required. It is a cron job, not a discipline.</p>"},{"i":"25A-3","v":"25A","s":"25a-2-the-daily-protocol","q":"Recite the daily protocol.","a":"<ul><li><b>Start</b> (3 min) — confirm the system ran: fills reconciled, no errors, no stale data</li><li><b>Start</b> (1 min) — one line naming today's single work item</li><li><b>During</b> (90 min) — research block, timer set, one item</li><li><b>During</b> — log any urge to intervene, with time and trigger. Do not act</li><li><b>End</b> (2 min) — one line: what you did, what is next. Close everything</li><li><b>Never</b> — look at P&amp;L</li></ul>"},{"i":"25A-4","v":"25A","s":"25a-2-the-daily-protocol","q":"Give the argument for why the no-P&amp;L rule has to be absolute rather than a default.","a":"<p>A rule with an exception is a rule you re-decide daily, and re-deciding daily is what Anxiety 16 converts into checking.</p><p>If the risk controls are correctly built, <b>nothing you would do with the daily number is something the system has not already done, better and sooner</b>. So it provides no decision-relevant information and imposes a real cost. That asymmetry holds whether or not the profile is accurate.</p>"},{"i":"25A-5","v":"25A","s":"25a-3-emotionality-as-an-instrument","q":"What is Emotionality actually measuring, and what is the reframe?","a":"<p>Access to and awareness of your own feelings — <b>emotional granularity, not volatility</b>. You score high on both, which is unusual and exploitable.</p><p>The reframe: <b>you cannot stop the readings; you can decide whether they are inputs to decisions or entries in a log.</b> Suppression fails and costs energy. Redirection turns the same signal into data about the process.</p>"},{"i":"25A-6","v":"25A","s":"25a-3-emotionality-as-an-instrument","q":"Which state on the vocabulary table is the most dangerous, and why?","a":"<p><b>'Bright, expansive, ready to scale'</b>, following a good month. Cheerfulness 15 plus Immoderation 15.</p><p>It is the most dangerous because <b>every control in Volume 24 fires in a drawdown and none of them fires after a good month</b>. It does not feel like a loss of control — it feels like conviction.</p>"},{"i":"25A-7","v":"25A","s":"25a-4-the-upside-protocol-the-control-volume-24-is","q":"State failure mode 5 and its four drivers.","a":"<p><b>Scaling up after a good run.</b></p><p>Driven by Cheerfulness 15 (high positive affect after wins), Immoderation 15 (difficulty resisting an attractive urge), Self-Efficacy 11 (recent evidence temporarily resolves a standing doubt — a powerful reinforcer), Modesty 10 (comfortable concluding the result reflects skill).</p>"},{"i":"25A-8","v":"25A","s":"25a-4-the-upside-protocol-the-control-volume-24-is","q":"Why is a euphoric scale-up worse than a panicked de-risk?","a":"<p>A panicked de-risk costs you the recovery — real but bounded. A euphoric scale-up <b>increases exposure immediately before the mean reversion a good run makes more likely</b>, with no control watching.</p><p>And it is harder to notice: it does not feel like losing control, it feels like conviction.</p>"},{"i":"25A-9","v":"25A","s":"25a-4-the-upside-protocol-the-control-volume-24-is","q":"Give the five upside controls.","a":"<ol><li><b>Size-increase ladder</b>, pre-committed: only on a review date, max +25%, only after a full quarter at current size</li><li><b>The same 24-hour delay</b> as for de-risking — symmetry is the point</li><li><b>An upside diagnostic trigger</b>: up more than 15% requires the same written check as down 8%</li><li><b>No new strategy within 30 days of a best month</b></li><li><b>Log the good-mood urges too</b> — a log containing only bad weeks measures half the process, and the missing half is the expensive one</li></ol>"},{"i":"25A-10","v":"25A","s":"25a-5-environment-design-make-the-wrong-action-exp","q":"State the environment-design principle in one sentence, and why it is not a comment on your discipline.","a":"<p><b>Put every consequential control somewhere you cannot reach it in the state that would make you want to.</b></p><p>Not a discipline question — Self-Discipline scores 12/20, unremarkable in both directions. It is a statement about the general unreliability of in-the-moment judgement under stress, which applies to everyone and more so at Vulnerability 13 and Anxiety 16. Engineering around it is what professionals do.</p>"},{"i":"25A-11","v":"25A","s":"25a-5-environment-design-make-the-wrong-action-exp","q":"Give the structural version of three willpower rules.","a":"<ul><li>'I won't look' &rarr; <b>P&amp;L off the dashboard, broker logged out, equity curve behind a script</b></li><li>'I'll wait 24h' &rarr; <b>override requires a signed, timestamped file the code checks</b></li><li>'only when justified' &rarr; <b>size lives in a config the broker enforces; changing it needs a commit and a review date</b></li></ul>"},{"i":"25A-12","v":"25A","s":"25a-6-sustainability-and-a-burnout-buffer-of-44","q":"Give the six sustainability parameters and the one that matters most.","a":"<p>90-minute sessions; 5 days not 7; &le;8 hours of deep research a week; mornings, fixed; a genuine week off per quarter, scheduled in advance.</p><p>The one that matters: <b>stop on the timer, not on the task.</b> It prevents the hardest sessions being the longest, and it leaves a clear re-entry point for tomorrow.</p>"},{"i":"25A-13","v":"25A","s":"25a-6-sustainability-and-a-burnout-buffer-of-44","q":"Name the six burnout early-warning signals and their pre-committed responses.","a":"<ul><li>Two skipped sessions &rarr; <b>halve next week's target</b>, do not compensate</li><li><b>Reports not opened</b> &rarr; strongest signal available: halve size, three days off</li><li>Research effortful for two weeks &rarr; switch to infrastructure or reading</li><li>Checking outside protocol &rarr; log out of the broker for a week</li><li>Irritability at execution details &rarr; take the scheduled break early</li><li><b>Sleep disturbed</b> &rarr; reduce size until it stops. Not negotiable</li></ul>"},{"i":"25A-14","v":"25A","s":"25a-6-sustainability-and-a-burnout-buffer-of-44","q":"Why is the sleep test a hard constraint for you rather than soft advice?","a":"<p>With Anxiety 16 and Vulnerability 13, sleep disruption is an <b>early and reliable indicator that position size exceeds what you can hold through a normal drawdown</b> — and holding through normal drawdowns is the entire requirement of systematic trading.</p><p>A size you cannot sleep at is a size you will abandon at the worst moment, converting a temporary loss into a permanent one. Sizing down is not caution; it is the only version of the strategy you can actually run.</p>"},{"i":"25A-15","v":"25A","s":"25a-7-working-alone-and-the-one-input-you-cannot-g","q":"What can you not supply yourself, and what is the minimum viable fix?","a":"<p>Every failure mode is <b>invisible from inside</b>: overfitting feels like diligence, procrastination feels like rigour, an override feels like judgement, a scale-up feels like conviction.</p><p>Minimum fix: <b>one person, once a month, thirty minutes, asynchronous.</b> Send numbers not narrative. Their whole job is one question — 'what would have to be true for this to be wrong?' Automate the sending.</p>"},{"i":"25A-16","v":"25A","s":"25a-7-working-alone-and-the-one-input-you-cannot-g","q":"What is the specific vulnerability to trading-education selling, and what is the filter?","a":"<p>Altruism 15, Cooperation 14, Sympathy 13 and Trust 12 describe someone warm and cooperative; Gregariousness 8 means few peers to calibrate against. That is the target profile for anyone selling community plus confident answers.</p><p>Filter: <b>anyone selling a strategy, a signal or 'access' is selling the thing they would be trading if it worked.</b> A real edge with $20m capacity has no reason to recruit subscribers.</p>"},{"i":"25A-17","v":"25A","s":"25a-8-strategy-fit-scored-against-your-profile","q":"Which strategy families score Excellent for your profile, and why?","a":"<p><b>Cross-asset trend / managed futures</b> — slow (Activity Level 9), rule-based and well-documented (Liberalism 9 prefers established methods), diversified so no single position dominates, and the long flat stretches are documented in advance.</p><p><b>Cross-sectional equity factors</b> and <b>volatility targeting overlays</b> also score very good: monthly rebalancing, portfolio-level reporting, heavy on the data hygiene that suits Orderliness 16.</p>"},{"i":"25A-18","v":"25A","s":"25a-8-strategy-fit-scored-against-your-profile","q":"Which strategy families should you avoid, and for which facet in each case?","a":"<ul><li><b>Statistical arbitrage</b> — the model literally recommends adding to a diverging position: failure mode 2 written into the specification (Immoderation 15)</li><li><b>Short volatility / option selling</b> — frequent small rewards, rare large losses: the reward schedule Immoderation responds to most, and the loss shape Vulnerability 13 handles worst</li><li><b>Discretionary anything</b> — every decision made in the moment, and Neuroticism 86 makes the moment the worst available time to decide</li></ul>"},{"i":"25A-19","v":"25A","s":"25a-9-pre-mortem-how-this-ends","q":"What are the top two causes of death in the pre-mortem, and what do they have in common?","a":"<ol><li><b>Attrition</b> — no dramatic failure; sessions thinned then stopped</li><li><b>Never went live</b> — three years of research, a beautiful framework, no capital deployed</li></ol><p>Neither is a trading failure. Both are failures of <b>continuation</b> — sustaining unrewarded work, and shipping something imperfect. Neither is addressed by more knowledge, which is worth remembering when Intellect 16 proposes that the next thing to learn is the bottleneck.</p>"},{"i":"25A-20","v":"25A","s":"25a-10-the-card","q":"Recite the operating card.","a":"<ol><li>Look at P&amp;L <b>monthly</b>. Not today</li><li>A drawdown is the <b>base rate</b>, not evidence</li><li>Down days are <b>46%</b> of days. That is the design</li><li>Want to override? <b>Write it, wait 24h, re-read</b></li><li>Want to increase size? <b>Same 24h, and only on a review date</b></li><li>Certainty it is broken is a <b>state</b>, not a finding</li><li><b>Never add to a loser.</b> Never</li><li><b>Stop on the timer</b>, not the task</li><li>Not sleeping &rarr; <b>the size is wrong</b></li><li><b>Unopened reports</b> = strongest warning signal</li><li>Log the urge, act on the protocol</li><li><b>The work is showing up, not knowing more</b></li></ol>"},{"i":"05-5","v":"05","s":"5-5-from-signal-to-portfolio","q":"How does a signal become a portfolio, and what is lost at each step?","a":"<p>Signal &rarr; z-score &rarr; target weights &rarr; constrained weights &rarr; traded weights.</p><p>Neutralisation removes intended and unintended exposure alike; constraints cut the transfer coefficient; turnover limits delay the signal. By the end, a portfolio typically realises <b>a third to a half</b> of the paper information ratio — and that gap is where most 'the backtest was better' comes from.</p>"},{"i":"07-4","v":"07","s":"7-3-graph-neural-networks-on-economic-relationships","q":"Why is a train/validation/test split insufficient for a neural network on financial data?","a":"<p>Because you look at the validation set hundreds of times while tuning, so it becomes part of the training procedure. The test set is then the only honest measure — and it is used once, or it is not a test set.</p><p>Combined with purged CV and an embargo, and with the trial count recorded, this is the minimum honest protocol.</p>"},{"i":"07-5","v":"07","s":"7-5-regularisation-that-actually-matters-here","q":"What is the honest role of a language model in a systematic pipeline?","a":"<p><b>Feature extraction</b> from text — entity linking, event classification, sentiment — feeding a conventional model that you can validate.</p><p>Not end-to-end prediction: the trial count is unmanageable, the failure modes are opaque, and you cannot attribute a loss to anything you can fix.</p>"},{"i":"08-5","v":"08","s":"8-4-beyond-black-scholes","q":"What is the variance risk premium, and what is its payoff shape?","a":"<p>Implied variance exceeds subsequent realised variance on average — compensation to whoever is short volatility. It is one of the more durable returns in finance.</p><p>The payoff is brutally asymmetric: slightly positive most months, catastrophically negative occasionally, with skew around &minus;3. A high Sharpe over a benign decade is completely uninformative about its risk.</p>"},{"i":"09-4","v":"09","s":"9-3-an-order-book-that-does-not-chase-pointers","q":"Why does a systematic trader at retail latency still care about Volume 9?","a":"<p>Not to compete on speed, but to <b>understand what you are up against</b>: why your passive orders fill adversely, why your quoted price is stale, and why a strategy that looks profitable on 1-second bars is not.</p><p>It also sets the boundary: any edge that requires sub-millisecond reaction is not available to you, and knowing that saves months.</p>"},{"i":"09-5","v":"09","s":"9-5-the-system-level-knobs","q":"What is the single most useful low-latency practice for a non-HFT system?","a":"<p><b>Measure and log the full path</b> — decision time, send time, ack time, fill time — on every order, and alert on the p99.</p><p>You are not optimising it. You are detecting the day it changes, which is usually the first sign that a broker changed routing or a venue changed its matching behaviour.</p>"},{"i":"10-4","v":"10","s":"10-2-the-standard-algorithms","q":"Name the standard execution algorithms and when each is right.","a":"<ul><li><b>TWAP</b> — no volume information; simple, predictable, gameable</li><li><b>VWAP</b> — match the day's volume profile; right when your benchmark is VWAP</li><li><b>POV</b> — fixed participation; right when you care about footprint more than completion time</li><li><b>Implementation shortfall</b> — Almgren&ndash;Chriss with your risk aversion; right when you have alpha decay</li></ul>"},{"i":"10-5","v":"10","s":"10-5-order-types-and-venue-mechanics","q":"What do the main order types cost you, in one line each?","a":"<ul><li><b>Market</b> — immediate, pays the spread and impact, no adverse selection</li><li><b>Limit</b> — earns the spread, pays adverse selection, may not fill</li><li><b>Peg</b> — follows the touch; reduces stale-quote risk, increases messaging</li><li><b>Iceberg</b> — hides size, loses queue priority on each refresh</li></ul>"},{"i":"10A-4","v":"10A","s":"10a-2-the-algorithms-and-which-to-use","q":"Why should an RL execution project start tabular?","a":"<p>Because a tabular Q-learner over five state buckets and five actions is <b>a hundred numbers you can print and inspect</b>, and can be checked against Almgren&ndash;Chriss.</p><p>Starting with a deep actor&ndash;critic gives you something unstable and unexplainable, where you cannot tell whether a bad policy came from the algorithm, the reward, the simulator or the state design — and all four are wrong at first.</p>"},{"i":"11-7","v":"11","s":"11-1-mean-variance-and-why-it-fails-in-practice","q":"In one sentence, why does mean&ndash;variance fail in practice when the algebra is correct?","a":"<p>Because it is a <b>maximally efficient consumer of its inputs</b>, and its inputs — especially expected returns — are estimated with error comparable to their size, so it converts estimation error into extreme positions.</p>"},{"i":"12-7","v":"12","s":"12-2-extreme-value-theory-for-the-part-that-matters","q":"Why estimate tail risk by EVT rather than by fitting a distribution to all the data?","a":"<p>Because a full-sample fit is dominated by the <b>body</b>, which has thousands of observations, and the body's shape has almost nothing to do with the tail's.</p><p>EVT fits only the exceedances over a high threshold, where the limiting form is known regardless of the underlying distribution.</p>"},{"i":"13-6","v":"13","s":"13-2-volatility-targeting-the-mechanism-that-does-mo","q":"What is the mechanical reason volatility targeting raises geometric return?","a":"<p>Because compounded return is &mu; &minus; &sigma;&sup2;/2 (0A.3): stabilising &sigma; at a target reduces the <em>average</em> of &sigma;&sup2; relative to a strategy with the same mean and fluctuating volatility, by Jensen.</p><p>You are not forecasting anything. You are removing a drag term.</p>"},{"i":"14-5","v":"14","s":"14-5-where-the-structural-edges-actually-are","q":"What is MEV, and what is the practical exposure for an ordinary participant?","a":"<p>Value extractable by reordering, inserting or censoring transactions in a block — sandwiching, back-running, liquidation racing.</p><p>Practical exposure: your swaps get <b>sandwiched</b>. Defences are tight slippage limits, private mempools/relays, and splitting large trades — the same footprint logic as Volume 10, in a public queue.</p>"},{"i":"15-5","v":"15","s":"15-5-a-research-data-architecture-that-scales","q":"What does a research data architecture need that an ad-hoc one does not?","a":"<ol><li><b>Immutable raw</b> — never overwrite a source file; corrections arrive as new versions</li><li><b>A manifest</b> — source, retrieval date, row count, content hash, all in version control</li><li><b>As-of joins</b> as the default join, not a special case</li><li><b>A single universe builder</b> that every strategy calls, so survivorship is fixed once</li></ol>"},{"i":"16-5","v":"16","s":"16-2-the-fill-model-is-the-backtest","q":"Give the minimum honest limit-order fill rule.","a":"<p>A resting limit fills only if the price <b>trades through</b> your level, not merely touches it — and even then, only for the volume that traded beyond you.</p><p>Filling on touch assumes you were first in the queue, which is the assumption that makes passive strategies look profitable in backtest and lose money live.</p>"},{"i":"17-5","v":"17","s":"17-5-deployment-and-change-management","q":"What makes a deployment safe in a trading system?","a":"<ol><li>The change is in <b>version control</b> and reviewed</li><li>It runs in <b>shadow</b> against live data first, with outputs diffed against production</li><li>It goes live at <b>reduced size</b></li><li>There is a <b>rollback</b> that has been tested, not just written down</li><li>Nothing deploys on a Friday, or into an event</li></ol>"},{"i":"18-5","v":"18","s":"18-4-the-catalogue-of-biases","q":"Name five biases from the catalogue and the direction each pushes.","a":"<ul><li><b>Survivorship</b> — inflates returns</li><li><b>Look-ahead</b> — inflates everything, often enormously</li><li><b>Selection / data snooping</b> — inflates the best result specifically</li><li><b>Ignoring costs</b> — inflates high-turnover strategies most</li><li><b>Outlier dependence</b> — the edge is three days; check by removing the best 1% of days</li></ul>"},{"i":"19-4","v":"19","s":"19-1-the-competition-landscape","q":"What are competitions actually good for?","a":"<p>Building a <b>verifiable public track record of process</b>, and forcing you to work to a deadline with a fixed evaluation you cannot move.</p><p>Not for finding strategies: the objective is not your objective, the data is not point-in-time in your universe, and the leaderboard is a giant multiple-testing machine.</p>"},{"i":"19-5","v":"19","s":"19-3-the-roles-and-what-they-actually-involve","q":"What do the main quant roles actually involve?","a":"<ul><li><b>Researcher</b> — signal generation and validation; long horizons, mostly negative results</li><li><b>Trader / PM</b> — sizing, risk, execution decisions; owns the P&amp;L</li><li><b>Quant developer</b> — the systems everything runs on; usually the highest leverage and lowest glamour</li><li><b>Risk</b> — the only seat with a mandate to say no</li></ul>"},{"i":"21-4","v":"21","s":"21-5-realised-volatility-estimators","q":"Why use a realised-volatility estimator other than close-to-close?","a":"<p>Because close-to-close throws away the intraday range. Parkinson, Garman&ndash;Klass and Rogers&ndash;Satchell use high/low/open and are <b>4&ndash;8&times; more efficient</b> for the same sample.</p><p>Caveat: they assume no overnight gaps and continuous observation, so they understate volatility for gappy assets. Yang&ndash;Zhang handles the gap.</p>"},{"i":"21-5","v":"21","s":"21-7-transaction-cost-model-calibration","q":"How do you calibrate a transaction cost model, and what do you calibrate it against?","a":"<p>Regress <b>your own realised slippage</b> versus the decision-time microprice on participation rate, in logs (2A.5). Never against VWAP, which your own trading contaminates.</p><p>Re-estimate quarterly and alert when the constant moves more than 30%.</p>"},{"i":"22-3","v":"22","s":"22-3-two-worked-implementations","q":"What should you actually do with the 101 alphas?","a":"<p>Use them as a <b>feature library</b> and as a worked demonstration of the operator language. Combine, neutralise and validate them like any other feature set — with a recorded trial count.</p><p>Treating them individually as strategies means trading a 2016 publication, net of costs, against everyone else who read it.</p>"},{"i":"23-3","v":"23","s":"23-2-the-bank","q":"Which problem categories carry most of the value in a bank of 106?","a":"<p><b>Probability and expectation</b> (the interview staple), and <b>stochastic calculus</b> (the one that separates candidates). Linear algebra and optimisation are checks rather than instruction.</p><p>Sample across categories rather than working in order, and stop when you can narrate a solution reliably.</p>"},{"i":"26-1","v":"26","s":"26-1-what-a-strategy-actually-is","q":"A systematic strategy is six decisions and one discipline. Name them, and say which of the six actually decides whether you make money.","a":"<p>Universe, <b>signal</b>, shaping, <b>sizing</b>, risk, execution &mdash; and the discipline is <b>validation</b>.</p><p>The signal is the part that feels like having an idea and is the <em>least</em> decisive of the six. <b>Sizing and costs decide the outcome.</b> A mediocre signal sized well beats a good signal sized badly.</p>"},{"i":"26-2","v":"26","s":"26-2-a-market-whose-answer-you-already-know","q":"Why is a generated market able to teach something that no backtest on real data can?","a":"<p>Because you <b>set whether an edge exists</b>. With real data there is one history, you have already looked at it, and there is no way to ask whether a Sharpe of 0.8 was skill or luck.</p><p>Set the trend strength to zero and any strategy that still looks good is measuring your search rather than the market &mdash; and that is a fact you can verify rather than a warning you have to take on trust.</p>"},{"i":"26-3","v":"26","s":"26-5-reading-a-result-honestly","q":"What is the specific two-part signature of lookahead in a backtest?","a":"<p>A Sharpe ratio that is <b>implausibly high</b> together with a maximum drawdown that is <b>implausibly small</b>.</p><p>Either alone is ambiguous; the pair is diagnostic. A rough check: the worst drawdown of a strategy with Sharpe <i>S</i> tends to be of the order of its annual volatility divided by <i>S</i>. A Sharpe of 2 with a 4% drawdown does not satisfy that at any realistic volatility.</p><p>First diagnostic, always: <b>shift the signal back one more bar and re-run.</b> If it collapses, it was cheating.</p>"},{"i":"26-4","v":"26","s":"26-6-why-the-trial-counter-cannot-be-optional","q":"You run a 9&times;7 parameter sweep and keep the best cell. How many trials is that, and roughly what Sharpe should you have expected from noise alone?","a":"<p><b>Sixty-three trials</b>, not one &mdash; you looked at all sixty-three and kept the best.</p><p>At around sixty trials on ten years of daily data, the expected best Sharpe from a market containing <em>nothing</em> is roughly <b>2.2</b>. A swept result below that is not evidence of anything.</p><p>Worse: the count follows the data, not the session. Everything anyone has ever tried on the same history counts.</p>"},{"i":"26-5","v":"26","s":"26-5-reading-a-result-honestly","q":"What is the difference between a parameter <em>plateau</em> and a parameter <em>spike</em>, and why does it matter more than the best cell?","a":"<p>A <b>plateau</b> is a broad region of the parameter grid that all works, degrading gently as you move away from the centre. A <b>spike</b> is one good cell surrounded by cells that fail.</p><p>A real effect has a mechanism, and mechanisms do not switch off between a 58-day and a 62-day lookback. A spike means the parameter was fitted to the particular noise in this sample, and that noise will not repeat.</p><p>The best cell is the <em>least</em> informative number on the grid, because it is the one selection bias acts on most strongly.</p>"},{"i":"26-6","v":"26","s":"26-4-the-language-a-signal-is-written-in","q":"Why does a Donchian breakout rule need a <code>hold()</code> operator, and what would happen without one?","a":"<p>A breakout rule fires <b>only on the day a new extreme is made</b>. On every other day the raw expression is zero.</p><p>Without carrying the last non-zero value forward, the strategy would hold a position for exactly one day and then go flat &mdash; which is not a breakout system at all, and would produce enormous turnover and a meaningless backtest.</p><p>Note also that the channel must be built from <code>delay(high, 1)</code>: comparing today's close to a range that includes today is lookahead.</p>"},{"i":"26-7","v":"26","s":"26-7-out-of-the-browser-and-into-a-repository","q":"Name three things a small backtester omits that make every result it produces better than reality.","a":"<p>Any three of:</p><ul><li><b>Point-in-time data</b> &mdash; no restatements, no delistings, no historical index membership.</li><li><b>A fill model</b> &mdash; positions change in full, at the close, always.</li><li><b>Borrow and financing</b>, and the real cost of holding a short.</li><li><b>Capacity</b> &mdash; impact as a chosen coefficient rather than your size against real volume.</li><li><b>Portfolio construction</b> &mdash; asset-by-asset sizing ignores the correlations.</li></ul><p>The direction is the point: every omission flatters. Assume the laboratory is optimistic, because it is.</p>"},{"i":"26-8","v":"26","s":"26-1-what-a-strategy-actually-is","q":"You have a signal with a gross Sharpe of 1.2 and a net Sharpe of &minus;0.4 at four basis points of half-spread. What is the first thing to try, and why that first?","a":"<p><b>Smooth the signal</b> &mdash; wrap it in an <code>ema</code> of a few days.</p><p>The gap between gross and net is turnover, and smoothing is the cheapest way to reduce turnover: it trades a small amount of gross edge for a large reduction in trading. Push it until net stops improving.</p><p>If nothing survives, the honest conclusion is that the edge belongs to someone whose fills are better than yours, which is a real answer and a common one.</p>"},{"i":"0c-1-conditional-expectation-is-a-random-variable-1","v":"0C","s":"0c-1-conditional-expectation-is-a-random-variable","q":"State the tower property and the conditional variance decomposition, and give one trading use of each.","a":"<p><b>Tower:</b> E[E[X|Y]] = E[X], and more generally E[E[X|ℱ]|𝒢] = E[X|𝒢] for 𝒢 ⊆ ℱ — the coarser conditioning wins. Use: price by conditioning on the first step and averaging, which is what a binomial tree does recursively, and what makes a martingale's expectation flat.</p><p><b>Variance:</b> Var(X) = E[Var(X|Y)] + Var(E[X|Y]) — within-regime risk plus between-regime risk. Use: a book sized on the within-regime number and then run through the regime shift is the standard way a risk model is wrong by a factor rather than by a percentage.</p>"},{"i":"0c-2-lotus-moment-generating-functions-and-what-they-buy-1","v":"0C","s":"0c-2-lotus-moment-generating-functions-and-what-they-buy","q":"Why is option pricing under a stochastic volatility model done through the characteristic function rather than the moment generating function?","a":"<p>The MGF E[e<sup>tX</sup>] need not exist — for heavy-tailed laws it is infinite for every t &gt; 0 — while the <b>characteristic function</b> E[e<sup>itX</sup>] always exists, because |e<sup>itX</sup>| = 1.</p><p>Heston and its relatives have a semi-analytic characteristic function, so vanillas price by Fourier inversion in microseconds. A missing MGF is also a diagnosis in its own right: it says the tail is too heavy for any exponential bound to apply.</p>"},{"i":"0c-2-lotus-moment-generating-functions-and-what-they-buy-2","v":"0C","s":"0c-2-lotus-moment-generating-functions-and-what-they-buy","q":"What single property makes moment generating functions worth the trouble?","a":"<p><b>The MGF of a sum of independent variables is the product of their MGFs.</b> Convolution — the hard operation — becomes multiplication, which is the easy one.</p><p>That is why MGFs (and their always-existing cousin, the characteristic function) are the standard route to distributions of sums, to the central limit theorem, and to Chernoff bounds.</p>"},{"i":"0c-3-the-four-inequalities-worth-knowing-by-name-1","v":"0C","s":"0c-3-the-four-inequalities-worth-knowing-by-name","q":"Which inequality explains volatility drag, and how?","a":"<p><b>Jensen's.</b> For a concave function φ, E[φ(X)] ≤ φ(E[X]); the logarithm is concave, so E[ln S<sub>T</sub>] ≤ ln E[S<sub>T</sub>].</p><p>The gap is exactly the −½σ²t in the exponent of geometric Brownian motion (20.4): the median path falls below the mean, and the shortfall grows with variance. Run the same inequality with a convex payoff and the gap becomes the value of optionality — which is what a long option position owns.</p>"},{"i":"0c-4-order-statistics-and-why-the-maximum-is-the-interesting-one-1","v":"0C","s":"0c-4-order-statistics-and-why-the-maximum-is-the-interesting-one","q":"Why is the Sharpe ratio from a parameter sweep an order statistic, and what does that imply about its size?","a":"<p>Because you report the <b>best</b> cell, not a random one. The best of N draws from the null has the law F(x)<sup>N</sup>, and the maximum of N standard normals grows like <b>√(2 ln N)</b>.</p><p>That growth is slow enough to be deceptive: about 1.19 at five trials, 2.0 at twenty-five, 3.26 at a thousand. None of those looks absurd on a tear sheet, which is why the trial count has to be recorded rather than recalled (18.1, 26.6).</p>"},{"i":"0c-4-order-statistics-and-why-the-maximum-is-the-interesting-one-2","v":"0C","s":"0c-4-order-statistics-and-why-the-maximum-is-the-interesting-one","q":"Why is the maximum of N draws the order statistic that matters in finance?","a":"<p>Because the strategy you report is the <b>best of N</b> you tried, and the maximum of N standard normals grows roughly like &radic;(2 ln N).</p><p>That growth is <b>slow</b>, which is exactly what makes it dangerous: with a hundred trials the inflated best-of-N Sharpe still looks like a plausible number rather than an obviously absurd one.</p>"},{"i":"0c-5-markov-chains-and-the-two-questions-you-ask-of-one-1","v":"0C","s":"0c-5-markov-chains-and-the-two-questions-you-ask-of-one","q":"For a two-state regime-switching model, how do you read persistence and expected duration off the transition matrix?","a":"<p><b>Persistence</b> is the diagonal: P<sub>ii</sub> is the chance of staying in state <em>i</em> next period. <b>Expected duration</b> in state <em>i</em> is <b>1/(1 − P<sub>ii</sub>)</b>, the mean of a geometric.</p><p>So P<sub>11</sub> = 0.98 on daily data means a calm regime lasting about fifty days on average. Implausibly short fitted durations usually mean the true state space is larger than two and the chain is absorbing the misfit as rapid switching.</p>"},{"i":"0c-6-poisson-processes-and-the-exponential-clock-1","v":"0C","s":"0c-6-poisson-processes-and-the-exponential-clock","q":"What does thinning a Poisson process give you, and why is the independence surprising?","a":"<p>Mark each arrival independently as type A with probability p. The A-stream and the B-stream are each Poisson, with rates <b>pλ</b> and <b>(1−p)λ</b> — and they are <b>independent of each other</b>.</p><p>Independence is surprising because the two streams are carved out of one sequence of arrivals, so you would expect them to compete. It is useful because it means the count of your own fills, if they are a thinned stream of order arrivals, carries no information about anybody else's count.</p>"},{"i":"0c-6-poisson-processes-and-the-exponential-clock-2","v":"0C","s":"0c-6-poisson-processes-and-the-exponential-clock","q":"What does memorylessness mean, and which distribution alone has it?","a":"<p>Having waited already tells you <b>nothing</b> about how much longer you will wait: P(T &gt; s + t | T &gt; s) = P(T &gt; t).</p><p>Only the <b>exponential</b> distribution (and its discrete cousin the geometric) has it. That is why a constant-hazard model forgets everything, and why a term structure of hazard rates is used in practice instead of a single number.</p>"},{"i":"0c-7-the-multivariate-normal-and-the-three-facts-you-will-reuse-1","v":"0C","s":"0c-7-the-multivariate-normal-and-the-three-facts-you-will-reuse","q":"Write the conditional mean and variance of a multivariate normal, and name the two standard methods that are this formula.","a":"<p>E[X₁|X₂] = μ₁ + Σ₁₂Σ₂₂<sup>−1</sup>(X₂ − μ₂), with conditional covariance Σ₁₁ − Σ₁₂Σ₂₂<sup>−1</sup>Σ₂₁ — which <b>does not depend on the observed value</b>.</p><p>It is the <b>Kalman filter</b> update (3.4): prior, observation, and a linear correction weighted by covariances — which is why the uncertainty band narrows on schedule rather than in response to the data. It is also <b>OLS</b>, with prior and observation relabelled.</p>"},{"i":"0c-7-the-multivariate-normal-and-the-three-facts-you-will-reuse-2","v":"0C","s":"0c-7-the-multivariate-normal-and-the-three-facts-you-will-reuse","q":"Name the three properties of the multivariate normal that everything else leans on.","a":"<p><b>1. Closed under linear combination</b> — any weighted sum of jointly normal variables is normal, which is the whole reason portfolio variance is a quadratic form.</p><p><b>2. Closed under conditioning</b> — the conditional distribution is normal with a mean linear in the conditioning variables. That is regression, and it is why the Kalman filter is exact.</p><p><b>3. Zero covariance implies independence</b> — true here and false in general, which is what makes the assumption so seductive and so dangerous in the tails.</p>"},{"i":"0d-1-root-finding-and-the-implied-volatility-problem-1","v":"0D","s":"0d-1-root-finding-and-the-implied-volatility-problem","q":"Why is Newton's method the wrong default for implied volatility, and what replaces it?","a":"<p>The Newton step divides by <b>vega</b>, which goes to zero for deep in- or out-of-the-money options. The iterate is then thrown to an absurd or negative volatility. It looks fine on a quiet day and fails across the whole surface at once on the day a crash pushes many strikes deep.</p><p>Use a <b>bracket plus Brent</b>: superlinear when safe, bisection when not, and guaranteed to converge. Check the quote is inside the no-arbitrage bounds first — a price below intrinsic has no implied volatility, and the right answer is to reject it rather than return a number.</p>"},{"i":"0d-1-root-finding-and-the-implied-volatility-problem-2","v":"0D","s":"0d-1-root-finding-and-the-implied-volatility-problem","q":"Why is bisection still the right default for implied volatility?","a":"<p>Because it <b>cannot fail</b> once you have a bracket. Newton converges faster but needs a derivative and can diverge when vega is tiny — deep in or out of the money, or close to expiry — which is exactly where a solver gets called on stale or crossed quotes.</p><p>The production answer is a hybrid: Newton or Brent inside a guaranteed bracket, with a hard iteration cap and an explicit failure return rather than a silent last iterate.</p>"},{"i":"0d-2-quadrature-when-to-integrate-and-when-to-simulate-1","v":"0D","s":"0d-2-quadrature-when-to-integrate-and-when-to-simulate","q":"What decides between deterministic quadrature and Monte Carlo, and what is the crossover?","a":"<p><b>Dimension.</b> Quadrature costs m<sup>d</sup> evaluations for m points per axis — exponential in d. Monte Carlo error is O(n<sup>−1/2</sup>) <b>whatever the dimension</b>.</p><p>The crossover is around <b>four dimensions</b>. Below it, simulating is wasteful — Simpson gets four digits from dozens of evaluations where Monte Carlo needs hundreds of millions. Above it, quadrature is simply unavailable.</p>"},{"i":"0d-3-monte-carlo-and-the-four-variance-reductions-worth-knowing-1","v":"0D","s":"0d-3-monte-carlo-and-the-four-variance-reductions-worth-knowing","q":"Name the control variate that is always available when pricing an exotic by simulation, and why it works.","a":"<p>Price the corresponding <b>European vanilla on the same paths</b>, subtract it, and add back its known closed form.</p><p>It works because the two payoffs share the terminal distribution and are therefore highly correlated, so most of the sampling noise cancels. The canonical case is an arithmetic Asian controlled by its geometric counterpart, which has a closed form and routinely cuts the error by twenty times or more.</p>"},{"i":"0d-4-finite-differences-and-the-stability-condition-nobody-checks-1","v":"0D","s":"0d-4-finite-differences-and-the-stability-condition-nobody-checks","q":"Why does a grid method beat simulation for American options, and what does Longstaff–Schwartz have to do instead?","a":"<p>Optimal stopping requires <b>backward induction</b> — at each node you compare the continuation value with the exercise value and keep the larger. A grid holds every node, so it is one comparison per point.</p><p>Monte Carlo walks <b>forward</b> and has no continuation value available, so Longstaff–Schwartz <b>regresses</b> one from the cross-section of paths. Because the exercise rule is estimated rather than optimal, the resulting figure is a <b>lower bound</b> on the true price, not the price.</p>"},{"i":"0d-4-finite-differences-and-the-stability-condition-nobody-checks-2","v":"0D","s":"0d-4-finite-differences-and-the-stability-condition-nobody-checks","q":"What distinguishes explicit from implicit finite-difference schemes, and why does it matter?","a":"<p><b>Explicit</b> schemes step forward directly and are cheap per step, but are only stable when the time step is small relative to the square of the space step — halve the grid spacing and you need four times as many steps.</p><p><b>Implicit</b> and Crank–Nicolson schemes solve a linear system at each step and are unconditionally stable, so the step size is set by accuracy rather than by stability. That is almost always the better trade.</p>"},{"i":"0d-5-constrained-optimisation-in-practice-1","v":"0D","s":"0d-5-constrained-optimisation-in-practice","q":"A calibration converges to different parameters on consecutive days. What has it told you, and what is the fix?","a":"<p>That the objective is <b>non-convex with multiple minima</b> — not that the market changed. The answer depends on the starting point.</p><p>Fix: <b>start from yesterday's solution</b>, record the objective value achieved, and alert when that value jumps rather than when the parameters do. Better still, reformulate so the problem is convex — an L1 penalty in place of a cardinality constraint, a CVaR constraint in place of a hard drawdown limit — so there is a unique answer to defend.</p>"},{"i":"0d-5-constrained-optimisation-in-practice-2","v":"0D","s":"0d-5-constrained-optimisation-in-practice","q":"Before trusting an optimiser's answer, what three things should you check?","a":"<p><b>1. Is the problem convex?</b> If it is, a local optimum is global and you can trust the solver. If not, the answer depends on the starting point and must be run from several.</p><p><b>2. Are the constraints active?</b> A solution sitting on a bound is a solution determined by the bound, not by the objective — often the real finding.</p><p><b>3. Is it stable?</b> Perturb the inputs within their standard errors and re-solve. A solution that moves a lot is reporting estimation error, not an optimum.</p>"},{"i":"1a-1-the-two-fundamental-theorems-and-what-each-actually-says-1","v":"1A","s":"1a-1-the-two-fundamental-theorems-and-what-each-actually-says","q":"State both fundamental theorems, and say what it means when the second one fails.","a":"<p><b>First:</b> no arbitrage ⟺ there exists at least one equivalent martingale measure ℚ under which discounted prices are martingales. <b>Second:</b> the market is complete ⟺ that ℚ is unique.</p><p>When uniqueness fails — stochastic volatility with no traded vol instrument, random-size jumps, more risk sources than tradeable assets — there is a <b>range</b> of arbitrage-free prices. The model then <i>selects</i> a measure rather than deriving a price, and the number is a quote defensible only insofar as the calibration instruments span the risk you are taking.</p>"},{"i":"1a-1-the-two-fundamental-theorems-and-what-each-actually-says-2","v":"1A","s":"1a-1-the-two-fundamental-theorems-and-what-each-actually-says","q":"State the two fundamental theorems of asset pricing, and say what incompleteness therefore means for price.","a":"<p><b>First:</b> no arbitrage ⟺ there exists at least one equivalent martingale measure. Existence of a risk-neutral measure <i>is</i> the absence of arbitrage.</p><p><b>Second:</b> that measure is unique ⟺ the market is complete. Uniqueness of the price is the same statement as the ability to replicate.</p><p>So incompleteness is not a modelling inconvenience — it means a <i>range</i> of prices is consistent with no arbitrage, and something outside the model must pick one.</p>"},{"i":"1a-2-change-of-numeraire-the-trick-that-removes-half-the-algebra-1","v":"1A","s":"1a-2-change-of-numeraire-the-trick-that-removes-half-the-algebra","q":"Why does the T-forward measure simplify pricing under stochastic rates?","a":"<p>Under ℚ you must compute E<sup>ℚ</sup>[e<sup>−∫r ds</sup> · Payoff], and with random rates the discount factor is <b>correlated with the payoff</b>, so the two cannot be separated.</p><p>Taking the zero-coupon bond P(t,T) as numéraire gives <b>Price = P(0,T)·E<sup>T</sup>[Payoff]</b>: the discounting comes out as today's observable bond price and the expectation is clean. Every forward-rate market model is stated in this measure for exactly that reason.</p>"},{"i":"1a-3-stopping-times-and-what-makes-a-rule-legitimate-1","v":"1A","s":"1a-3-stopping-times-and-what-makes-a-rule-legitimate","q":"Give two exit rules that are not stopping times, and say what they correspond to in a backtest.","a":"<p><b>Exit at the maximum of the path</b> and <b>exit one day before the crash</b>. Neither is decidable from information available at the time — you need the future to know you have stopped.</p><p>Both are formal statements of <b>lookahead</b>. Sizing by volatility computed over the whole sample is the same error in another form. The resulting equity curve is not achievable by any strategy, and it shows up as the signature of implausibly high Sharpe with implausibly small drawdown (26.8).</p>"},{"i":"1a-3-stopping-times-and-what-makes-a-rule-legitimate-2","v":"1A","s":"1a-3-stopping-times-and-what-makes-a-rule-legitimate","q":"What makes an exit rule a legitimate stopping time, and why does it matter for backtests?","a":"<p>The decision to stop at time <i>t</i> must depend only on information available <b>at</b> <i>t</i>. 'Sell when the drawdown hits 10%' qualifies; 'sell at the high' does not.</p><p>It matters because an illegitimate rule is exactly what look-ahead bias looks like from the inside. Every backtest exit should be checkable against this one criterion, and most reported failures of 'obvious' strategies are a stopping rule that used tomorrow's data.</p>"},{"i":"1a-4-american-options-free-boundaries-and-the-price-of-waiting-1","v":"1A","s":"1a-4-american-options-free-boundaries-and-the-price-of-waiting","q":"Why is early exercise of an American call never optimal without dividends, and what changes for a put?","a":"<p>Exercising a call early pays the strike sooner — forfeiting interest on it — and gives up the remaining downside protection. The European call already trades above intrinsic, so the option is worth more alive than dead. A discrete dividend can reverse this just before the ex-date.</p><p>A <b>put</b> is the mirror: exercising <i>receives</i> the strike now and earns interest on it, and deep in the money the surrendered optionality is small. So early exercise is often optimal, and the American put has no closed form.</p>"},{"i":"1a-5-jump-diffusion-and-why-it-cannot-be-hedged-away-1","v":"1A","s":"1a-5-jump-diffusion-and-why-it-cannot-be-hedged-away","q":"Why does a jump-diffusion make the market incomplete, and what does that do to a delta hedge?","a":"<p>A delta hedge cancels <b>infinitesimal</b> moves. A jump is not infinitesimal: when the price gaps, the option and the hedge change by different amounts and the difference cannot be rebalanced away.</p><p>With jumps of <b>random size</b> there is one hedging instrument against a continuum of outcomes, so no self-financing portfolio replicates the claim. By the second fundamental theorem the martingale measure is not unique, and a range of prices is arbitrage-free. For a short-gamma book the gap loss goes as ½Γ(ΔS)² — quadratic in the gap, which is why the Greeks do not describe the risk.</p>"},{"i":"1a-5-jump-diffusion-and-why-it-cannot-be-hedged-away-2","v":"1A","s":"1a-5-jump-diffusion-and-why-it-cannot-be-hedged-away","q":"Why does adding jumps make a market incomplete, and what follows practically?","a":"<p>Replication in Black–Scholes relies on <b>continuous rebalancing</b>. You cannot rebalance through a gap, so a delta hedge no longer eliminates the risk and no unique price is forced.</p><p>Practically: the model returns a price and a hedge that leaves <b>residual jump exposure</b>, and that residual has to be sized and limited explicitly rather than assumed away. Short gamma then loses a bounded amount to diffusion and an unbounded amount to a gap.</p>"},{"i":"1a-6-the-market-price-of-risk-and-how-p-and-q-differ-in-practice-1","v":"1A","s":"1a-6-the-market-price-of-risk-and-how-p-and-q-differ-in-practice","q":"Risk-neutral default probabilities exceed historical ones for the same rating. Which is wrong?","a":"<p><b>Neither.</b> They answer different questions. The risk-neutral figure comes from a <b>price</b> (ℚ) and therefore embeds a risk premium; the historical figure is a real-world frequency (ℙ).</p><p>The gap between them <i>is</i> the credit risk premium — a tradeable object, not an inconsistency. Using the ℚ number to forecast losses overstates them; using the ℙ number to quote a CDS produces a price that will be traded against you all day. The variance risk premium (8A.5) is the same structure.</p>"},{"i":"2b-1-the-taxonomy-who-trades-and-why-1","v":"2B","s":"2b-1-the-taxonomy-who-trades-and-why","q":"Why does 'who is losing to this strategy?' have to have an answer?","a":"<p>Because trading is <b>zero-sum before costs and negative-sum after them</b>. The gains of dealers, arbitrageurs and informed traders are paid, in aggregate, by utilitarian and noise traders.</p><p>So if you cannot name the population supplying your profit — and say why they are willing to keep supplying it — you have not identified an edge. The default answer at retail size is that the population is you, paying a professional for immediacy.</p>"},{"i":"2b-2-liquidity-has-four-dimensions-and-they-trade-off-1","v":"2B","s":"2b-2-liquidity-has-four-dimensions-and-they-trade-off","q":"Name liquidity's four dimensions and say which one a large rebalancing order consumes.","a":"<p><b>Immediacy</b> (how fast), <b>width</b> (what a small trade costs), <b>depth</b> (how much at that price), <b>resiliency</b> (how fast the book refills).</p><p>A large rebalance consumes <b>depth</b> and pays impact, so the cost model is the propagator of 2A, not the spread. A short-horizon signal consumes immediacy and pays width. All four deteriorate together in stress, which is why costs calibrated on ordinary days understate the trade you will be forced to do.</p>"},{"i":"2b-2-liquidity-has-four-dimensions-and-they-trade-off-2","v":"2B","s":"2b-2-liquidity-has-four-dimensions-and-they-trade-off","q":"Name liquidity's four dimensions and say which one a snapshot of the book cannot show.","a":"<p><b>Immediacy</b> (how fast you can trade), <b>width</b> (the spread), <b>depth</b> (how much sits at each level), and <b>resiliency</b> (how quickly the book refills after being hit).</p><p>A snapshot shows width and depth. It cannot show <b>resiliency</b>, which is the dimension that decides whether you can repeat the trade — and the one that disappears first in a crisis.</p>"},{"i":"2b-3-the-spread-decomposed-into-its-three-costs-1","v":"2B","s":"2b-3-the-spread-decomposed-into-its-three-costs","q":"Split the spread into its three components, and say which competition cannot remove.","a":"<p><b>Order processing</b> (fees, clearing, technology), <b>inventory</b> (risk of holding the position until it can be laid off), and <b>adverse selection</b> (expected loss to better-informed counterparties).</p><p>Competition compresses the first two toward marginal cost. It <b>cannot</b> compress adverse selection, because that is a <i>transfer</i> to informed traders rather than a margin. So a perfectly competitive market in a heavily informed name will still quote a wide spread — and must.</p>"},{"i":"2b-4-auctions-the-opening-the-closing-and-why-they-exist-1","v":"2B","s":"2b-4-auctions-the-opening-the-closing-and-why-they-exist","q":"Why does the trading day open and close with a call auction rather than continuously?","a":"<p><b>Open:</b> information accumulated overnight with no trading, so the first price must aggregate a great deal of interest at once. A continuous market would do this badly, one order at a time, with the earliest arrivals bearing all the uncertainty.</p><p><b>Close:</b> an enormous set of participants need <i>the same</i> price — index funds on close-based benchmarks, NAV strikes, derivative settlement. Concentrating that demand into one cross is what makes it cheap to serve, and it is now the largest liquidity event of the day in many equity markets.</p>"},{"i":"2b-4-auctions-the-opening-the-closing-and-why-they-exist-2","v":"2B","s":"2b-4-auctions-the-opening-the-closing-and-why-they-exist","q":"Why does the closing auction carry such a large share of daily volume?","a":"<p>Because the closing price is the <b>benchmark most mandates are measured against</b> — index funds, NAV calculations and many performance contracts all reference it.</p><p>Everyone measured against the close trades at the close, which concentrates flow into a single uncrossing. That makes the auction the most liquid moment of the day and also the moment at which a predictable, mechanical order is most exposed to being anticipated.</p>"},{"i":"2b-5-blocks-upstairs-markets-and-why-size-hides-1","v":"2B","s":"2b-5-blocks-upstairs-markets-and-why-size-hides","q":"State the block trader's dilemma and name three mechanisms that address it.","a":"<p><b>The dilemma:</b> to find the other side you must reveal that you want to trade, and revealing it moves the price against you before you have traded.</p><p><b>Mechanisms:</b> slicing into the continuous book (costs time and exposure to drift); upstairs negotiation through a broker (selective disclosure, but the information leaks to the broker); dark venues (no pre-trade signal, but uncertain fills and adverse selection); auctions (presence is uninformative, but no price control); and risk transfer to a dealer (certainty, at the price of their inventory risk).</p>"},{"i":"2b-6-manipulation-and-the-signatures-it-leaves-1","v":"2B","s":"2b-6-manipulation-and-the-signatures-it-leaves","q":"Why is order-book imbalance a dangerous signal input, and what is the fix?","a":"<p>Because posting and cancelling displayed size is <b>nearly free</b> while trading is not. A signal built on displayed size is trading against people who can manufacture its input at no cost — which is what spoofing is, and which reverses the sign of what the signal learned.</p><p><b>Fix:</b> build on <i>executed</i> flow, or weight imbalance by how long the size has rested. Both make the manipulation expensive to run against you. The general rule: prefer inputs that cost money to fabricate.</p>"},{"i":"2b-7-fragmentation-internalisation-and-the-order-you-did-not-route-1","v":"2B","s":"2b-7-fragmentation-internalisation-and-the-order-you-did-not-route","q":"Why is retail marketable flow attractive to a wholesaler, and what does the arrangement cost the market?","a":"<p><b>Attractive because it is uninformed.</b> Its adverse-selection cost (2B.3) is low, so it can be filled at or inside the displayed quote and still be profitable.</p><p><b>Cost:</b> the order never interacts with the lit book, so it does not contribute to public price discovery — while the improvement it receives is measured against a quote that exists because other participants are posting there. Good individually, arguably corrosive collectively; the policy argument is genuine rather than settled.</p>"},{"i":"2b-7-fragmentation-internalisation-and-the-order-you-did-not-route-2","v":"2B","s":"2b-7-fragmentation-internalisation-and-the-order-you-did-not-route","q":"What does internalising retail flow do to the orders that remain on the public book?","a":"<p>It removes the <b>uninformed</b> flow. Retail orders are, on average, the safest to trade against, which is precisely why a market maker will pay a broker to route them.</p><p>What is left on the public book is therefore a more informed — more <i>toxic</i> — mixture, so quoted spreads there must widen to cover the higher adverse selection. The retail order gets a better price; the public book gets a worse one.</p>"},{"i":"2b-8-halts-limits-and-what-happens-when-the-mechanism-stops-1","v":"2B","s":"2b-8-halts-limits-and-what-happens-when-the-mechanism-stops","q":"What happens to a market-neutral position when one leg is halted?","a":"<p>It becomes <b>outright</b> in the live leg, with no ability to adjust and no observable basis — there is no price for the halted leg, only a last print. The reopening auction can then print far from where it last traded.</p><p>No volatility-based risk model captures this, because the risk is the <i>absence of a price</i> rather than the size of a move. A stop order in the halted name is worthless for the same reason: it triggers on the reopening print, which is the gap it was meant to guard against.</p>"},{"i":"5a-1-portfolio-sorts-the-workhorse-1","v":"5A","s":"5a-1-portfolio-sorts-the-workhorse","q":"What is a portfolio sort estimating, and what is the price of that estimator?","a":"<p>It is a <b>non-parametric conditional mean</b>: E[return | characteristic in this bucket], with no assumption of linearity or monotonicity. That is why it can reveal a relationship living only in the extreme decile, or one that reverses in the middle.</p><p>The price is that it conditions on one variable at a time. If the characteristic is correlated with another return predictor — size, most often — a univariate sort cannot say which of them is responsible.</p>"},{"i":"5a-1-portfolio-sorts-the-workhorse-2","v":"5A","s":"5a-1-portfolio-sorts-the-workhorse","q":"List the five decisions a decile sort hides, in the order you make them.","a":"<p><b>1. Universe</b> — exchange, price floor, market-cap floor, exclusions. <b>2. Ranking</b> — which lag, which accounting date, how missing values are handled. <b>3. Cut points</b> — deciles or quintiles, and whose distribution defines them. <b>4. Weighting</b> — equal or value, the single most consequential choice. <b>5. Holding and rebalance</b> — frequency, overlap, and the formation gap.</p><p>Every published spread is conditional on all five, and most disagreements between replications trace to steps 3 and 4.</p>"},{"i":"5a-2-breakpoints-and-weighting-1","v":"5A","s":"5a-2-breakpoints-and-weighting","q":"Equal-weight and value-weight versions of a sort disagree sharply. What have you learned?","a":"<p>That the effect is <b>concentrated at one end of the size distribution</b> — almost always the small end. That disagreement is a finding in itself, and more informative than either number alone.</p><p>Equal weighting also embeds a monthly rebalance that buys losers and sells winners, so part of the gap is a short-horizon reversal premium in illiquid names rather than the characteristic being tested.</p>"},{"i":"5a-3-bivariate-sorts-independent-and-dependent-1","v":"5A","s":"5a-3-bivariate-sorts-independent-and-dependent","q":"When should a double sort be dependent rather than independent, and what does the order encode?","a":"<p>Sort <b>dependently when the two variables are correlated</b>. Independent cuts then leave corner cells nearly empty, and those thin cells dominate the spread's variance.</p><p>In a dependent sort the <b>first variable is the one being controlled for</b>: you cut on it, then rank on the characteristic within each of its buckets. Every cell holds the same number of names, and each spread is measured among stocks matched on the control.</p>"},{"i":"5a-4-fama-macbeth-the-two-pass-regression-1","v":"5A","s":"5a-4-fama-macbeth-the-two-pass-regression","q":"What does each pass of a Fama–MacBeth regression do, and what problem does the split solve?","a":"<p><b>Pass one:</b> for every period separately, regress the cross-section of returns on lagged characteristics. This yields <i>T</i> slope estimates per characteristic — each one the return to a portfolio with unit exposure to that characteristic and zero to the others.</p><p><b>Pass two:</b> average each slope series over time and <i>t</i>-test it against zero.</p><p>The split solves <b>cross-sectional correlation</b>: returns in the same month move together, which ruins pooled standard errors. That dependence is absorbed inside each period's regression, leaving inference to be done on <i>T</i> numbers.</p>"},{"i":"5a-4-fama-macbeth-the-two-pass-regression-2","v":"5A","s":"5a-4-fama-macbeth-the-two-pass-regression","q":"What should you look at in a Fama–MacBeth result besides the mean slope?","a":"<p>The <b>slope series itself</b>. Pass one produces one estimate per period, and that time series is the strategy's actual return stream.</p><p>A premium that arrives as a steady drizzle and one whose average comes from four extraordinary months can carry the same <i>t</i>-statistic. The mean gets published; the series tells you whether you could have held it.</p>"},{"i":"5a-5-standard-errors-that-survive-a-panel-1","v":"5A","s":"5a-5-standard-errors-that-survive-a-panel","q":"Newey–West corrects for what, and what is the standard abuse of it?","a":"<p>It is a <b>heteroskedasticity- and autocorrelation-consistent</b> estimator: it builds the long-run variance from weighted autocovariances out to lag <i>L</i>, using declining Bartlett weights so the result stays positive.</p><p>The abuse is <b>choosing <i>L</i> after seeing the answer</b> — trying several and reporting the lag that keeps <i>t</i> above two. Fix <i>L</i> in advance from sample length or from the known overlap in the data; where overlapping windows cause the autocorrelation, the overlap is the honest lower bound.</p>"},{"i":"5a-5-standard-errors-that-survive-a-panel-2","v":"5A","s":"5a-5-standard-errors-that-survive-a-panel","q":"Why do clustered standard errors mislead when clusters are few, and what is 'few'?","a":"<p>The cluster-robust variance estimator is consistent in the <b>number of clusters</b>, not the number of observations. With too few it is biased <b>downward</b> — understating uncertainty, which is exactly the direction that manufactures significance.</p><p>Below roughly <b>forty clusters</b> the bias is material. That is a real constraint: clustering by year on twenty years of data is clustering on twenty.</p>"},{"i":"5a-6-outliers-winsorising-and-conventions-1","v":"5A","s":"5a-6-outliers-winsorising-and-conventions","q":"A cross-sectional slope is 0.31 after winsorising and 0.04 on raw data. What do you conclude?","a":"<p>That the result is <b>a report on a handful of extreme observations</b>, not on the cross-section. Squared-error loss lets one firm with near-zero book equity outweigh two thousand others.</p><p>The defensible practice is to fix the treatment <i>before</i> seeing the answer and to report the sensitivity across treatments. Stable across winsorising levels and rank transforms is a finding; a large gap between raw and treated is a description of the tail.</p>"},{"i":"5a-7-persistence-decay-and-turnover-1","v":"5A","s":"5a-7-persistence-decay-and-turnover","q":"What three measurements establish how fast a signal decays, and why is a decay curve alone insufficient?","a":"<p><b>1. Characteristic persistence</b> — autocorrelation of the characteristic at 1, 3, 6, 12, 24 months. <b>2. Return decay</b> — the spread plotted against prediction horizon. <b>3. Transition matrix</b> — the probability of moving from decile <i>i</i> to decile <i>j</i>, whose diagonal is what you keep.</p><p>The curve is insufficient because rebalancing frequency is set where <b>marginal alpha captured equals marginal cost</b>. Without a cost model you have only one side of that equation.</p>"},{"i":"5a-7-persistence-decay-and-turnover-2","v":"5A","s":"5a-7-persistence-decay-and-turnover","q":"What does a decay profile that turns negative after one month tell you?","a":"<p>That <b>short-horizon reversal is embedded in the sort</b>. The characteristic is picking up stocks that have moved, and the subsequent bounce is what the spread is capturing.</p><p>That is a liquidity-provision return rather than the effect you thought you were testing, and it is the hardest kind to keep after costs, because it requires trading exactly when everyone else wants to trade the same way.</p>"},{"i":"5a-8-the-anomaly-zoo-and-replication-1","v":"5A","s":"5a-8-the-anomaly-zoo-and-replication","q":"Why is a <i>t</i>-statistic of 2.0 an inadequate hurdle for a newly published anomaly?","a":"<p>Because 2.0 corresponds to a 5 per cent false-positive rate for a <b>single pre-specified test</b>, and the literature is the surviving tail of an enormous, largely invisible number of tests. Try a hundred characteristics and about five clear that bar by chance alone.</p><p>Correcting for multiple testing puts the practical minimum near <b><i>t</i> = 3.0</b>, and even that is generous, since the unreported search is unobservable.</p>"},{"i":"6a-1-bias-variance-and-what-a-model-is-for-1","v":"6A","s":"6a-1-bias-variance-and-what-a-model-is-for","q":"Write the bias–variance decomposition, and say why it favours simple models in finance.","a":"<p>E[(<i>y</i> − <i>f</i>&#770;)²] = Bias² + Variance + &sigma;²<sub>&epsilon;</sub>. Bias is the gap between the average fit and the truth; variance is how much the fit moves with the training sample; &sigma;²<sub>&epsilon;</sub> is irreducible noise in <i>y</i>.</p><p>Financial returns have a very large &sigma;²<sub>&epsilon;</sub> — a 5 per cent <i>R</i>² is a strong signal. When noise dominates, <b>variance is the binding cost and bias is comparatively cheap</b>, which is why regularised simple models beat flexible ones here and why intuitions from image or language problems transfer badly.</p>"},{"i":"6a-2-resampling-cross-validation-and-bootstrap-1","v":"6A","s":"6a-2-resampling-cross-validation-and-bootstrap","q":"Why must feature selection happen inside each cross-validation fold?","a":"<p>Because selecting features using the outcome on the full dataset lets information from the held-out fold into the model that is scored on it. The resulting test error is not an out-of-sample estimate at all — it is often spectacular and always meaningless.</p><p>The same rule covers every outcome-aware step: target encoding, imputation using the response, and scaling with statistics computed across the whole dataset. All of it belongs inside the fold.</p>"},{"i":"6a-2-resampling-cross-validation-and-bootstrap-2","v":"6A","s":"6a-2-resampling-cross-validation-and-bootstrap","q":"Why is five- or ten-fold cross-validation preferred to leave-one-out?","a":"<p>Because of the <b>bias–variance trade-off in the estimate itself</b>. LOOCV is nearly unbiased — each model is fitted on almost the whole dataset — but its <i>n</i> fitted models are nearly identical, so their errors are highly correlated and averaging them reduces variance very little.</p><p>Five or ten folds accept a small amount of bias in exchange for a large reduction in the variance of the estimate, and cost far less to compute.</p>"},{"i":"6a-3-ridge-lasso-and-elastic-net-1","v":"6A","s":"6a-3-ridge-lasso-and-elastic-net","q":"Why does lasso set coefficients to exactly zero while ridge does not?","a":"<p>Because of the shape of the constraint region. Ridge constrains the coefficient vector to a <b>sphere</b>; lasso constrains it to a <b>diamond</b> whose corners lie on the axes.</p><p>The solution is where the elliptical RSS contours first touch the region. A smooth sphere is almost surely touched away from any axis, so no coefficient is exactly zero. A diamond is frequently touched at a corner, and corners have zero coordinates. The geometry is the selection mechanism.</p>"},{"i":"6a-4-classification-and-its-metrics-1","v":"6A","s":"6a-4-classification-and-its-metrics","q":"What does AUC mean exactly, and when should a precision–recall curve replace it?","a":"<p>AUC is the probability that a randomly chosen positive case receives a <b>higher score than a randomly chosen negative case</b>. It measures ranking quality across every threshold: 0.5 is a coin, 1.0 is perfect.</p><p>Replace it with a precision–recall curve when the positive class is <b>rare</b>. The false positive rate has a huge true-negative count in its denominator, so it stays small and flatters the model; precision does not.</p>"},{"i":"6a-5-trees-bagging-random-forests-boosting-1","v":"6A","s":"6a-5-trees-bagging-random-forests-boosting","q":"Bagging and boosting each attack which error term, and what follows about overfitting?","a":"<p><b>Bagging attacks variance</b>: deep trees on bootstrap samples, averaged. Bias is unchanged, and adding trees cannot overfit — more trees only reduces Monte Carlo noise in the average.</p><p><b>Boosting attacks bias</b>: small trees fitted sequentially to the ensemble's residual, added with a learning rate. Each round adds capacity, so the round count <i>is</i> a tuning parameter and must be chosen on held-out data.</p>"},{"i":"6a-5-trees-bagging-random-forests-boosting-2","v":"6A","s":"6a-5-trees-bagging-random-forests-boosting","q":"Why does correlation between trees put a floor under the benefit of averaging?","a":"<p>Averaging <i>B</i> identically distributed variables with pairwise correlation &rho; gives variance <b>&rho;&sigma;² + (1 − &rho;)&sigma;²/<i>B</i></b>. As <i>B</i> grows the second term vanishes and the first does not.</p><p>So if one feature dominates and every bagged tree splits on it first, the trees are highly correlated and more trees buy almost nothing. Forcing each split to consider a random subset of features lowers &rho; and therefore lowers the floor — which is the entire idea of a random forest.</p>"},{"i":"6a-6-support-vector-machines-and-kernels-1","v":"6A","s":"6a-6-support-vector-machines-and-kernels","q":"What is the kernel trick, and why is it not specific to support vector machines?","a":"<p>The SVM optimisation touches the data only through <b>inner products</b>. Replacing each inner product with a kernel <i>K</i>(<i>x</i><sub>i</sub>, <i>x</i><sub>j</sub>) — a function equal to an inner product in some higher-dimensional space — fits a linear boundary in that space without ever computing the mapping. An RBF kernel corresponds to an infinite-dimensional space at ordinary cost.</p><p>Any method expressible purely in inner products admits the same substitution: kernel ridge regression, kernel PCA and Gaussian processes all use it.</p>"},{"i":"6a-7-unsupervised-learning-pca-and-clustering-1","v":"6A","s":"6a-7-unsupervised-learning-pca-and-clustering","q":"Name the three standard ways PCA misleads on financial data.","a":"<p><b>1. Scale dependence</b> — on unstandardised data the highest-variance series dominates PC1. Use the correlation matrix unless the variance differences are the point.</p><p><b>2. Variance is not relevance</b> — the direction explaining most variance need not predict the outcome; a low-variance component can carry the signal.</p><p><b>3. Components are not causes</b> — orthogonality is imposed by construction. Naming PC2 is storytelling unless it is stable out of sample, which beyond PC1 it usually is not.</p>"},{"i":"6a-7-unsupervised-learning-pca-and-clustering-2","v":"6A","s":"6a-7-unsupervised-learning-pca-and-clustering","q":"What do the first three principal components of a yield curve represent?","a":"<p><b>Level, slope and curvature</b> — and together they typically explain around 95 per cent of the variation in the curve.</p><p>This is the rare case where components are stable, interpretable and reproducible out of sample. Equity returns are the contrast: PC1 is the market, and beyond it the components are unstable and hard to name — which is why naming them is usually storytelling.</p>"},{"i":"6a-8-what-finance-breaks-1","v":"6A","s":"6a-8-what-finance-breaks","q":"Twenty years of daily data, six-month signal horizon. What is the effective sample size?","a":"<p>Roughly <b>forty independent observations</b>, not five thousand rows. Overlapping windows and serial dependence mean that what you actually observe is about forty non-overlapping realisations of the thing being predicted.</p><p>Every capacity decision — feature count, tree depth, boosting rounds — should be made against the effective sample size. Making that substitution prevents most machine-learning failures in finance before they occur.</p>"},{"i":"8b-1-futures-mechanics-margin-and-clearing-1","v":"8B","s":"8b-1-futures-mechanics-margin-and-clearing","q":"How does a clearing house change counterparty risk, and what does it not remove?","a":"<p>It <b>novates</b> the trade: one contract becomes two, buyer-to-CCP and CCP-to-seller, so you no longer face your original counterparty. Losses are absorbed by a waterfall — defaulter's margin, defaulter's default-fund contribution, the CCP's own skin in the game, then <b>surviving members' contributions</b> and assessment rights.</p><p>The last two steps mean clearing <b>mutualises</b> risk rather than eliminating it. Bilateral exposure becomes shared exposure to the CCP — smaller in normal conditions, and highly correlated across members in a crisis.</p>"},{"i":"8b-2-forward-pricing-carry-and-convenience-yield-1","v":"8B","s":"8b-2-forward-pricing-carry-and-convenience-yield","q":"Why does a long futures position lose money in contango even if spot is unchanged?","a":"<p>Because the roll sells the near contract and buys a more expensive far contract each time the position is carried forward. In an upward-sloping curve that is a repeated realised loss, independent of any move in spot.</p><p>In backwardation the same mechanic pays. Over multi-year horizons this roll term dominates the return of long commodity index positions, which is why index performance and headline spot performance can diverge enormously.</p>"},{"i":"8b-3-swaps-and-the-discounting-revolution-1","v":"8B","s":"8b-3-swaps-and-the-discounting-revolution","q":"Why are collateralised swaps discounted on OIS rather than on an interbank curve?","a":"<p>Because discounting must match <b>funding</b>. A trade collateralised daily in cash has its cash flows funded at the rate the collateral earns — the overnight rate — so the replication argument requires discounting at that rate.</p><p>Interbank term rates embed bank credit and funding risk that a collateralised trade does not carry. The result is <b>multi-curve</b> valuation: an OIS curve for discounting and separate projection curves for each floating index and tenor.</p>"},{"i":"8b-3-swaps-and-the-discounting-revolution-2","v":"8B","s":"8b-3-swaps-and-the-discounting-revolution","q":"Give the two equivalent readings of an interest rate swap.","a":"<p><b>Two bonds:</b> a payer swap is short a fixed-rate bond and long a floating-rate note, and its value is the difference between them.</p><p><b>A strip of forwards:</b> each payment date is a forward rate agreement, and the value is the sum of the discounted differences between the fixed rate and each forward rate.</p><p>The second reading is the one that generalises — it is how the par swap rate turns out to be a discount-factor-weighted average of the forwards.</p>"},{"i":"8b-4-binomial-trees-and-lattice-pricing-1","v":"8B","s":"8b-4-binomial-trees-and-lattice-pricing","q":"Write the risk-neutral probability in a one-step binomial tree, and say what is absent from it.","a":"<p><i>p</i> = (<i>e</i><sup><i>r</i>&Delta;<i>t</i></sup> − <i>d</i>) / (<i>u</i> − <i>d</i>).</p><p>Absent are the <b>real probability of an up move</b> and the <b>expected return on the underlying</b>. The hedging argument removed both: a portfolio of &Delta; shares against a short option pays the same in either state, so it must earn <i>r</i>. That is risk-neutral valuation made concrete in two lines.</p>"},{"i":"8b-4-binomial-trees-and-lattice-pricing-2","v":"8B","s":"8b-4-binomial-trees-and-lattice-pricing","q":"When should you reach for a lattice, a PDE, or Monte Carlo?","a":"<p><b>Closed form</b> where one exists and its assumptions hold — nothing beats it.</p><p><b>Lattice or finite difference</b> for early exercise and one or two factors: both solve backward from maturity, which is what allows an exercise decision at every node.</p><p><b>Monte Carlo</b> for path dependence and many factors, since its error falls as 1/&radic;<i>N</i> regardless of dimension. It runs forward, so early exercise needs a regression method such as Longstaff–Schwartz.</p>"},{"i":"8b-5-exotics-a-working-taxonomy-1","v":"8B","s":"8b-5-exotics-a-working-taxonomy","q":"Name the three structural sources of difficulty in exotic derivatives.","a":"<p><b>1. Payoff discontinuity</b> — digitals and barriers have unbounded delta and gamma near the discontinuity, so no continuous hedge exists; they are managed with spreads and an explicit tolerance.</p><p><b>2. Unobservable parameters</b> — correlation, forward volatility, volatility of volatility cannot be marked to a liquid instrument, so the model risk <i>is</i> the position.</p><p><b>3. Path dependence</b> — the payoff depends on the route, so current spot does not summarise the hedge and valuation generally needs simulation.</p>"},{"i":"8b-6-jumps-and-numerical-methods-1","v":"8B","s":"8b-6-jumps-and-numerical-methods","q":"What does adding jumps to a diffusion model break, and what follows for hedging?","a":"<p>It breaks <b>completeness</b>. Black–Scholes gets a unique price because continuous rebalancing replicates the option exactly; you cannot rebalance through a gap, so a range of prices is consistent with no arbitrage and the price depends on a preference for jump risk.</p><p>Practically, the delta hedge leaves <b>residual jump exposure</b> that must be sized and limited explicitly. Short gamma then loses a bounded amount to diffusion and an unbounded amount to a gap.</p>"},{"i":"8b-7-caps-floors-and-swaptions-1","v":"8B","s":"8b-7-caps-floors-and-swaptions","q":"How does a cap differ structurally from a swaption on the same period?","a":"<p>A cap is a <b>portfolio of independent options</b> — one caplet per reset, each a call on its own forward rate. A swaption is a <b>single option on a basket</b> of forward rates.</p><p>So the swaption is sensitive to the <b>correlation among forward rates</b> and the cap is not. The gap between cap and swaption implied volatilities on matching periods is therefore a direct read on that correlation.</p>"},{"i":"8b-7-caps-floors-and-swaptions-2","v":"8B","s":"8b-7-caps-floors-and-swaptions","q":"What is a volatility cube, and how does it differ from an equity volatility surface?","a":"<p>An equity surface has two axes: <b>strike and maturity</b>. A swaption cube has three: <b>option expiry, swap tenor, and strike</b>.</p><p>So a 1y × 10y swaption — a one-year option on a ten-year swap — is a completely different instrument from a 10y × 1y. Traders read the expiry-by-tenor grid at the money and the smile in the third dimension, which is where SABR earns its place.</p>"},{"i":"8b-8-term-structure-models-1","v":"8B","s":"8b-8-term-structure-models","q":"What separates equilibrium from no-arbitrage term structure models, and why does it matter?","a":"<p><b>Equilibrium</b> models (Vasicek, CIR) take constant parameters and <i>produce</i> a curve, which will not match the observed one. <b>No-arbitrage</b> models (Ho–Lee, Hull–White, HJM) take today's curve as an <i>input</i> and add a time-dependent drift to reproduce it exactly.</p><p>It matters because a model that misprices the underlying bonds cannot be trusted to price options on them. Exact fit to the initial curve is a minimum requirement for trading use.</p>"},{"i":"8b-9-xva-the-adjustments-that-make-a-price-real-1","v":"8B","s":"8b-9-xva-the-adjustments-that-make-a-price-real","q":"Why is CVA an option rather than a reserve, and what follows operationally?","a":"<p>Because the loss on a counterparty default is the <b>positive part</b> of the exposure at that moment. CVA is the discounted expectation of max(exposure, 0) weighted by default probability, times loss given default — and a maximum is a payoff.</p><p>So CVA has Greeks: delta to market factors and credit delta to the counterparty's spread. Banks therefore run <b>CVA desks that hedge it as a trading book</b> rather than holding it as a static reserve.</p>"},{"i":"8b-9-xva-the-adjustments-that-make-a-price-real-2","v":"8B","s":"8b-9-xva-the-adjustments-that-make-a-price-real","q":"Name the XVA family and what each member prices.","a":"<p><b>CVA</b> — expected loss from the counterparty defaulting while the trade is in your favour. <b>DVA</b> — the mirror gain from your own default. <b>FVA</b> — funding an uncollateralised position at your own spread rather than the risk-free rate. <b>MVA</b> — funding initial margin over the trade's life. <b>KVA</b> — holding regulatory capital against it. <b>ColVA</b> — the optionality in the collateral agreement.</p><p>Each one prices an assumption the textbook made for free and that costs real money to violate.</p>"},{"i":"8c-1-expiration-p-and-l-and-reading-a-position-1","v":"8C","s":"8c-1-expiration-p-and-l-and-reading-a-position","q":"How do you draw the expiry payoff of an arbitrary option position?","a":"<p>Every expiry payoff is <b>piecewise linear with a kink only at a strike</b>. Fix the slope far below every strike (long stock, plus short puts, minus long puts), fix the slope far above (long stock, plus long calls, minus short calls), and change the slope at each strike by <b>+1 per long call and short put, −1 per short call and long put</b>.</p><p>Then shift the line by the net premium. Maximum loss, maximum gain and the breakevens are read off the result.</p>"},{"i":"8c-1-expiration-p-and-l-and-reading-a-position-2","v":"8C","s":"8c-1-expiration-p-and-l-and-reading-a-position","q":"What single feature of an expiry diagram tells you the position is bounded?","a":"<p><b>Zero slope at both ends.</b> If the payoff flattens beyond the highest and lowest strike, the worst case is a number you can write down before trading.</p><p>A non-zero slope at either end means the position is <b>outright</b> beyond the last strike, and no Greek management changes that at expiry. Most option blow-ups are positions whose far slope was not zero.</p>"},{"i":"8c-2-put-call-parity-and-synthetics-1","v":"8C","s":"8c-2-put-call-parity-and-synthetics","q":"State put–call parity and give the six synthetics that follow from it.","a":"<p><b><i>C</i> − <i>P</i> = <i>S</i> − <i>Ke</i><sup>−<i>rT</i></sup></b> for European options, same strike and expiry. Subtract the present value of dividends from <i>S</i>; on futures options the right side is (<i>F</i> − <i>K</i>)<i>e</i><sup>−<i>rT</i></sup>.</p><p>Long stock = long call + short put. Short stock = short call + long put. Long call = long stock + long put. Short call = short stock + short put. Long put = short stock + long call. <b>Short put = long stock + short call</b> — the covered write is a short put wearing a disguise.</p>"},{"i":"8c-2-put-call-parity-and-synthetics-2","v":"8C","s":"8c-2-put-call-parity-and-synthetics","q":"A conversion has no market risk. What is it actually a bet on?","a":"<p>The <b>carry inputs</b>, and only those: the interest rate to expiry, the size and timing of dividends, the <b>borrow cost</b> on the stock leg, and on American options the risk of early assignment.</p><p>So an apparently mispriced conversion means one of those four is wrong in your model. Borrow cost is the usual culprit.</p>"},{"i":"8c-3-vertical-spreads-1","v":"8C","s":"8c-3-vertical-spreads","q":"A bull call spread and a bull put spread on the same strikes: how do they differ?","a":"<p>They do <b>not</b> differ in risk. By put–call parity their expiry payoffs are identical up to a constant, so they are the same bet — one taken as a debit, the other as a credit.</p><p>The choice is decided by <b>execution and carry</b>: which strike pair has the tighter market and more size, which version carries less early-assignment risk on American options, and whether the credit version ties up margin you would rather use elsewhere. 'Receiving premium' describes the cash flow, not the risk.</p>"},{"i":"8c-4-volatility-spreads-straddles-to-condors-1","v":"8C","s":"8c-4-volatility-spreads-straddles-to-condors","q":"What does a delta-hedged long straddle actually earn, and what does that imply about buying one?","a":"<p>Its P&amp;L over a rehedged interval is approximately <b>½&Gamma;<i>S</i>²(&sigma;²<sub>realised</sub> − &sigma;²<sub>implied</sub>)&Delta;<i>t</i></b>: you earn realised variance and pay implied variance.</p><p>So it is not a bet that the market moves. It is a bet that the market moves <b>more than the implied volatility already charges for</b>, and that you capture the gap by rehedging. Buying before an event everyone can see usually means buying an implied volatility that already contains it.</p>"},{"i":"8c-4-volatility-spreads-straddles-to-condors-2","v":"8C","s":"8c-4-volatility-spreads-straddles-to-condors","q":"Why do the wings of a butterfly cost most of what the short middle strikes bring in?","a":"<p>Because the wings are what convert an unbounded short-volatility position into a bounded one, and the market charges correctly for that tail.</p><p>A short straddle or strangle has non-zero far slopes — outright and unbounded in both directions. Selling naked because the wings 'look expensive' is removing the only part of the structure that protects you.</p>"},{"i":"8c-5-calendars-diagonals-and-forward-volatility-1","v":"8C","s":"8c-5-calendars-diagonals-and-forward-volatility","q":"What is a long calendar spread actually a bet on, and why is it hard to manage?","a":"<p>It sells the near expiry and buys the far one at the same strike, earning the <b>difference in decay</b> (theta scales roughly as 1/&radic;<i>T</i>) while being long <b>forward volatility</b> between the two expiries.</p><p>It is hard because it is <b>long vega and short gamma at once</b> — a sharp move helps the far leg's vega while the near leg's larger gamma loses faster — and because <b>the legs are not fungible</b>: an event between the expiries belongs to one leg, so a calendar over earnings is an earnings position.</p>"},{"i":"8c-6-ratio-spreads-and-the-risk-you-did-not-price-1","v":"8C","s":"8c-6-ratio-spreads-and-the-risk-you-did-not-price","q":"Why is a 'zero-cost' ratio spread not a free position?","a":"<p>Because a 1×2 call ratio has a <b>far slope of −1</b>: beyond the upper strike it is short one unit of the underlying, permanently and without a bound. The maximum shown profit sits exactly at the short strike, which is what makes the diagram look attractive.</p><p>Every zero-cost structure is a spread financed by selling something. The question is never what it cost but <b>what you sold to make the cost zero</b> — here, a tail. Size the position by the naked leg, not by the net premium.</p>"},{"i":"8c-7-choosing-a-structure-from-a-view-1","v":"8C","s":"8c-7-choosing-a-structure-from-a-view","q":"What four dimensions must a view specify before an option structure can be chosen?","a":"<p><b>Direction</b>, <b>magnitude</b> (relative to what implied already prices), <b>timing</b> (and any known event in the window), and a view on <b>implied volatility</b> itself.</p><p>A view with only direction is a stock view and belongs in stock. Options exist for views with two or more dimensions filled in — that is what they are for.</p>"},{"i":"8c-7-choosing-a-structure-from-a-view-2","v":"8C","s":"8c-7-choosing-a-structure-from-a-view","q":"Name three views that no option structure expresses well, and what each really is.","a":"<p><b>'It will go up eventually'</b> — options expire, so a view with no horizon cannot be bought; every structure imposes one and you pay for it repeatedly.</p><p><b>'It will not go down'</b> — this is a short put whatever it is called, and should be priced as one.</p><p><b>'Upside without risk'</b> — the premium <i>is</i> the risk, relocated. Any structure that appears to give free upside has an unbounded leg.</p>"},{"i":"8c-8-managing-a-position-adjustment-and-gamma-rent-1","v":"8C","s":"8c-8-managing-a-position-adjustment-and-gamma-rent","q":"What is gamma rent, and how should you read it?","a":"<p>A long-gamma position earns approximately <b>½&Gamma;<i>S</i>²&sigma;²<sub>realised</sub>&Delta;<i>t</i></b> from rehedging — buying low and selling high mechanically — and pays theta, which is priced from implied volatility. The net is the running charge for holding convexity.</p><p>Read it as a <b>lease</b>: you pay daily for the right to profit from movement, and the lease runs whether or not the movement arrives. Short gamma makes you the landlord — collecting daily, exposed to the day the building comes down.</p>"},{"i":"8c-8-managing-a-position-adjustment-and-gamma-rent-2","v":"8C","s":"8c-8-managing-a-position-adjustment-and-gamma-rent","q":"State the one rule that prevents the standard options blow-up sequence.","a":"<p><b>An adjustment may not increase the position's maximum loss.</b></p><p>The sequence it prevents: a short option goes against you; rather than take the loss you sell another option to finance rolling it out and away; the market continues; you repeat. Each step is locally rational, the position grows, and the loss stops being bounded by anything.</p><p>Write the maximum loss down before opening the trade, and check every proposed adjustment against it.</p>"},{"i":"8c-9-early-exercise-dividends-and-pin-risk-1","v":"8C","s":"8c-9-early-exercise-dividends-and-pin-risk","q":"When is early exercise of an American option rational?","a":"<p><b>A call on a non-dividend stock: never</b> — exercising discards time value and pays the strike early; sell it instead.</p><p><b>A call before an ex-dividend date:</b> when the dividend exceeds the remaining time value of the matching put.</p><p><b>A put:</b> when deep in the money and interest on the strike proceeds beats the remaining time value — rare at low rates, common at high ones.</p><p><b>Futures options:</b> either side can be worth exercising, since the strike is not paid and the deferral argument disappears.</p>"},{"i":"8c-9-early-exercise-dividends-and-pin-risk-2","v":"8C","s":"8c-9-early-exercise-dividends-and-pin-risk","q":"What is pin risk, and what is the remedy?","a":"<p>If the underlying settles exactly at your short strike you do not know whether you will be assigned. You learn after the close, and discover on Monday whether you are flat or holding a large position in a market you cannot yet trade.</p><p>A short at-the-money option carried into expiry is therefore an <b>unhedgeable overnight gap the size of the whole position</b>. The remedy is absolute: close short strikes near spot before expiry — buying back a nearly worthless option is the cheapest insurance in derivatives.</p>"},{"i":"10b-1-what-a-trade-costs-the-decomposition-1","v":"10B","s":"10b-1-what-a-trade-costs-the-decomposition","q":"Why is market impact always an estimate rather than a measurement?","a":"<p>Because impact is the difference between the price you got and <b>the price that would have obtained had you not traded</b> — and that second price does not exist. There is no counterfactual to observe.</p><p>So every impact figure in every TCA report is a model output, and the report is only as good as that model. This is why TCA is a modelling discipline rather than an accounting one, and why commissions (auditable), spread (measurable) and impact (estimated only) must be kept as separate lines.</p>"},{"i":"10b-1-what-a-trade-costs-the-decomposition-2","v":"10B","s":"10b-1-what-a-trade-costs-the-decomposition","q":"Why must any usable cost number be reported as a pair?","a":"<p>Because <b>impact falls as you trade slower and timing risk rises as you trade slower</b>. No schedule minimises both — that trade-off is the whole content of the efficient trading frontier.</p><p>A cost model reporting only expected impact will therefore always recommend trading slower, and keep recommending it past the point of absurdity. Report an expected cost <i>and</i> its dispersion.</p>"},{"i":"10b-2-implementation-shortfall-properly-defined-1","v":"10B","s":"10b-2-implementation-shortfall-properly-defined","q":"Write implementation shortfall for a partially filled buy, and name what each term does.","a":"<p>IS = &Sigma;<sub>j</sub><i>q</i><sub>j</sub>(<i>P</i><sub>j</sub> − <i>P</i><sub>d</sub>) + (<i>Q</i> − &Sigma;<i>q</i><sub>j</sub>)(<i>P</i><sub>end</sub> − <i>P</i><sub>d</sub>) + fees, all against the <b>decision price</b> <i>P</i><sub>d</sub>.</p><p>The first term is <b>execution cost</b> on what traded; the second is <b>opportunity cost</b> on what did not. Together they stop an algorithm from looking good by quietly abandoning hard orders, or looking bad by completing them.</p>"},{"i":"10b-2-implementation-shortfall-properly-defined-2","v":"10B","s":"10b-2-implementation-shortfall-properly-defined","q":"Which component of shortfall is most often unmeasured, and why does that matter?","a":"<p><b>Delay cost</b> — arrival price minus decision price, on the full intended quantity. Organisations measure trading cost because it is the trader's number; delay cost indicts the process instead.</p><p>It matters because in fast strategies the delay term routinely exceeds everything else combined, and it is the cheapest thing to fix: it is plumbing between signal and market, not a market cost.</p>"},{"i":"10b-3-benchmarks-and-how-each-one-is-gamed-1","v":"10B","s":"10b-3-benchmarks-and-how-each-one-is-gamed","q":"What is the self-reference problem with VWAP as an execution benchmark?","a":"<p>If your order is 20 per cent of the interval's volume, your own fills are 20 per cent of the VWAP you are judged against. Beating it becomes partly arithmetic rather than skill.</p><p>Worse, the incentive it creates is to <b>trade in proportion to volume regardless of price</b> — exactly the behaviour a trader holding information should not have. VWAP is reasonable for a small, unhurried, alpha-free order and poor for anything else.</p>"},{"i":"10b-3-benchmarks-and-how-each-one-is-gamed-2","v":"10B","s":"10b-3-benchmarks-and-how-each-one-is-gamed","q":"How do you defend a TCA programme against benchmark gaming?","a":"<p>Not with a cleverer benchmark — every benchmark is gameable. Use <b>two benchmarks with opposing incentives, reported together</b>, plus the completion rate.</p><p>Arrival price rewards speed and completion; participation-weighted price rewards patience. A desk cannot flatter both at once, so the pair reveals what either alone would hide.</p>"},{"i":"10b-4-building-an-impact-model-from-your-own-fills-1","v":"10B","s":"10b-4-building-an-impact-model-from-your-own-fills","q":"Give the canonical impact model form and the exponents it usually fits.","a":"<p>Cost (bp) = <i>a</i>&middot;&sigma;<sup><i>b</i></sup>&middot;(<i>Q</i>/<i>ADV</i>)<sup><i>c</i></sup>&middot;<i>f</i>(&rho;) + half-spread, with <b><i>c</i> near ½</b> (the square-root law) and <b><i>b</i> near 1</b>.</p><p>Fit it <b>in logs</b>, where it is linear in log&sigma; and log(<i>Q</i>/<i>ADV</i>), one row per parent order — child fills are not independent observations.</p>"},{"i":"10b-4-building-an-impact-model-from-your-own-fills-2","v":"10B","s":"10b-4-building-an-impact-model-from-your-own-fills","q":"What selection bias inflates a naive impact fit, and how do you correct it?","a":"<p>Your orders are not random: you trade larger when more confident, and confidence comes from information. So adverse moves after large orders are partly your <b>alpha</b>, which a naive regression attributes entirely to impact — producing coefficients that are too high.</p><p>Control for realised alpha over the horizon, and better, <b>fit on mechanically driven orders</b> — index rebalances, redemptions, scheduled rolls — which carry no information. That subset is small and is the cleanest data you have.</p>"},{"i":"10b-4-building-an-impact-model-from-your-own-fills-3","v":"10B","s":"10b-4-building-an-impact-model-from-your-own-fills","q":"How do you separate temporary from permanent impact in your own data?","a":"<p>After the order completes, <b>track the price for several multiples of the order's duration</b>. The part that reverts is <b>temporary</b> impact — what you paid for immediacy. The part that persists is <b>permanent</b> — information you gave away.</p><p>The ratio is the diagnosis: impact that is mostly permanent means the strategy is signalling, and the fix is execution design rather than simply trading slower.</p>"},{"i":"10b-5-pre-trade-estimates-and-the-cost-curve-1","v":"10B","s":"10b-5-pre-trade-estimates-and-the-cost-curve","q":"What does a pre-trade cost curve plot, and what does adding alpha decay do to it?","a":"<p>Expected cost against trading horizon: <b>expected impact falls</b> monotonically with horizon while <b>timing risk rises</b> as &sigma;&radic;<i>T</i>. Their risk-weighted sum has a minimum, which is the recommended horizon — and it moves with risk aversion, correctly.</p><p>Adding <b>alpha decay</b> shortens the recommendation sharply. For a signal that halves in a day, patience costs the alpha you were trading.</p>"},{"i":"10b-5-pre-trade-estimates-and-the-cost-curve-2","v":"10B","s":"10b-5-pre-trade-estimates-and-the-cost-curve","q":"Why must a pre-trade estimate be reported with an interval?","a":"<p>Because a point estimate converts a statistical statement into a promise. '23 basis points' invites an argument about a 31 bp outcome; '23 bp, 68% interval 12 to 38' invites the correct conclusion that nothing unusual happened.</p><p>The interval compounds three sources: the residual dispersion of the fit, the standard error on the fitted coefficients, and the uncertainty in the volatility and volume forecasts.</p>"},{"i":"10b-6-post-trade-attribution-1","v":"10B","s":"10b-6-post-trade-attribution","q":"What is the cost-adjusted z-score, and why is it the basis of post-trade attribution?","a":"<p><i>z</i> = (realised cost − predicted cost) ÷ predicted standard deviation, computed per order.</p><p>It puts orders of different sizes, names, days and urgencies onto <b>one comparable scale</b>. The mean of <i>z</i> across a group is the skill estimate; its standard error is 1/&radic;<i>n</i>, so 100 orders detect a bias of about 0.2 standard deviations and no less. Comparing raw basis points across different orders compares things that were never comparable.</p>"},{"i":"10b-6-post-trade-attribution-2","v":"10B","s":"10b-6-post-trade-attribution","q":"Why should individual orders be reviewed for process but never judged on outcome?","a":"<p>Because cost dispersion is large enough that a single order cannot distinguish good execution from bad. A desk with genuinely better execution needs hundreds of orders before the evidence is significant.</p><p>Reviewing single outcomes therefore manufactures confident conclusions from noise and rewards whoever was lucky. Review individual orders for <b>process</b> failures — a wrong venue, a badly set limit, an order left unworked — and judge <b>outcomes</b> only in aggregate.</p>"},{"i":"10b-7-costs-inside-portfolio-construction-1","v":"10B","s":"10b-7-costs-inside-portfolio-construction","q":"What three consequences follow from putting costs into the portfolio objective?","a":"<p>Maximising <i>w</i>&prime;&mu; − (&lambda;/2)<i>w</i>&prime;&Sigma;<i>w</i> − <i>c</i>(<i>w</i> − <i>w</i><sub>0</sub>) gives:</p><p><b>1. A no-trade region</b> — small deviations from optimal are not worth correcting, so the solution is a region rather than a point.</p><p><b>2. Path dependence</b> — the optimum depends on current holdings, not on forecasts alone.</p><p><b>3. Shrinking positions at size</b> — marginal cost rises with the fraction of ADV, so the optimiser stops short of the frictionless answer in illiquid names.</p>"},{"i":"10b-7-costs-inside-portfolio-construction-2","v":"10B","s":"10b-7-costs-inside-portfolio-construction","q":"Derive capacity from the cost curve, and say why the break-even point is the wrong target.","a":"<p>Gross alpha per unit of capital is roughly constant as you scale, while cost per unit rises as (size)<sup>½</sup> under the square-root law. Net alpha therefore <b>peaks and then falls</b>.</p><p><b>Capacity is the peak, not the zero.</b> Running at break-even means working for nothing. Capacity is also not a single number: it depends on turnover, the universe's liquidity, signal decay and the cost variance you accept.</p>"},{"i":"11b-1-the-pipeline-end-to-end-1","v":"11B","s":"11b-1-the-pipeline-end-to-end","q":"List the seven stages between a raw signal and a submitted order.","a":"<p><b>1. Raw forecast</b> in natural units → <b>2. Scaling</b> to a known expected absolute value → <b>3. Capping</b> at a fixed multiple → <b>4. Combination</b> across rules → <b>5. Volatility scaling</b> so one unit of forecast is one unit of risk in any instrument → <b>6. Portfolio scaling</b> with instrument weights, the diversification multiplier and the risk target → <b>7. Rounding and buffering</b>.</p><p>Keep them in separate functions: then a signal can change without changing risk, and a risk target can change without touching signals.</p>"},{"i":"11b-2-forecast-scaling-and-capping-1","v":"11B","s":"11b-2-forecast-scaling-and-capping","q":"How is a raw signal converted into a standard forecast, and why is pooling important?","a":"<p>Pick a convention — say an expected absolute value of 10 — and multiply by <b>scalar = 10 ÷ mean(|raw forecast|)</b>, estimated over a long history and <b>pooled across instruments</b>.</p><p>Pooling matters because a per-instrument scalar fits noise and lets a rule appear to work in one market only because its scalar was tuned there. The constant itself is arbitrary; what matters is that every rule shares it, so a forecast of 20 means the same conviction whichever rule produced it.</p>"},{"i":"11b-2-forecast-scaling-and-capping-2","v":"11B","s":"11b-2-forecast-scaling-and-capping","q":"Why does capping forecasts buy more than it costs?","a":"<p>Uncapped forecasts have fat tails and position size inherits them, so the system's largest positions come from the most extreme readings — precisely the ones most likely to be data errors, regime breaks, or the moment before a signal stops working.</p><p>Capping at about twice the average bounds the maximum position, makes the system robust to bad data, and lowers turnover, at the cost of giving up rare large positions whose forecast accuracy is usually no better than average.</p>"},{"i":"11b-3-combining-rules-1","v":"11B","s":"11b-3-combining-rules","q":"Why is mean–variance optimisation the wrong tool for combining trading rules?","a":"<p>Because rules are <b>highly correlated</b> — two crossovers with adjacent lookbacks can exceed 0.9. Optimising over highly correlated assets with estimated means gives enormous, unstable long–short weights in which estimation error dominates the signal.</p><p>The result backtests beautifully and behaves erratically live. Judge any weighting scheme on the <b>stability of its weights</b> rather than on the fitted combination's Sharpe ratio.</p>"},{"i":"11b-3-combining-rules-2","v":"11B","s":"11b-3-combining-rules","q":"Why must a combined forecast be rescaled, and what does skipping it cause?","a":"<p>Averaging correlated forecasts <b>shrinks</b> them: the average of two rules that agree half the time has a smaller expected absolute value than either alone. The convention is therefore broken by the combination step.</p><p>Restore it with a forecast diversification multiplier computed from the rules' correlation matrix. Skipping this silently lowers the whole system's risk — which is why so many systems run well below their intended target.</p>"},{"i":"11b-4-the-diversification-multiplier-1","v":"11B","s":"11b-4-the-diversification-multiplier","q":"Give the diversification multiplier formula and the equal-correlation simplification.","a":"<p><b>DM = 1 ÷ &radic;(<i>w</i>&prime;&rho;<i>w</i>)</b>, where <i>w</i> are the sub-portfolio weights and &rho; their correlation matrix.</p><p>For <i>N</i> equally weighted positions all correlated at &rho;: <b>DM = 1 ÷ &radic;(&rho; + (1 − &rho;)/<i>N</i>)</b> — equal to 1 at &rho; = 1, &radic;<i>N</i> at &rho; = 0, and approaching 1/&radic;&rho; as <i>N</i> grows.</p>"},{"i":"11b-4-the-diversification-multiplier-2","v":"11B","s":"11b-4-the-diversification-multiplier","q":"Why does diversification saturate, and what does that imply about adding instruments?","a":"<p>Because DM approaches <b>1/&radic;&rho;</b> as <i>N</i> grows. At &rho; = 0.3, going from ten instruments to thirty moves the multiplier only from about 1.68 to 1.78; going from two to five moves it from 1.24 to 1.56.</p><p>So the marginal value of the twentieth instrument is nearly zero while its marginal cost in data, monitoring and execution is not. More instruments is not always better.</p>"},{"i":"11b-4-the-diversification-multiplier-3","v":"11B","s":"11b-4-the-diversification-multiplier","q":"Name the two opposite errors involving the diversification multiplier.","a":"<p><b>Omitting it</b> leaves the book under target — a system aiming at 20 per cent volatility with ten instruments at &rho; = 0.3 realises about 12 per cent, and looks like a poor strategy when it is merely a small one.</p><p><b>Applying it with a calm-period correlation</b> is worse: correlations rise when markets fall, so the multiplier over-leverages precisely when it should not. Cap it, estimate &rho; over a long window, and stress it upward before applying.</p>"},{"i":"11b-5-volatility-targeting-at-portfolio-level-1","v":"11B","s":"11b-5-volatility-targeting-at-portfolio-level","q":"Write the volatility-targeted position formula and name what each term decides.","a":"<p><i>N</i><sub>i</sub> = (forecast<sub>i</sub> ÷ convention) × (<i>C</i> × &tau; × <i>w</i><sub>i</sub> × DM) ÷ (&sigma;<sub>i</sub> × value per point<sub>i</sub>).</p><p><b>Forecast</b> is conviction, <b>C</b> capital, <b>&tau;</b> the risk target, <b>w</b> the instrument weight, <b>DM</b> the diversification multiplier, <b>&sigma;</b> the forecast volatility, and value per point the contract's arithmetic. Each is a decision owned by a different stage of the pipeline.</p>"},{"i":"11b-5-volatility-targeting-at-portfolio-level-2","v":"11B","s":"11b-5-volatility-targeting-at-portfolio-level","q":"Where does volatility targeting hurt rather than help?","a":"<p><b>Mean reversion strategies</b> — volatility and opportunity often rise together, so the mechanism shrinks positions exactly when the edge is largest.</p><p><b>Sharp reversals after a spike</b> — you de-risk at the bottom and re-risk on the way back, monetising the whipsaw.</p><p><b>Gaps</b> — a jump happens before any estimator can respond, so targeting offers no protection against the risk people most often credit it with.</p>"},{"i":"11b-6-buffering-rounding-and-minimum-size-1","v":"11B","s":"11b-6-buffering-rounding-and-minimum-size","q":"How is a no-trade buffer implemented, and what is the detail that makes it work?","a":"<p>Define a band of width <i>b</i> — commonly 10 per cent of the average absolute position — around the optimal position <i>N</i>*. Inside the band, do nothing. Outside it, <b>trade to the nearest edge of the band, not to the centre</b>.</p><p>Trading to the edge is the detail that matters: correcting all the way to the centre makes every excursion a full-size trade and most of the turnover reduction disappears. A 10 per cent buffer typically cuts turnover to about a third for a small loss of tracking.</p>"},{"i":"11b-6-buffering-rounding-and-minimum-size-2","v":"11B","s":"11b-6-buffering-rounding-and-minimum-size","q":"What test decides whether an instrument belongs in a systematic book at all?","a":"<p><b>At your capital and risk target, is the average absolute position at least about four contracts?</b></p><p>Below that, rounding dominates: an optimal position of 0.4 contracts rounds to zero (no contribution) or to one (2.5× the intended risk). The instrument then adds noise rather than diversification. Since diversification saturates anyway, dropping such instruments improves a small account.</p>"},{"i":"11b-6-buffering-rounding-and-minimum-size-3","v":"11B","s":"11b-6-buffering-rounding-and-minimum-size","q":"Why must buffering come before rounding, and not after?","a":"<p>Because rounding noise pushes the position across the band. If you round first and then buffer, the integer jitter repeatedly triggers trades and re-introduces exactly the turnover the buffer was meant to remove.</p><p>Correct order: continuous optimal → buffer against the current position in continuous units → round to whole contracts → apply hard limits → net against working orders.</p>"},{"i":"12b-1-hazard-rates-and-survival-curves-1","v":"12B","s":"12b-1-hazard-rates-and-survival-curves","q":"Give the approximation linking credit spread, recovery and hazard rate, and state its use.","a":"<p><b>&lambda; &asymp; <i>s</i> / (1 − <i>R</i>)</b> — hazard rate is roughly the spread divided by loss given default. A 300 bp spread with 40 per cent recovery implies about a 5 per cent annual hazard.</p><p>It is the quick sanity check on any quoted spread, and it makes the spread–recovery identification problem visible: only the ratio is pinned down by a single spread, so recovery must be assumed rather than inferred.</p>"},{"i":"12b-1-hazard-rates-and-survival-curves-2","v":"12B","s":"12b-1-hazard-rates-and-survival-curves","q":"Contrast structural and reduced-form credit models, and say what each is used for.","a":"<p><b>Structural (Merton):</b> default is assets falling below liabilities, so equity is a call on the firm. It has economic content and links equity to credit — but it predicts near-zero short-maturity spreads, which is empirically false.</p><p><b>Reduced-form (intensity):</b> default is the first jump of a point process with intensity &lambda;. No economic story, but it fits observed spreads exactly and is tractable.</p><p>Structural for ratings-style analysis and distance to default; reduced-form for pricing and hedging traded credit.</p>"},{"i":"12b-2-credit-default-swaps-and-bootstrapping-1","v":"12B","s":"12b-2-credit-default-swaps-and-bootstrapping","q":"Describe the CDS bootstrap, and name the assumption every hazard curve depends on.","a":"<p>Set the premium leg equal to the protection leg at each quoted maturity and solve sequentially for a <b>piecewise-constant hazard rate</b>: the 1y spread gives &lambda;<sub>1</sub>; holding that fixed, the 3y spread gives &lambda;<sub>1–3</sub>, and so on — the same recursion as a yield curve bootstrap, with survival probabilities in place of discount factors.</p><p>The assumption is <b>recovery</b>. Because &lambda; &asymp; <i>s</i>/(1 − <i>R</i>), one spread identifies only the ratio, so <i>R</i> is fixed by convention (often 40 per cent) and &lambda; solved for. Two desks with different conventions report different default probabilities from identical data.</p>"},{"i":"12b-3-indices-tranches-and-correlation-1","v":"12B","s":"12b-3-indices-tranches-and-correlation","q":"Why is a senior tranche a bet on correlation rather than on default rates?","a":"<p>Because it only takes losses after a large fraction of the pool has already defaulted. That scenario requires defaults to arrive <b>together</b>, so a senior tranche's losses are systemic by construction.</p><p>Higher correlation fattens the joint-default tail and is exactly what hurts it, while the pool's average default rate can move considerably without touching it at all. Tranching redistributes risk and changes its character; it never removes it.</p>"},{"i":"12b-4-securitisation-and-the-machinery-of-2007-1","v":"12B","s":"12b-4-securitisation-and-the-machinery-of-2007","q":"Why did pooling and re-tranching mortgage exposures fail to diversify risk?","a":"<p>Because every loan in the pool depended on <b>one national factor</b> — house prices. Pooling correlated exposures does not reduce risk; it converts idiosyncratic risk into pure factor risk.</p><p>A senior claim on such a pool therefore fails in exactly one scenario, and that scenario is the only one that matters. The general test: ask what single factor, moved far enough, would make every component fail at once. If it exists and is unmodelled, the diversification is decorative.</p>"},{"i":"12b-4-securitisation-and-the-machinery-of-2007-2","v":"12B","s":"12b-4-securitisation-and-the-machinery-of-2007","q":"What single question tests any diversified structure?","a":"<p><b>What one factor, moved far enough, would make every component fail at once?</b></p><p>If such a factor exists and is not modelled, the diversification is decorative. Pooling exposures that all depend on one national factor does not reduce risk — it <b>converts idiosyncratic risk into pure factor risk</b>, and a senior claim on that pool is a short position in the factor's tail wearing the costume of a diversified investment.</p>"},{"i":"12b-5-counterparty-exposure-and-wrong-way-risk-1","v":"12B","s":"12b-5-counterparty-exposure-and-wrong-way-risk","q":"Define wrong-way risk and give one specific and one general example.","a":"<p>Wrong-way risk is <b>positive dependence between exposure and counterparty default probability</b>: what you are owed grows exactly as the ability to pay it shrinks.</p><p><b>Specific:</b> buying credit protection on a firm from a counterparty economically tied to it, or taking collateral in the counterparty's own securities. <b>General:</b> an oil producer hedging with a bank whose loan book is concentrated in energy.</p><p>Standard CVA assumes independence, so wrong-way risk can multiply the true adjustment several times.</p>"},{"i":"12b-5-counterparty-exposure-and-wrong-way-risk-2","v":"12B","s":"12b-5-counterparty-exposure-and-wrong-way-risk","q":"Why are ratings downgrade triggers individually prudent and collectively dangerous?","a":"<p>Each clause looks like sensible protection: more collateral if the counterparty weakens.</p><p>Aggregated across a firm's contracts they become a <b>simultaneous, mechanical, unfundable cash call</b> at the exact moment funding disappears. This mechanism converted solvency concerns into immediate liquidity failures at more than one institution in 2008, and it is invisible in any contract-by-contract review.</p>"},{"i":"12b-6-blow-ups-and-what-each-one-proves-1","v":"12B","s":"12b-6-blow-ups-and-what-each-one-proves","q":"Name the four mechanisms behind almost every documented derivatives blow-up.","a":"<p><b>1. Funding and liquidity, not valuation</b> — most failures are cash-flow failures on economically defensible positions. VaR does not measure this; a stressed cash-flow projection does.</p><p><b>2. Correlations that hold until they matter</b> — diversification measured in calm data is not diversification.</p><p><b>3. Position size relative to the market</b> — exit capacity binds, and is absent from the risk report unless deliberately added.</p><p><b>4. Controls that exist only on paper</b> — segregation of duties, independent marks, external confirmation and frozen model governance are cheap and lapse first.</p>"},{"i":"13b-1-expected-return-is-a-discount-rate-1","v":"13B","s":"13b-1-expected-return-is-a-discount-rate","q":"Why is a historical average return a biased estimate of expected return?","a":"<p>Because expected return <b>is</b> the discount rate: price high ⟺ discount rate low ⟺ expected return low. So past and future returns are mechanically linked with a negative sign, through the price.</p><p>A sample in which valuations rose shows high realised returns <i>because</i> expected returns were falling. Extrapolating that average forward double-counts a re-rating windfall that can only happen once.</p>"},{"i":"13b-1-expected-return-is-a-discount-rate-2","v":"13B","s":"13b-1-expected-return-is-a-discount-rate","q":"How can returns be unpredictable and expected returns vary at the same time?","a":"<p>They describe <b>different horizons</b>. At short horizons realised returns are dominated by news and are close to unforecastable. At long horizons the discount rate dominates, and valuation ratios explain a substantial share of the variation.</p><p>A small persistent difference in expected return compounds into a large difference over a decade while remaining invisible over a month.</p>"},{"i":"13b-2-the-equity-risk-premium-1","v":"13B","s":"13b-2-the-equity-risk-premium","q":"Give the building-block estimate of expected equity return, and name the honest assumption in it.","a":"<p>E[<i>r</i>] &asymp; <b>dividend yield + expected real dividend growth + expected inflation + expected change in valuation</b>; subtract the expected safe rate for the premium.</p><p>The honest assumption is that the <b>valuation-change term is zero</b> over long horizons — you cannot forecast a re-rating. Assuming otherwise is permitted only if stated and justified. The decomposition's value is that two people who disagree about the premium usually disagree about exactly one term.</p>"},{"i":"13b-2-the-equity-risk-premium-2","v":"13B","s":"13b-2-the-equity-risk-premium","q":"State the equity premium puzzle and three proposed resolutions.","a":"<p>The realised historical premium in developed markets — several per cent a year in real terms over a century — is roughly an order of magnitude larger than standard consumption-based models predict at plausible risk aversion.</p><p><b>Survivorship</b>: the markets we study are the ones that survived. <b>Rare disasters</b>: investors priced a catastrophe that mostly did not occur in sample. <b>Habit or long-run risk</b>: risk aversion rises in bad times, making equities far riskier than a simple model implies. Also <b>re-rating</b>: part of the realised premium was a one-off fall in the discount rate.</p>"},{"i":"13b-3-the-bond-risk-premium-1","v":"13B","s":"13b-3-the-bond-risk-premium","q":"Decompose a long yield, and say what curve steepness actually predicts.","a":"<p><b><i>y</i><sup>(<i>n</i>)</sup> = average expected future short rate + term premium.</b> Under the pure expectations hypothesis the premium is zero, so a steep curve would mean the market expects rates to rise.</p><p>Empirically it does not: a steep curve predicts <b>excess returns on long bonds</b> rather than subsequent rate rises. That is the classic rejection of the hypothesis, and it makes steepness a forward-looking measure of the bond premium.</p>"},{"i":"13b-3-the-bond-risk-premium-2","v":"13B","s":"13b-3-the-bond-risk-premium","q":"Why does the stock–bond correlation change the term premium, and why is its sign not fixed?","a":"<p>If bonds pay off when equities fall, they hedge bad times and need <b>less</b> compensation, so the term premium falls. If they fall together, bonds are risky in bad times and the premium rises.</p><p>The sign is regime-dependent: <b>inflation-driven</b> regimes give a positive stock–bond correlation, <b>growth-driven</b> regimes a negative one. That single sign changes the premium, the case for duration, and the risk of every balanced portfolio at once — and the assumption is usually implicit.</p>"},{"i":"13b-4-the-credit-risk-premium-1","v":"13B","s":"13b-4-the-credit-risk-premium","q":"Decompose a credit spread, and state the credit spread puzzle.","a":"<p>A spread pays for <b>expected default loss</b> (probability × loss given default), a <b>default risk premium</b> for the uncertainty and timing of those losses, an <b>illiquidity premium</b>, and in some jurisdictions a <b>tax</b> component.</p><p>The puzzle is that expected default loss has historically accounted for <b>well under half</b> of the average investment-grade spread. Spreads look far too wide for the defaults that actually occur.</p>"},{"i":"13b-4-the-credit-risk-premium-2","v":"13B","s":"13b-4-the-credit-risk-premium","q":"Why is the credit premium much larger than expected losses?","a":"<p><b>Defaults cluster</b> — they arrive together in recessions, when other assets are falling and risk appetite is lowest. Compensation for a correlated loss far exceeds that for an independent loss of the same expected size.</p><p><b>The payoff is asymmetric</b> — a small spread most of the time, a large loss occasionally, which demands a premium beyond the mean and flatters short-sample Sharpe ratios enormously. And <b>illiquidity is real</b>: corporate bonds can be untradeable exactly when you want to sell.</p>"},{"i":"13b-5-the-illiquidity-premium-1","v":"13B","s":"13b-5-the-illiquidity-premium","q":"Distinguish the two premia both called 'illiquidity', and say which is dangerous.","a":"<p><b>The level premium</b>: an asset permanently harder to trade should have a permanently higher expected return. Real, defensible, harvestable by genuinely long-term capital.</p><p><b>The liquidity risk premium</b>: an asset whose liquidity <i>disappears in bad times</i> pays more still, because it fails exactly when you need to sell. This is the dangerous one.</p><p>An asset can be permanently illiquid but reliably tradeable, or usually liquid and periodically untradeable. Only crisis behaviour tells them apart.</p>"},{"i":"13b-5-the-illiquidity-premium-2","v":"13B","s":"13b-5-the-illiquidity-premium","q":"What is volatility laundering, and what is the correction?","a":"<p>An asset marked quarterly by appraisal on stale comparables shows low measured volatility and low measured correlation with public markets. Neither is a property of the asset — both are properties of the marking process.</p><p>The consequences are inflated Sharpe ratios, understated correlations, and optimisers that over-allocate because they were handed exactly the flattering inputs. The correction is to <b>unsmooth</b> the series with an autoregressive adjustment, which typically raises measured volatility substantially.</p>"},{"i":"13b-6-the-volatility-risk-premium-1","v":"13B","s":"13b-6-the-volatility-risk-premium","q":"Why does the volatility risk premium exist?","a":"<p><b>Insurance demand</b> — investors are structurally long equities and want protection; whoever supplies it charges above fair value, as in any insurance market.</p><p><b>Bad-times exposure</b> — volatility rises exactly when equities fall and risk appetite drops, so short volatility must be paid for.</p><p><b>Negative skew</b> — small regular gains and rare large losses demand a premium over the mean, for the same reason credit does.</p>"},{"i":"13b-6-the-volatility-risk-premium-2","v":"13B","s":"13b-6-the-volatility-risk-premium","q":"Name the three ways a volatility-harvesting business fails.","a":"<p><b>Leverage</b> — the premium is small per unit of exposure, so scaling is tempting, and the scaled position's worst day scales with it.</p><p><b>Short-sample flattery</b> — a negatively skewed strategy shows a superb Sharpe until the tail arrives; a Sharpe computed over a period without a crisis is not evidence.</p><p><b>The correlated unwind</b> — everyone harvesting holds the same position and is forced out by the same move, which is why volatility spikes overshoot.</p>"},{"i":"13b-7-bad-times-the-framework-that-unifies-them-1","v":"13B","s":"13b-7-bad-times-the-framework-that-unifies-them","q":"State the principle that unifies every risk premium.","a":"<p><b>An asset earns a premium to the extent that it pays off badly in bad times</b> — not to the extent that it is volatile. Volatility arriving at harmless moments is not compensated; what matters is <i>when</i> losses occur relative to when the investor needs money.</p><p>Formally, it is the covariance of the payoff with the marginal utility of consumption. Every asset pricing model in the field is an argument about what 'bad times' means.</p>"},{"i":"13b-7-bad-times-the-framework-that-unifies-them-2","v":"13B","s":"13b-7-bad-times-the-framework-that-unifies-them","q":"Why is a portfolio of risk premia less diversified than its correlation matrix suggests?","a":"<p>Because if every premium is compensation for the same thing — losing money in bad times — then they share a common exposure that only shows up in bad times.</p><p>Measured correlations are <b>conditional on the good times that dominate the sample</b>; in the episodes that define the premia, they converge. This is why risk parity across premia disappoints in crises, and why a stress test using measured correlations is not a stress test.</p>"},{"i":"13b-7-bad-times-the-framework-that-unifies-them-3","v":"13B","s":"13b-7-bad-times-the-framework-that-unifies-them","q":"Give the four-question test for any claimed new risk premium.","a":"<p><b>1. When does it lose?</b> No describable scenario means you have not found the risk.</p><p><b>2. Does that scenario coincide with when investors need money?</b> If yes, it is a genuine risk premium — expect to be paid, and to suffer.</p><p><b>3. If not, why is it not arbitraged?</b> A premium paying in all states needs a constraint, a mandate, or a structural seller to explain it.</p><p><b>4. What is my exit in that scenario?</b> The premium is only yours if you survive its bad times.</p>"},{"i":"13b-8-time-varying-expected-returns-1","v":"13B","s":"13b-8-time-varying-expected-returns","q":"What do time-varying expected returns license, and what do they not?","a":"<p><b>Licensed:</b> planning — a forward estimate beats a historical average for expectations, liabilities and savings rates; <b>modest, slow tilts</b> small relative to the estimate's uncertainty; and mechanical <b>rebalancing</b>, which harvests part of the effect with no forecast at all.</p><p><b>Not licensed:</b> short-horizon market timing — the <i>R</i>² is near zero monthly; confidence in the regression; and leaving the market entirely, since even a correct low-expected-return signal usually means 'hold somewhat less', not 'hold none'.</p>"},{"i":"13b-8-time-varying-expected-returns-2","v":"13B","s":"13b-8-time-varying-expected-returns","q":"Name the three reasons long-horizon predictive regressions overstate their evidence.","a":"<p><b>Overlapping windows</b> — ten-year returns sampled monthly share 119 of 120 months, so the effective sample is a fraction of the nominal one.</p><p><b>Persistent regressor</b> — valuation ratios are near unit-root, giving biased coefficients and overstated <i>t</i>-statistics (Stambaugh bias).</p><p><b>Ex-post knowledge</b> — the historical average valuation is known only in hindsight; a real-time investor did not know what 'expensive' meant. Using expanding-window statistics shrinks the effect dramatically.</p>"}]
;
window.__NEWCARDS__=[
{"i":"x-fm-1","v":"—","s":"honest-counts","q":"This page prints 101 alphas, 106 problems, 479 cards and 227 glossary entries. What rule generated those particular numbers, and what happens at build time if a duplicate paragraph or a broken cross-reference appears?","a":"<p>Every number is a <b>count of distinct items</b> verified at build time — where a larger number would have been more impressive but false, the smaller true number is printed.</p><p>The <b>build fails</b> on any duplicate paragraph, duplicate code block, broken cross-reference or unrendered equation. The counts are an auditable property of the file, not a marketing claim.</p>"},
{"i":"x-fm-2","v":"—","s":"how-it-is-built","q":"Why is every equation rendered to SVG at build time rather than typeset in the browser, and what does that buy you as a reader?","a":"<p>No typesetting library, no network request, no layout shift — <b>the mathematics is present the moment the page paints</b>, and the whole document works offline as one self-contained file.</p><p>The same reasoning applies to build-time syntax highlighting, the pre-built search index, and inline SVG diagrams drawn from the text's own colour tokens: they are theme-aware, scale to any width, and carry screen-reader descriptions. There is not one raster image in the file.</p>"},
{"i":"x-fm-3","v":"—","s":"reading-paths","q":"You have never traded anything and want to start from nothing. Which reading path does the page prescribe, in order — and which single volume runs alongside <em>all</em> the paths?","a":"<p><b>0</b> (the runway, working its checklist) → <b>00</b> (how to study) → <b>0A</b> (mathematics) → <b>0B</b> (Python) → <b>26</b> (build one) → <b>18</b> (why it is not real).</p><p><b>Volume 00</b> runs alongside every path: ten minutes of review a day, throughout. The paths choose what you read; 00 decides whether any of it stays.</p>"},
{"i":"x-fm-4","v":"—","s":"the-reference-in-pictures","q":"What is the figure index for, and what is the time trade it offers against the prose?","a":"<p>Sixty-four diagrams, each carrying one idea and <b>stating its own conclusion</b>, ordered as the shortest complete route through the document — roughly <b>twenty minutes against about eleven hours</b> of prose.</p><p>Each links to the passage that develops it, so it doubles as a map: skim the pictures, then descend only where a conclusion surprises you.</p>"},
{"i":"x-fm-5","v":"—","s":"personalised","q":"Volumes 24, 25 and 25A are written for one named reader. What are those sections allowed to conclude, what are they forbidden to conclude, and what use are they to anyone else?","a":"<p>They choose <b>system design constraints</b> — which failure modes to engineer against, which strategies suit the temperament, how fast to pace the work. They <b>never predict returns</b>.</p><p>For a different reader they are a worked example of designing a process around known weaknesses rather than assuming they can be willed away.</p>"},
{"i":"x-0-19","v":"0","s":"0-19-where-to-go-next","q":"Why does the reference claim the first trade is not an achievement, and what does it change about how you learn?","a":"<p>It is <b>the point at which learning finally has consequences attached</b> — and therefore starts working.</p><p>Before it, every conclusion is optional. After it, your own results tell you where to go deep: the reference is arranged so you can descend exactly where the outcomes start hurting.</p>"},
{"i":"x-00-1","v":"00","s":"00-1-why-reading-this-will-not-work","q":"Re-reading a section feels like understanding. What is that feeling actually measuring, and what does the Roediger–Karpicke result show about acting on it?","a":"<p>It measures <b>processing fluency</b> — how <em>recently</em> you encountered the text, not whether you could produce it from memory.</p><p>In the canonical studies, re-readers predict they will do better and do worse: at a week's delay the tested group retains far more, while the re-read group's confidence stays high. <b>Your confidence and your retention move in opposite directions</b>, so confidence cannot be your signal for what to study.</p>"},
{"i":"x-00-2","v":"00","s":"00-2-the-five-mechanisms-that-do-work","q":"Name the five mechanisms that actually produce durable learning, and state what all five have in common as an experience.","a":"<p><b>Retrieval practice</b>, <b>spacing</b>, <b>interleaving</b>, <b>elaboration</b>, and <b>generation</b> (attempting before being told).</p><p>All five feel worse than the thing they replace. Difficulty during encoding is the mechanism, not a side-effect — which is why the strategies that feel most productive are the ones that work least.</p>"},
{"i":"x-00-3","v":"00","s":"00-3-how-this-reference-implements-each","q":"Where does each mechanism physically live in this document, and what is the one rule about the global queue versus the per-volume panel?","a":"<p>Retrieval → the card deck anchored to the section that teaches each item. Spacing → an SM-2 scheduler setting the next interval from recall quality. Interleaving → the <b>global queue shuffles across volumes</b>. Elaboration and generation → the exercises and the Forge.</p><p>The rule: <b>review from the global queue</b>; use the per-volume panel only when you have just read that volume and want a same-session check. The per-volume panel does not interleave, so it flatters you.</p>"},
{"i":"x-00-4","v":"00","s":"00-4-your-dashboard","q":"Of the numbers on the dashboard, which single one should drive a session — and where does all this data live?","a":"<p><b>Cards due</b> — the scheduler's estimate of what you are about to forget. That is the queue, and it is the only number that should decide what you do today.</p><p>&quot;Consolidated&quot; means an interval past 21 days, the conventional line between still-learning and retained. Everything is computed from your own history, stored <b>in this browser only</b>; nothing is transmitted, and Export writes a JSON file you can move to another machine.</p>"},
{"i":"x-00-5","v":"00","s":"00-5-a-session-template","q":"Give the ninety-minute session in order, with rough minutes — and justify why review comes before reading rather than after.","a":"<p>1. <b>Review due cards</b> from the global queue, 10–15 min. 2. <b>Read the new section once</b>, no notes, 15 min. 3. <b>Close it and reconstruct</b> the main result on a blank page, 15 min. 4. <b>Work the exercises / code it</b>, the bulk of the time. 5. Write the one-line summary and log what broke.</p><p>Review goes first because attention is freshest and because <b>skipping it is exactly how the schedule collapses</b> — a queue you postpone once becomes a queue you cannot face.</p>"},
{"i":"x-00-6","v":"00","s":"00-6-when-a-card-keeps-failing","q":"A card has been marked <em>Again</em> five times. Name the four diagnoses and the fix for each.","a":"<p><b>The card is too big</b> (the answer holds three ideas) → re-read the source section and split the card. <b>You never understood it</b> (cannot reconstruct even with the section open) → a prerequisite gap; follow the cross-reference back. <b>It is an isolated fact</b> with nothing to hang on → elaborate: connect it to something you already own. <b>It does not matter</b> → suspend it.</p><p>Repeating a failing card unchanged is the one response that never works — more repetitions do not fix a card that is the wrong shape.</p>"},
{"i":"x-0a-1","v":"0A","s":"0a-1-how-to-use-this-volume","q":"What is the specific failure mode that ends most self-directed mathematical projects, and what is the discipline that prevents it?","a":"<p><b>Reading forward when you do not understand</b> — on the theory that it will clarify later. It does not: the gap compounds silently until the material becomes unreadable and you conclude you cannot do mathematics.</p><p>The discipline: <b>read with a pen</b> and work the marked exercises. They are the mechanism that moves material from recognisable to usable — the difference between nodding along in an interview and answering.</p>"},
{"i":"x-0a-19a","v":"0A","s":"0a-19-estimation-likelihood-bias-and-standard-erro","q":"Write the MSE decomposition, and use it to explain why a deliberately <em>biased</em> estimator such as Ledoit–Wolf beats the unbiased sample covariance out of sample.","a":"<p>MSE = <b>bias² + variance</b>.</p><p>A little bias buys a large variance reduction whenever the variance term dominates — which it always does in high dimensions, where you have more parameters than data to support them. Shrinkage, ridge and James–Stein are all this trade. <b>Unbiasedness is a luxury, and in high dimensions usually a mistake.</b></p>"},
{"i":"x-0a-19b","v":"0A","s":"0a-19-estimation-likelihood-bias-and-standard-erro","q":"You have fitted a GARCH model by maximum likelihood. Where do the standard errors come from, and what does a Hessian that is not positive definite tell you?","a":"<p>From the <b>inverse Hessian of the negative log-likelihood at the optimum</b> — the observed Fisher information. Fisher information is the curvature at the peak: sharp means the data pin the parameter down, flat means they do not.</p><p>A Hessian that is not positive definite means the optimum is <b>not interior</b> and the standard errors are meaningless. That is information about your model, not a nuisance to suppress — report it rather than hiding it.</p>"},
{"i":"x-0a-24","v":"0A","s":"0a-24-self-test-are-you-ready-for-volume-1","q":"What is the pass mark on the Volume 0A gate, what does a score below ten mean, and what does it <em>not</em> mean?","a":"<p><b>Fifteen or more</b>: proceed. <b>Ten to fourteen</b>: revisit the specific sections you missed. <b>Below ten</b>: work the volume again.</p><p>Below ten means &quot;this volume needs a second pass&quot; and nothing more. Mathematical material does not go in on first reading for anyone; people who appear to absorb it instantly have almost always seen a version before. <b>The gate exists because it is possible to fail it</b> — and you tick a box only if you could produce the answer on a blank page.</p>"},
{"i":"x-0b-5","v":"0B","s":"0b-5-polars-and-when-the-switch-is-worth-it","q":"What are the two structural differences between Polars and pandas that produce the speedup, and roughly how large is it?","a":"<p>A <b>lazy query engine</b> — nothing executes until <code>.collect()</code>, so the optimiser sees the whole plan, pushes filters down and avoids materialising intermediates — and <b>no index</b>, which removes a large class of silent alignment bugs.</p><p>Typically <b>5–30×</b> faster on grouped operations over large panels. The switch is worth it when a research iteration is long enough that you stop running it.</p>"},
{"i":"x-0b-7","v":"0B","s":"0b-7-getting-data-in-files-apis-and-a-cache-that-s","q":"Rank CSV, Parquet, Arrow IPC and SQLite/DuckDB by what each is actually for — and say what the local cache is protecting you from.","a":"<p><b>Parquet</b> is the default for everything: typed, compressed, columnar. <b>CSV</b> is for interchange with humans only — untyped, slow, ambiguous dates. <b>Arrow IPC</b> is zero-copy between processes, not an archive format. <b>DuckDB</b> is the queryable local analytics store; SQLite is row-oriented and the wrong shape for this.</p><p>The cache — hash the request, store the response, never refetch — protects the <b>research loop</b>: it makes reruns free, makes results reproducible when the vendor changes history under you, and stops rate limits from ending a session.</p>"},
{"i":"x-0b-11","v":"0B","s":"0b-11-profiling-and-the-three-speedups-that-matter","q":"Name the speedups in the order you should attempt them, with rough gains — and state the argument for why the last one changes what you can do rather than merely saving time.","a":"<p>Measure first (<code>cProfile</code>, then <code>line_profiler</code>): intuition about numerical code is worse than random. Then: <b>vectorise a row loop</b> (50–200×), <b>fix an accidental object dtype</b> (10–100×), <b>cache a pure function</b> (unbounded), pandas→Polars/NumPy (5–30×), <b>numba</b> <code>@njit</code> last (10–100×, only for genuinely path-dependent loops such as a fill model), parallelise sweeps (≈ core count).</p><p>Cutting an iteration from twelve minutes to twenty seconds does not save eleven minutes — it <b>changes what the loop is for</b>, by removing the friction that was silently limiting your search.</p>"},
{"i":"x-1-1","v":"1","s":"1-1-filtered-probability-spaces-and-what-a-trading-s","q":"A probability space is bookkeeping. Which object carries the trading content, and what is a signal <em>formally</em>?","a":"<p>The <b>filtration</b> 𝓕<sub>t</sub> — the information available at time t, increasing in t. It is the formal statement of &quot;no lookahead&quot;.</p><p>A trading signal is a <b>predictable (or 𝓕<sub>t</sub>-adapted) process</b>: its value at t is a function of information available at t. Every backtest bug of the lookahead family is the same mistake — a position that is not adapted to the filtration you claimed to trade on.</p>"},
{"i":"x-1-4","v":"1","s":"1-4-the-it-integral-and-it-isometry","q":"Why is the Itô integral defined with the <em>left</em> endpoint of each interval, and what does that choice buy?","a":"<p>Because the left endpoint is what makes the integral a <b>martingale</b> — and it is the mathematical image of <b>placing your position before observing the move</b>.</p><p>Any other evaluation point (Stratonovich uses the midpoint) destroys the martingale property and quietly lets the integrand peek at the increment it is being paid on. Itô isometry then gives 𝔼[(∫θdW)²] = 𝔼[∫θ²dt] — the variance of a stochastic integral is the integral of the squared integrand.</p>"},
{"i":"x-1-8","v":"1","s":"1-8-feynman-kac-sdes-become-pdes","q":"State what Feynman–Kac establishes, and give the operational rule for choosing which side of the equivalence to compute on.","a":"<p>A discounted expectation under the risk-neutral measure, V(t,x)=𝔼<sup>Q</sup>[e<sup>−r(T−t)</sup>Φ(X<sub>T</sub>)|X<sub>t</sub>=x], <b>solves a parabolic PDE</b> — and substituting GBM coefficients gives Black–Scholes directly.</p><p>The equivalence runs both ways, so choose by shape: <b>Monte Carlo</b> when the dimension is high or the payoff is path-dependent; <b>finite differences</b> when the dimension is low and you need stable Greeks or an early-exercise boundary.</p>"},
{"i":"x-2-5","v":"2","s":"2-5-avellaneda-stoikov-market-making","q":"In Avellaneda–Stoikov, what is the reservation price and which way does it move when you are long? Separately, what sets the total spread?","a":"<p>The <b>inventory-adjusted price at which the maker is indifferent to holding</b>: r = s − qγσ²(T−t). Long inventory (q&gt;0) pushes it <b>down</b>, so both quotes shift down and you are more likely to be lifted out of the position than added to it.</p><p>The optimal total spread depends on γσ²(T−t) plus a term in (1/γ)ln(1+γ/k) from the order-arrival intensity — i.e. on <b>risk aversion, volatility, time remaining and how fast fills arrive</b>, not on your desired profit.</p>"},
{"i":"x-2-7","v":"2","s":"2-7-hawkes-processes-order-flow-clusters","q":"What empirical fact about order flow does a Poisson process get wrong, and what does the Hawkes branching ratio tell you when it approaches one?","a":"<p>Arrivals <b>cluster</b> — trades beget trades. A Hawkes process makes intensity self-exciting: λ(t)=μ+∑<sub>t<sub>i</sub>&lt;t</sub>α e<sup>−β(t−t<sub>i</sub>)</sup>, so each event lifts the arrival rate and the lift decays.</p><p>The <b>branching ratio n=α/β</b> is the expected number of events directly triggered by one event. n→1 means <b>near-critical</b>: almost all activity is endogenously generated by other activity rather than by news — the regime where liquidity evaporates and small orders produce outsized moves.</p>"},
{"i":"x-3-4","v":"3","s":"3-4-dynamic-hedge-ratios-with-the-kalman-filter","q":"Give three concrete defects of a rolling-OLS hedge ratio, and say what modelling β as a random walk fixes.","a":"<p>It <b>lags</b>; it <b>jumps</b> when an outlier rolls off the window; and the <b>window length is a free parameter you will overfit</b>.</p><p>Modelling β<sub>t</sub>=β<sub>t−1</sub>+η<sub>t</sub> with observation y<sub>t</sub>=β<sub>t</sub>x<sub>t</sub>+ε<sub>t</sub> and filtering gives a continuously updated estimate with an explicit uncertainty band, no window, and one interpretable tuning ratio — the <b>signal-to-noise ratio</b> Q/R, which sets how fast β is allowed to move.</p>"},
{"i":"x-4-2","v":"4","s":"4-2-arma-and-why-it-rarely-helps-for-returns","q":"State the stationarity and invertibility conditions for ARMA(p,q), and explain why ARMA is nevertheless close to useless on returns but useful on other series.","a":"<p>Stationarity: roots of φ(z)=0 <b>outside the unit circle</b>. Invertibility: the same of θ(z). Select with BIC (−2ℓ+k·lnT) rather than AIC — BIC is more conservative and you are looking for a parsimonious model.</p><p>Returns are close to <b>serially uncorrelated in the mean</b>, so there is almost nothing for ARMA to fit; the structure lives in the <b>second moment</b>, which is GARCH's job. ARMA earns its place on series that <em>are</em> autocorrelated — realised volatility, spreads, order-flow imbalance, basis.</p>"},
{"i":"x-4-7","v":"4","s":"4-7-vector-autoregressions-and-granger-causality","q":"Define Granger causality precisely, and give the two standard warnings about reading it as causation.","a":"<p>x <b>Granger-causes</b> y if lagged x improves the forecast of y beyond lagged y alone — an F-test on the joint significance of x's lags in a VAR(p).</p><p>Warnings: it is <b>predictive precedence, not causation</b> — a common driver that reaches x faster produces the same test result; and it is <b>sampling-frequency dependent</b>, so a relationship at daily frequency can vanish or reverse at five minutes. Add that with n series and p lags you are estimating n²p parameters, so the test overfits quickly.</p>"},
{"i":"x-17-1","v":"17","s":"17-1-system-topology","q":"Name the seven components of a production trading topology, and state the single design reason the risk gateway sits <em>outside</em> strategy code.","a":"<p><b>Market data handler</b> (normalises, sequences, gap-fills, owns book state) · <b>strategy processes</b> (one each, isolated) · <b>risk gateway</b> · <b>OMS</b> (owns order state — acks, rejects, partials, cancels, amends; the single source of truth for what is working) · <b>position/ledger service</b> · <b>monitoring</b> · <b>kill switch</b>.</p><p>The gateway is outside strategy code so that <b>a strategy bug cannot exceed the limits</b>. A limit enforced by the thing it is meant to constrain is not a limit.</p>"},
{"i":"x-20-3","v":"20","s":"20-3-it-s-lemma","q":"Sketch the proof of Itô's lemma in three steps, and name the term that a first-order Taylor expansion would have thrown away.","a":"<p>Taylor-expand f(t+dt, X+dX) to <b>second order</b>; substitute dX=μdt+σdW; apply the multiplication table dW²=dt, dt·dW=0, dt²=0.</p><p>The surviving extra term is <b>½σ²f<sub>xx</sub>dt</b> — the Itô correction. It exists because Brownian motion has non-vanishing quadratic variation, so (dX)² is of order dt, not dt². Everything distinctive about stochastic calculus is that one term.</p>"},
{"i":"x-20-4","v":"20","s":"20-4-solution-of-geometric-brownian-motion","q":"Solve dS=μS dt+σS dW, and say precisely which path the −½σ² belongs to.","a":"<p>Let Y=lnS. Itô gives dY=(μ−½σ²)dt+σdW, arithmetic Brownian motion, so Y<sub>t</sub>=Y<sub>0</sub>+(μ−½σ²)t+σW<sub>t</sub> and <b>S<sub>t</sub>=S<sub>0</sub>exp[(μ−½σ²)t+σW<sub>t</sub>]</b>.</p><p>Taking expectations recovers 𝔼[S<sub>t</sub>]=S<sub>0</sub>e<sup>μt</sup>. So the <b>−½σ² is a property of the median path, not the mean</b> — this is volatility drag, and it is why a volatile asset with positive expected return can still have a median that falls.</p>"},
{"i":"x-20-5","v":"20","s":"20-5-ornstein-uhlenbeck-solution-moments-half-life","q":"For dX=κ(θ−X)dt+σdW, write the conditional variance and the half-life, and say what the stationary variance implies about position sizing on a spread.","a":"<p>Var[X<sub>t</sub>|X<sub>0</sub>]=(σ²/2κ)(1−e<sup>−2κt</sup>), rising to a <b>stationary variance σ²/2κ</b>. Half-life = <b>ln2/κ</b>.</p><p>So a spread's natural scale is σ/√(2κ), and the half-life tells you the holding period the trade implies. Size against the stationary standard deviation, not against a recent range — and if the half-life is long relative to your patience or your financing cost, the trade is not viable however wide the spread looks.</p>"},
{"i":"x-20-6","v":"20","s":"20-6-black-scholes-by-the-hedging-argument","q":"Derive the Black–Scholes PDE by hedging in four moves, then name the two assumptions whose failure you actually feel in practice.","a":"<p>Hold one option, short Δ shares: Π=V−ΔS. Apply Itô to dΠ. Choose <b>Δ=V<sub>S</sub></b>, which cancels the dW terms exactly. A riskless portfolio must earn r, so dΠ=rΠdt — rearranging gives V<sub>t</sub>+rSV<sub>S</sub>+½σ²S²V<sub>SS</sub>−rV=0.</p><p>It breaks on <b>continuous, costless rebalancing</b>. In discrete time the cancellation is imperfect and leaves a residual proportional to Γ — precisely the gamma–theta P&amp;L. With transaction costs, continuous hedging costs infinity, which is why real hedging is discrete and <b>hedge error is a risk in its own right</b>.</p>"},
{"i":"x-20-7","v":"20","s":"20-7-put-call-parity","q":"State put–call parity and explain why it is described as model-free. What does a persistent violation actually indicate?","a":"<p>C−P = S<sub>0</sub>e<sup>−qT</sup> − Ke<sup>−rT</sup>. It follows from a <b>static replication</b> argument — the two portfolios have identical payoffs at expiry — so it needs no dynamics, no volatility and no distributional assumption. That is what model-free means.</p><p>A persistent apparent violation is almost never an arbitrage: it is a <b>wrong input</b> — the borrow cost, dividend assumption, exercise style, or a stale quote on one leg. Check those before believing the free money.</p>"},
{"i":"x-20-8","v":"20","s":"20-8-optional-stopping-and-gambler-s-ruin","q":"A symmetric walk from 0 with absorbing barriers at −a and +b: give both classical results, then state the trading consequence for drawdowns.","a":"<p>P(hit +b first) = <b>a/(a+b)</b>, from optional stopping on the martingale X<sub>t</sub>. Expected time to absorption = <b>ab</b>, from optional stopping on X<sub>t</sub>²−t.</p><p>Time to move a fixed distance grows as the <b>square</b> of that distance. A drawdown twice as deep takes roughly <b>four times as long</b> to recover — which is why time-under-water grows far faster than intuition suggests, and why depth limits bind long before they look like they should.</p>"},
{"i":"x-20-10","v":"20","s":"20-10-the-markowitz-solution","q":"Derive the Markowitz weights, then state the two distinct reasons the closed form misleads in practice.","a":"<p>Minimise ½w<sup>T</sup>Σw subject to w<sup>T</sup>μ=μ<sub>p</sub> and w<sup>T</sup>1=1. The Lagrangian's first-order condition Σw=λ<sub>1</sub>μ+λ<sub>2</sub>1 gives <b>w*=Σ<sup>−1</sup>(λ<sub>1</sub>μ+λ<sub>2</sub>1)</b>; substituting back yields a parabola in μ<sub>p</sub> — the efficient frontier.</p><p>(1) With <b>N&gt;T</b> the sample covariance is singular and Σ<sup>−1</sup> is numerically meaningless. (2) Even when invertible, Σ<sup>−1</sup> <b>amplifies the smallest eigenvalues, which are the noisiest</b> — so the optimiser puts its largest bets where it knows least.</p>"},
{"i":"x-20-12","v":"20","s":"20-12-standard-error-of-the-sharpe-ratio","q":"Give the i.i.d. standard error of an estimated Sharpe ratio, convert it into the rule of thumb about years, and say how skew and kurtosis change it.","a":"<p>Var(Ŝ)≈(1/T)(1+½S²) in the same units as S. Annualised, SE(Ŝ)≈<b>√((1+½S²)/years)</b> — so with a Sharpe near 1, the standard error is roughly <b>1/√(years)</b>.</p><p>Three years of data therefore gives ±0.58 at one standard error: a measured 1.4 and a measured 0.6 are not distinguishable. With <b>negative skew and excess kurtosis</b> the variance is larger still — Var(Ŝ)≈(1/T)(1+½S²−γ<sub>3</sub>S+¼(γ<sub>4</sub>−3)S²) — which is exactly the shape of most strategies that look best.</p>"},
{"i":"x-21-2","v":"21","s":"21-2-hierarchical-risk-parity-allocator","q":"In the HRP allocator, what do the three stages do, and which property of it makes it well defined when mean–variance is not?","a":"<p><b>Tree clustering</b> on the correlation distance √((1−ρ)/2); <b>quasi-diagonalisation</b>, reordering leaves so correlated assets sit adjacent and large covariances concentrate near the diagonal (no value is changed); <b>recursive bisection</b>, splitting weight between halves in inverse proportion to each half's inverse-variance-portfolio variance.</p><p>It <b>never inverts the covariance matrix</b>. So it is defined when N&gt;T, and it does not amplify the noisiest eigenvalues — which is why it is far more stable out of sample.</p>"},
{"i":"x-21-3","v":"21","s":"21-3-equal-risk-contribution-risk-parity-solver","q":"What equation does the risk-parity solver actually solve, and what is the silent bug the module warns about?","a":"<p>It finds w with <b>w<sub>i</sub>(Σw)<sub>i</sub> = b<sub>i</sub>(w<sup>T</sup>Σw)</b> for all i — each asset contributes its budgeted share of portfolio variance. Cyclical coordinate descent has a closed form per coordinate (a quadratic in w<sub>i</sub>) and converges monotonically for positive-definite Σ.</p><p>The bug: <b>normalising inside the loop</b>. Rescaling w each pass changes the fixed point and stalls the solver at ~10⁻² risk-contribution error instead of machine precision — with no error and no warning. Normalise <b>only at the end</b>.</p>"},
{"i":"x-21-4","v":"21","s":"21-4-constrained-portfolio-optimiser-projected-gradi","q":"Three constraints — dollar neutrality, a position cap and a gross cap — fight each other. Why does &quot;de-mean, then clip&quot; fail, and what fixes it?","a":"<p>Because each projection breaks the previous one: de-meaning breaks the position cap, clipping breaks dollar-neutrality, and rescaling for gross breaks nothing but does not restore either. A single pass returns weights that <b>silently violate w<sub>max</sub></b>.</p><p>All three sets are convex, so <b>alternating projection</b> converges to a point in the intersection — usually in three or four rounds. Separately, the L1 turnover penalty is non-smooth, so it is handled by a <b>proximal (soft-threshold) step toward w<sub>prev</sub></b> rather than by a gradient, which a plain quadratic program cannot do at all.</p>"},
{"i":"x-21-6","v":"21","s":"21-6-point-in-time-universe-builder","q":"What must the listings table contain for the universe builder to be correct, and why is membership held between rebalance dates rather than re-ranked daily?","a":"<p>Per-asset <b>first_date and last_date including assets that have since delisted</b>. A universe built only from currently-listed names <em>is</em> survivorship bias — the exact thing the function exists to prevent.</p><p>Ranking by liquidity only on rebalance dates and holding membership in between avoids <b>phantom turnover</b> from names crossing the rank threshold day to day. The one exception: a name that stops being eligible mid-period leaves <b>immediately</b>, not at the next rebalance.</p>"},
{"i":"x-21-8","v":"21","s":"21-8-performance-analytics","q":"The tearsheet deliberately reports numbers that make a strategy look worse. Name three of them and say what each predicts.","a":"<p><b>Longest time under water</b> — predicts whether you will still be running it, because depth is survivable and duration is what makes people quit. <b>Sharpe excluding the top ten days</b> — reveals a record that is really a handful of lucky prints. <b>Tail ratio</b> |q₉₅/q₀₅| — shows whether the return distribution is paying you for a short-tail exposure.</p><p>Add hit rate, profit factor, skew, kurtosis, VaR/CVaR at 95%, and turnover. The flattering numbers predict nothing; these predict whether the strategy is alive in a year.</p>"},
{"i":"x-21-10","v":"21","s":"21-10-position-reconciliation","q":"Why does the reconciler use <code>Decimal</code> rather than <code>float</code>, and why does it never auto-correct?","a":"<p>Because comparing binary floats for equality produces <b>phantom breaks of 10⁻¹³ shares</b>, which then trigger correcting trades — a real, expensive bug caused entirely by the representation.</p><p>It never auto-corrects because a break means <b>you do not know your position</b>, and acting on an unknown position is how a small discrepancy becomes a large one. It returns a report and a verdict of <code>HALT_AND_ALERT</code> for a human.</p>"},
{"i":"x-21-12","v":"21","s":"21-12-c-latency-histogram","q":"What three properties make the latency histogram safe to call inside a hot loop, and why does that matter more than its accuracy?","a":"<p><code>record()</code> is <b>allocation-free, branch-light and O(1)</b>: fixed buckets, logarithmic bucketing with 64 linear sub-buckets per power of two, giving ~1.5% relative resolution.</p><p>It matters because <b>a histogram that allocates perturbs the very thing it measures</b>. 1.5% resolution is far finer than any decision you will make from it, so the trade is entirely one-sided — and it is what lets you report percentiles rather than the mean, as 9.4 demands.</p>"},
{"i":"x-22-2","v":"22","s":"22-2-reference-implementation-of-the-operator-librar","q":"In the alpha operator library, which axis is cross-sectional and which is time-series — and what does <code>decay_linear</code> weight most heavily?","a":"<p>DataFrames are dates × assets. <b>Cross-sectional operators act along axis=1</b> (rank, scale, indneutralize); <b>time-series operators along axis=0</b> (delay, delta, ts_mean, stddev, ts_rank, ts_argmax). Getting this backwards is the single most common bug in reimplementations — and it fails silently, producing a plausible-looking signal.</p><p><code>decay_linear</code> puts the <b>largest weight on the most recent observation</b> (weights d, d−1, …, 1). <code>scale</code> normalises each row so ∑|x|=a, which is the dollar-neutral sizing step; <code>indneutralize</code> demeans within industry, equivalent to residualising on group dummies.</p>"},
{"i":"x-22-5","v":"22","s":"22-5-the-complete-catalogue","q":"The catalogue of 101 alphas is described as near-ideal study material and near-worst trading material. Justify both halves.","a":"<p><b>As study</b>: 101 worked examples of signal construction with enough variety to build real intuition about ranking, neutralisation and conditional logic — a complete, systematic corpus.</p><p><b>As trading material</b>: they are published, therefore crowded; they were fitted on a specific universe and era; most were never net of costs; and running them is the purest form of the multiple-testing problem — you are selecting the best of 101 on your data, which is exactly what Volume 18 says produces a Sharpe from nothing.</p>"},
{"i":"x-gl-1","v":"GL","s":"gl-1-every-term-alphabetically","q":"What is the glossary <em>for</em>, given that every term is also defined where it first appears? Name the two ways it is meant to be used.","a":"<p>Because the reference is read non-linearly and out of order: the glossary is the <b>fallback definition</b> for a term you meet before the volume that teaches it, and every entry names the volume that develops it.</p><p>Two uses: as a <b>lookup</b> while reading forward, and as a <b>self-test</b> — cover the definitions, work down the list, and any term you cannot state in plain words marks a section you have read but not learned.</p>"},
{"i":"x-24-1","v":"24","s":"24-1-your-profile","q":"Read as a system specification rather than a personality description: which two facet clusters in this profile drive the design of the blueprint, and in which direction?","a":"<p><b>High Neuroticism</b> (Anxiety 16, Immoderation 15, Anger 14, Depression 14) means the system must remove discretion at exactly the moments discretion is most tempting — hence broker-enforced limits, automatic de-risk, and a 24-hour delay on overrides.</p><p><b>High Orderliness (16) with lower Self-Efficacy (11)</b> means systematic, complete, checkable process suits the temperament, but confidence will not arrive from results alone — so progress must be measured by <b>process metrics</b>, weekly, rather than by P&amp;L. The Burnout Buffer of 44 is a <em>constraint</em>, not a trait: it caps hours, not ambition.</p>"},
{"i":"x-24-7","v":"24","s":"24-7-sustainability","q":"Why is a sustainability constraint a <em>design</em> input rather than a lifestyle preference, and what is the argument against &quot;push through it&quot;?","a":"<p>Because <b>a schedule you cannot sustain produces a system that stops being maintained</b>, and an unmaintained system fails in ways that cost far more than the hours saved. Energy here is a genuine constraint (Activity Level 9/20), not a matter of willingness.</p><p>The design consequences: fixed 8–12 hours a week, one market-facing session a day, a full week off each quarter. Pushing through converts a small, recoverable slowdown into an abandonment — and an abandoned book realises every accumulated cost and none of the compounding.</p>"},
{"i":"x-24-8","v":"24","s":"24-8-the-one-page-summary","q":"Recite the operating rules that concern <em>size and loss</em>, and say what all of them have in common structurally.","a":"<p><b>Quarter-Kelly, never more.</b> Position and loss limits enforced <b>at the broker, not in your own code</b>. Automatic de-risk at −8%, automatic halt at −15%, no discretion in either. Scaling into losers disabled at the system level. 24-hour mandatory delay on any limit increase, with a written reason. Prefer bounded-loss structures; trading capital separate from income, always.</p><p>Structurally: every one of them <b>moves the decision outside the moment</b> — made in advance, enforced somewhere you cannot reach while the loss is happening.</p>"},
{"i":"x-25-1","v":"25","s":"25-1-quarter-1-foundations-and-the-data-layer","q":"Quarter 1 forbids all strategy work. Give the objective and the two-part justification.","a":"<p>Objective: <b>a correct point-in-time data store and a backtester you trust</b>. Nothing else.</p><p>Justified twice over: everything after this quarter is <b>worthless if this quarter is wrong</b> — a bad data layer invalidates every result built on it, silently — and nothing in it <b>depends on the market cooperating</b>, so it is the one quarter whose success is entirely under your control.</p>"},
{"i":"x-25-3","v":"25","s":"25-3-quarter-3-live-at-small-size-and-deeper-researc","q":"Weeks 29–30 go live at minimum size for two weeks with nothing changed. What are you measuring, and what are the three specific reactions to watch for?","a":"<p>You are measuring <b>yourself, not the strategy</b>: two weeks cannot say anything about edge, but they say everything about behaviour. Journal the reactions daily — not the P&amp;L, the reactions.</p><p>Watch for: <b>checking positions outside your scheduled session</b>; <b>wanting to adjust a parameter after a losing day</b>; <b>feeling a loss as a statement about you</b> rather than about variance. If discomfort is severe at a size that does not matter financially, that is cheap, important information — and the response is to <b>reduce size and repeat</b>, not to push through.</p>"},
{"i":"x-25-4","v":"25","s":"25-4-quarter-4-consolidate-or-specialise","q":"Quarter 4 offers two paths and forbids attempting both. Name them, and say what the choice should actually be made on.","a":"<p><b>Deepen the existing book</b> — more capacity, better execution, a third signal — or <b>build the evidence for a role</b>: a public research artefact, competition results, an interview-ready body of work.</p><p>They are genuinely different, and splitting effort produces a book too small to matter and a portfolio too thin to hire on. Decide from what the first three quarters actually revealed — <b>your measured results and your measured behaviour</b>, not which outcome you would prefer.</p>"},
{"i":"x-25-5","v":"25","s":"25-5-what-is-deliberately-excluded","q":"Which kinds of material does the twelve-month plan deliberately exclude, and what is the general principle behind every exclusion?","a":"<p>Anything whose prerequisites you will not have, or whose payoff requires infrastructure or capital you will not have: low-latency systems, options market making, most deep learning, and the deeper extension volumes (2A, 4A, 8A, 10A, 11A, 12A) until the volume they extend is actually working.</p><p>The principle: <b>a curriculum is defined by what it leaves out</b>. Time spent on material you cannot yet act on is time not spent on the data layer, the costs and the risk controls that decide whether anything survives.</p>"},
{"i":"x-26-3","v":"26","s":"26-3-the-laboratory","q":"What does the Forge laboratory run on, and what does it persist between visits — and why is that last item the important one?","a":"<p>Everything runs <b>in the page</b>: nothing uploaded, nothing fetched. It persists your configuration and, critically, your <b>trial count</b>.</p><p>The trial counter is the point. Ten steps take you from a first run to an exported Python file, and the counter rises as you go — so the number of things you tried is recorded <em>while</em> you try them, rather than being reconstructed afterwards by a person with an interest in the answer.</p>"},
{"i":"x-26-8a","v":"26","s":"26-8-fifteen-things-to-build-in-order","q":"The first three Forge exercises are: vary only the seed eight times; set the world to a random walk and tune until Sharpe &gt; 0.5; run a sweep on a signal that cannot know anything. What is each designed to teach?","a":"<p><b>1 — the error bar.</b> The spread of Sharpes across seeds is the uncertainty a single backtest never shows, and it is usually wider than the effect you are chasing.</p><p><b>2 — manufacture.</b> How little effort it takes to produce a result from a market containing nothing at all.</p><p><b>3 — your floor.</b> A signal that cannot know anything still reaches Sharpe above 0.6 somewhere across sixty-three cells. That number is the bar any real result must clear.</p>"},
{"i":"x-26-8b","v":"26","s":"26-8-fifteen-things-to-build-in-order","q":"Two of the fifteen exercises produce a diagnostic you should recognise on sight afterwards. Name the lookahead signature, and name what happens to a reversal signal at four basis points.","a":"<p><b>Lookahead signature</b>: Sharpe above 5 with a drawdown near 3%. That pair is not a good strategy, it is a bug — a signal computed with information the position could not have had.</p><p><b>Costs</b>: a short-horizon reversal with a gross Sharpe above 1 goes <b>negative net</b> at four basis points. This is the actual reason most published anomalies are untradeable, and the fix (smoothing with an EMA) trades gross edge for turnover until net stops improving.</p>"}
]
;window.__CARDS__=window.__CARDS__.concat(window.__NEWCARDS__);
